    nonisolated static func steeringDebugLog(_ message: @autoclosure () -> String) {
        #if DEBUG
            guard UserDefaults.standard.bool(forKey: "enableSteeringDebugLogging") else { return }
            print(message())
        #endif
    }

    nonisolated static func logCodexDebug(_ message: @autoclosure () -> String) {
        CodexDebugLog.log(message())
    }

    nonisolated static func shouldStartRemoteTurn(
        runState: AgentSessionRunState,
        remoteSessionID: String?
    ) -> Bool {
        guard let remoteSessionID,
              !remoteSessionID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        else {
            return true
        }
        switch runState {
        case .failed, .cancelled:
            return true
        case .idle, .running, .waitingForUser, .waitingForQuestion, .waitingForApproval, .completed:
            return false
        }
    }

