    func selectModel(rawModel: String) {
        selectedModelRaw = rawModel
    }

    func selectRemoteAgentModel(rawModel: String) {
        guard let session = activeSession,
              session.remoteHost != nil
        else {
            selectModel(rawModel: rawModel)
            return
        }
        let agent = RemoteHostAgentCatalog.agentKind(forModelID: rawModel) ?? session.selectedAgent
        let reasoningEffort = remoteHostCatalog.cachedCatalog(for: session.remoteHost?.hostID ?? "")?
            .reasoningEffort(forModelID: rawModel)
        isRestoringState = true
        selectedAgent = agent
        selectedModelRaw = rawModel
        selectedReasoningEffortRaw = reasoningEffort
        isRestoringState = false
        session.selectedAgent = agent
        session.selectedModelRaw = rawModel
        session.selectedReasoningEffortRaw = reasoningEffort
        session.isDirty = true
        updatePermissionBindingState(from: session)
        scheduleSave(for: session.tabID)
        syncComposerUIState(tabID: session.tabID)
        syncRuntimeMetricsUIState()
        syncRunInteractionUIState()
    }

    func remoteHostCatalogSnapshot(for session: AgentTabSession?) -> RemoteHostAgentCatalog? {
        guard let hostID = session?.remoteHost?.hostID else { return nil }
        guard remoteHostRegistry.hasHosts else { return nil }
        if let cached = remoteHostCatalog.cachedCatalog(for: hostID) {
            return cached
        }
        loadRemoteHostCatalogIfNeeded(hostID: hostID)
        return .degraded
    }

    /// Called when a remote host connection transitions to connected: a degraded
    /// catalog cached before the connection existed (e.g. list_agents refused or
    /// unreachable) is stale the moment the channel is up — drop it and reload so
    /// the remote model picker populates without waiting for the TTL.
    func refreshRemoteHostCatalogAfterConnect(hostID: String) {
        remoteCatalogLoadTasksByHostID.removeValue(forKey: hostID)?.cancel()
        if remoteHostCatalog.cachedCatalog(for: hostID)?.isDegraded == true {
            remoteHostCatalog.invalidate(hostID: hostID)
        }
        loadRemoteHostCatalogIfNeeded(hostID: hostID)
    }

    func loadRemoteHostCatalogIfNeeded(hostID: String) {
        guard remoteHostRegistry.hasHosts,
              remoteHostCatalog.cachedCatalog(for: hostID) == nil,
              remoteCatalogLoadTasksByHostID[hostID] == nil
        else { return }
        remoteCatalogLoadTasksByHostID[hostID] = Task { @MainActor [weak self] in
            guard let self else { return }
            _ = await remoteHostCatalog.catalog(for: hostID)
            guard !Task.isCancelled else { return }
            remoteCatalogLoadTasksByHostID[hostID] = nil
            syncComposerUIState()
        }
    }

    #if DEBUG
        func test_resetRemoteCatalogLoadState(hostID: String) {
            remoteCatalogLoadTasksByHostID.removeValue(forKey: hostID)?.cancel()
            remoteHostCatalog.invalidate(hostID: hostID)
        }

        func test_hasRemoteCatalogLoadTask(hostID: String) -> Bool {
            remoteCatalogLoadTasksByHostID[hostID] != nil
        }
    #endif

    @discardableResult
    func materializeRemoteChildSession(
        _ descriptor: RemoteAgentSessionDescriptor,
        parentSession: AgentTabSession,
        parentRemoteHost: AgentSessionRemoteHostBinding
    ) async -> AgentTabSession? {
        let childRemoteSessionID = descriptor.sessionID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let childSessionID = UUID(uuidString: childRemoteSessionID),
              let parentLocalSessionID = parentSession.activeAgentSessionID
        else { return nil }

        if let existing = sessions.values.first(where: { session in
            session.remoteHost?.hostID == parentRemoteHost.hostID
                && session.remoteHost?.remoteSessionID == childRemoteSessionID
        }) {
            configureMaterializedRemoteChildSession(
                existing,
                sessionID: existing.activeAgentSessionID ?? childSessionID,
                descriptor: descriptor,
                childRemoteSessionID: childRemoteSessionID,
                parentLocalSessionID: parentLocalSessionID,
                parentTabID: parentSession.tabID,
                parentRemoteHost: parentRemoteHost,
                isNewMaterialization: false
            )
            return existing
        }

        if case let .unique(existingTabID) = persistentBindingResolution(for: childSessionID) {
            guard let existing = try? await ensureSessionReady(tabID: existingTabID) else {
                return nil
            }
            if existing.activeAgentSessionID != childSessionID {
                guard installPersistentSessionBinding(
                    sessionID: childSessionID,
                    on: existing,
                    updateWorkspaceMetadata: true,
                    invalidateAsyncWork: true
                )?.sessionID == childSessionID else { return nil }
                // Rebound to the child's durable session: adopt its on-disk incarnation (transcript
                // and persistence state from one paired load) instead of declaring it loaded. A
                // hydration rejected by a binding, ownership, or workspace change configures nothing.
                guard await hydrateMaterializedRemoteSession(existing).isReadyForRemoteConfiguration else {
                    return nil
                }
            } else {
                existing.hasLoadedPersistedState = true
            }
            configureMaterializedRemoteChildSession(
                existing,
                sessionID: childSessionID,
                descriptor: descriptor,
                childRemoteSessionID: childRemoteSessionID,
                parentLocalSessionID: parentLocalSessionID,
                parentTabID: parentSession.tabID,
                parentRemoteHost: parentRemoteHost,
                isNewMaterialization: false
            )
            return existing
        }

        guard let promptManager,
              let createdTab = await promptManager.createBackgroundComposeTab(
                  strategy: .blank,
                  name: Self.remoteChildSessionName(descriptor.name),
                  capacityPolicy: .mcpBackgroundAgent
              )
        else { return nil }

        guard let childSession = session(for: createdTab.id, createIfNeeded: true) else {
            await promptManager.closeComposeTab(createdTab.id)
            return nil
        }
        guard installPersistentSessionBinding(
            sessionID: childSessionID,
            on: childSession,
            updateWorkspaceMetadata: true,
            invalidateAsyncWork: true
        )?.sessionID == childSessionID else { return nil }
        // A file for this deterministic id may already exist (earlier materialization whose tab
        // was closed): the paired load adopts it; an absent file leaves genuine initial creation.
        // A rejected hydration (rebound, closed, or workspace change while suspended) configures
        // nothing and never declares the tab loaded.
        guard await hydrateMaterializedRemoteSession(childSession).isReadyForRemoteConfiguration else {
            return nil
        }
        configureMaterializedRemoteChildSession(
            childSession,
            sessionID: childSessionID,
            descriptor: descriptor,
            childRemoteSessionID: childRemoteSessionID,
            parentLocalSessionID: parentLocalSessionID,
            parentTabID: parentSession.tabID,
            parentRemoteHost: parentRemoteHost,
            isNewMaterialization: true
        )
        return childSession
    }

    @discardableResult
    func materializeRemoteWorkspaceSession(
        descriptor: RemoteAgentSessionDescriptor,
        hostRecord: PairedHostRecord
    ) async -> AgentTabSession? {
        let remoteSessionID = descriptor.sessionID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let localSessionID = UUID(uuidString: remoteSessionID),
              !remoteCoordinator.localSessionExists(hostID: hostRecord.id, remoteSessionID: remoteSessionID),
              let promptManager,
              let createdTab = await promptManager.createBackgroundComposeTab(
                  strategy: .blank,
                  name: Self.remoteChildSessionName(descriptor.name)
              )
        else { return nil }

        guard let session = session(for: createdTab.id, createIfNeeded: true) else {
            await promptManager.closeComposeTab(createdTab.id)
            return nil
        }
        guard installPersistentSessionBinding(
            sessionID: localSessionID,
            on: session,
            updateWorkspaceMetadata: true,
            invalidateAsyncWork: true
        )?.sessionID == localSessionID else {
            await promptManager.closeComposeTab(createdTab.id)
            return nil
        }
        // The deterministic local id may already have a file (a previous pickup whose tab was
        // closed): adopt that incarnation through the paired load before configuring from the
        // descriptor; an absent file leaves genuine initial creation for the first save. The
        // hydration suspends: if the tab was rebound, closed, or the workspace changed meanwhile,
        // nothing below may be written onto whatever the tab now represents. The tab is left as
        // is (never closed here: closing deletes the backing file of its current binding).
        guard await hydrateMaterializedRemoteSession(session).isReadyForRemoteConfiguration,
              sessions[createdTab.id] === session,
              session.activeAgentSessionID == localSessionID
        else {
            return nil
        }

        let sessionName = Self.remoteChildSessionName(descriptor.name)
        renameSession(tabID: session.tabID, to: sessionName)
        session.remoteHost = AgentSessionRemoteHostBinding(
            hostID: hostRecord.id,
            hostDisplayName: hostRecord.displayName,
            remoteSessionID: remoteSessionID
        )
        session.parentSessionID = nil
        session.runState = Self.remoteChildRunState(from: descriptor.stateRaw)
        if let agentKindRaw = descriptor.agentKindRaw?.trimmingCharacters(in: .whitespacesAndNewlines),
           let agentKind = AgentProviderKind(rawValue: agentKindRaw)
        {
            session.selectedAgent = agentKind
        }
        if let modelRaw = descriptor.agentModelRaw?.trimmingCharacters(in: .whitespacesAndNewlines),
           !modelRaw.isEmpty
        {
            session.selectedModelRaw = modelRaw
        }
        // Deliberately preserve the new tab's local `.user` origin. Host provenance
        // is display-only metadata from the catalog, not local session ownership.
        session.hasLoadedPersistedState = true
        session.isDirty = true
        session.lastActivityAt = descriptor.lastModified ?? Date()

        upsertSessionIndex(
            sessionID: localSessionID,
            tabID: session.tabID,
            name: sessionName,
            lastUserMessageAt: nil,
            savedAt: session.lastActivityAt,
            lastRunStateRaw: session.runState.rawValue,
            itemCount: descriptor.itemCount ?? 0,
            agentKindRaw: session.selectedAgent.rawValue,
            agentModelRaw: session.selectedModelRaw,
            agentReasoningEffortRaw: session.selectedReasoningEffortRaw,
            autoEditEnabled: session.autoEditEnabled,
            parentSessionID: nil,
            isMCPOriginated: false,
            origin: session.origin,
            worktreeBindingSummaries: session.worktreeBindings.worktreeBindingSummaries,
            remoteHostID: hostRecord.id,
            remoteHostName: hostRecord.displayName,
            remoteSessionID: remoteSessionID,
            activeWorktreeMergeSummaries: session.worktreeMergeOperations.activeWorktreeMergeSummaries
        )
        updateBindingsFromSession(session)
        requestUIRefresh(tabID: session.tabID, urgent: false)
        scheduleSave(for: session.tabID)
        await promptManager.switchComposeTab(session.tabID)
        return session
    }

    /// Outcome of the paired hydration that precedes remote configuration of a materialized tab.
    enum MaterializedRemoteHydrationOutcome: Equatable {
        /// An existing incarnation was adopted: transcript and persistence state from one paired load.
        case adoptedExisting
        /// No file exists for the bound id: the tab is a genuine creator; its first save creates the file.
        case creator
        /// The binding, session object, or workspace changed while the load was suspended, or the
        /// load did not complete: nothing was adopted and the caller must not configure the tab.
        case rejected

        var isReadyForRemoteConfiguration: Bool {
            self != .rejected
        }
    }

    /// Runs the real persisted hydration for a tab that was just bound to a remote-derived durable
    /// session id. When a file exists, transcript and persistence state are adopted from the same
    /// gate-held load (later saves target that incarnation); when none exists, the tab stays a
    /// never-persisted owner and its first save creates the file. The binding, session object,
    /// and workspace captured before the load are revalidated after it: a rejected hydration
    /// reports `.rejected`, leaves a still-bound tab unresolved (never loaded without authority),
    /// and never touches a tab that now represents another session.
    @discardableResult
    func hydrateMaterializedRemoteSession(_ session: AgentTabSession) async -> MaterializedRemoteHydrationOutcome {
        guard let sessionID = session.activeAgentSessionID else { return .rejected }
        let tabID = session.tabID
        let expectedBinding = session.persistentSessionBindingIdentity
        let expectedTransitionGeneration = session.bindingTransitionGeneration
        let expectedWorkspaceID = (persistenceWorkspace ?? lastKnownWorkspaceSnapshot)?.id
        session.hasLoadedPersistedState = false
        // Operation-owned outcome: the awaited load's own result, never session state that an
        // obsolete load for a previous binding could have written.
        let outcome = await loadSessionFromDisk(for: session)
        guard sessions[tabID] === session,
              session.activeAgentSessionID == sessionID,
              session.persistentSessionBindingIdentity == expectedBinding,
              session.bindingTransitionGeneration == expectedTransitionGeneration,
              !session.bindingTransitionInProgress
        else {
            // The tab now represents something else (or nothing): its state belongs to that binding.
            return .rejected
        }
        // Attempt identity: a load cancelled or superseded without a binding change (for example
        // by a removal operation that was then vetoed) is obsolete. Its caller reports
        // `.rejected` but must not change the current attempt's readiness or outcome.
        guard let attemptID = outcome.attemptID, session.currentPersistedLoadAttemptID == attemptID else {
            return .rejected
        }
        guard (persistenceWorkspace ?? lastKnownWorkspaceSnapshot)?.id == expectedWorkspaceID else {
            session.hasLoadedPersistedState = false
            return .rejected
        }
        switch outcome.disposition {
        case .applied:
            guard session.hasLoadedPersistedState,
                  session.persistedIncarnationSessionID == sessionID,
                  session.persistenceState(for: sessionID) != nil
            else {
                session.hasLoadedPersistedState = false
                return .rejected
            }
            return .adoptedExisting
        case .noPayload, .suppressed:
            guard session.hasLoadedPersistedState, session.persistenceState == nil else {
                session.hasLoadedPersistedState = false
                return .rejected
            }
            return .creator
        case .unbound, .unresolved, .failed:
            // Stale, cancelled, or failed load: a persisted incarnation is never declared loaded
            // without its paired authority; the tab stays unresolved for a later hydration.
            session.hasLoadedPersistedState = false
            return .rejected
        }
    }

    private func configureMaterializedRemoteChildSession(
        _ session: AgentTabSession,
        sessionID: UUID,
        descriptor: RemoteAgentSessionDescriptor,
        childRemoteSessionID: String,
        parentLocalSessionID: UUID,
        parentTabID: UUID,
        parentRemoteHost: AgentSessionRemoteHostBinding,
        isNewMaterialization: Bool
    ) {
        let childName = Self.remoteChildSessionName(descriptor.name)
        let currentName = resolvedSessionDisplayName(for: session.tabID)
        if isNewMaterialization
            || AgentSessionTitleNaming.isDefaultSessionTitle(currentName)
            || currentName == "Agent Session"
        {
            renameSession(tabID: session.tabID, to: childName)
        }

        session.remoteHost = AgentSessionRemoteHostBinding(
            hostID: parentRemoteHost.hostID,
            hostDisplayName: parentRemoteHost.hostDisplayName,
            remoteSessionID: childRemoteSessionID
        )
        session.parentSessionID = parentLocalSessionID
        if isNewMaterialization || !session.runState.isTerminalForCommit {
            session.runState = Self.remoteChildRunState(from: descriptor.stateRaw)
        }
        if let agentKindRaw = descriptor.agentKindRaw?.trimmingCharacters(in: .whitespacesAndNewlines),
           let agentKind = AgentProviderKind(rawValue: agentKindRaw)
        {
            session.selectedAgent = agentKind
        }
        if let modelRaw = descriptor.agentModelRaw?.trimmingCharacters(in: .whitespacesAndNewlines),
           !modelRaw.isEmpty
        {
            session.selectedModelRaw = modelRaw
        }
        session.hasLoadedPersistedState = true
        session.isDirty = true
        session.lastActivityAt = Date()

        upsertSessionIndex(
            sessionID: sessionID,
            tabID: session.tabID,
            name: resolvedSessionDisplayName(for: session.tabID),
            lastUserMessageAt: session.lastUserMessageAt,
            savedAt: session.lastActivityAt,
            lastRunStateRaw: session.runState.rawValue,
            itemCount: max(session.transcriptCanonicalVisibleRowCount, session.items.count),
            agentKindRaw: session.selectedAgent.rawValue,
            agentModelRaw: session.selectedModelRaw,
            agentReasoningEffortRaw: session.selectedReasoningEffortRaw,
            autoEditEnabled: session.autoEditEnabled,
            parentSessionID: parentLocalSessionID,
            isMCPOriginated: session.isMCPOriginated,
            origin: session.origin,
            worktreeBindingSummaries: session.worktreeBindings.worktreeBindingSummaries,
            remoteHostID: parentRemoteHost.hostID,
            remoteHostName: parentRemoteHost.hostDisplayName,
            remoteSessionID: session.remoteHost?.normalizedRemoteSessionID,
            activeWorktreeMergeSummaries: session.worktreeMergeOperations.activeWorktreeMergeSummaries
        )
        updateBindingsFromSession(session)
        requestUIRefresh(tabID: session.tabID, urgent: false)
        requestUIRefresh(tabID: parentTabID, urgent: false)
        scheduleSave(for: session.tabID)
    }

    private static func remoteChildSessionName(_ rawName: String?) -> String {
        let trimmed = rawName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let candidate = trimmed.isEmpty ? "Agent Session" : trimmed
        return AgentSession.validatedName(candidate)
    }

    private static func remoteChildRunState(from rawState: String?) -> AgentSessionRunState {
        let trimmed = rawState?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if let state = AgentSessionRunState(rawValue: trimmed) {
            return state
        }
        let compact = trimmed
            .lowercased()
            .replacingOccurrences(of: "_", with: "")
            .replacingOccurrences(of: "-", with: "")
        switch compact {
        case "waitingforinput", "waitingforuser", "waitingforquestion", "waitingforapproval":
            return .waitingForUser
        case "running":
            return .running
        case "completed":
            return .completed
        case "cancelled", "canceled":
            return .cancelled
        case "failed", "expired":
            return .failed
        default:
            return .idle
        }
    }

    /// Persist the last-used model for a given agent to UserDefaults.
    private static func persistModelForAgent(agentRaw: String, modelRaw: String) {
        var dict = UserDefaults.standard.dictionary(forKey: lastUsedModelsByAgentKey) as? [String: String] ?? [:]
        dict[agentRaw] = modelRaw
        UserDefaults.standard.set(dict, forKey: lastUsedModelsByAgentKey)
    }

    /// Read the last-used model for a given agent from UserDefaults.
    private static func lastUsedModelRaw(forAgentRaw agentRaw: String) -> String? {
        let dict = UserDefaults.standard.dictionary(forKey: lastUsedModelsByAgentKey) as? [String: String]
        return dict?[agentRaw]
    }

    private func restoreLastUsedAgentSelectionIfNeeded() {
        guard let savedAgentRaw = UserDefaults.standard.string(forKey: Self.lastUsedAgentKey) else { return }
        let savedModelRaw = Self.lastUsedModelRaw(forAgentRaw: savedAgentRaw)
        let normalized = normalizedSelection(
            agentRaw: savedAgentRaw,
            modelRaw: savedModelRaw,
            preserveUnavailableAgent: true
        )
        isRestoringState = true
        selectedAgent = normalized.agent
        selectedModelRaw = normalized.modelRaw
        isRestoringState = false
    }

    private func persistLastUsedModelIfNeeded(agent: AgentProviderKind, modelRaw: String) {
        guard usesProductionAgentDefaultsAndModelPolling else { return }
        guard shouldPersistLastUsedModel(agent: agent, modelRaw: modelRaw) else { return }
        Self.persistModelForAgent(agentRaw: agent.rawValue, modelRaw: modelRaw)
    }

    private func shouldPersistLastUsedModel(agent: AgentProviderKind, modelRaw: String) -> Bool {
        true
    }

    func selectReasoningEffort(_ effort: CodexReasoningEffort?) {
        selectedReasoningEffortRaw = effort?.rawValue
    }

