    private func currentWorkspaceSnapshot(for owner: SessionIndexOwner) -> WorkspaceModel? {
        if let workspace = workspaceManager?.activeWorkspace,
           workspace.id == owner.workspaceID
        {
            return workspace
        }
        if let workspace = lastKnownWorkspaceSnapshot,
           workspace.id == owner.workspaceID
        {
            return workspace
        }
        return nil
    }

    // MARK: - Workspace Handling

    private func prepareWorkspaceSwitchSessionDiscard(
        _ session: AgentTabSession,
        reason: String
    ) -> WorkspaceSwitchSessionCleanupTarget {
        let target = WorkspaceSwitchSessionCleanupTarget(
            tabID: session.tabID,
            session: session,
            boundSessionID: boundSessionID(for: session.tabID),
            runID: session.runID
        )
        removePendingUIRefresh(for: session.tabID)
        cancelPersistedLoad(for: session)
        // The workspace switch was confirmed upstream (its sheet listed unsaved conversations).
        session.invalidateStaleResetRecoveryForLifecycle()
        // cancelEphemeralRuntimeState() cancels and nils agentTask before the
        // graceful cancelAgentRun() call in handleWorkspaceSwitch. See
        // prepareSessionForWindowClose for why this ordering is safe.
        // The conversation is retained, so buffered assistant text is applied, not discarded.
        session.drainPendingAssistantDelta()
        session.cancelEphemeralRuntimeState()
        clearPendingAssistantDelta(session)
        cancelPendingQuestion(for: session)
        cancelPendingApproval(for: session)
        reconcileInteractiveRunState(session)
        cancelPendingInstruction(for: session)
        if let runID = session.runID {
            _ = mcpRunToolCanceller(runID, "workspace_switch")
        }
        remoteCoordinator.stop(tabID: session.tabID)
        // The new workspace's owner is already installed and this session is discarded next, so
        // the drain above is memory-only; no timer may save it later under another context.
        cancelTranscriptSaveTimers(session)
        return target
    }

    func handleWorkspaceSwitch(_ workspace: WorkspaceModel?) async {
        let owner = sessionIndexStore.receiveWorkspaceSwitchNotification(workspace)
        await handleWorkspaceSwitch(workspace, owner: owner)
    }

    private func handleWorkspaceSwitch(
        _ workspace: WorkspaceModel?,
        owner: SessionIndexOwner
    ) async {
        guard sessionIndexStore.isWorkspaceActivationCurrent(owner, workspace: workspace) else { return }
        lastKnownWorkspaceSnapshot = workspace
        installSessionIndexOwner(owner, workspace: workspace)
        guard sessionIndexStore.isOwnerCurrent(owner) else { return }
        #if DEBUG
            let workspaceSwitchStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
            let workspaceSwitchInitialSessions = sessions.count
            let workspaceSwitchInitialActiveTabID = workspace?.activeComposeTabID
            WorkspaceRestorePerfLog.event(
                "agentMode.workspaceSwitch.begin",
                fields: [
                    "windowID": "\(windowID)",
                    "workspaceID": WorkspaceRestorePerfLog.shortID(workspace?.id),
                    "hasWorkspace": "\(workspace != nil)",
                    "sessionsBefore": "\(workspaceSwitchInitialSessions)",
                    "activeTabID": WorkspaceRestorePerfLog.shortID(workspaceSwitchInitialActiveTabID),
                    "isSystemWorkspace": "\(workspace?.isSystemWorkspace ?? false)"
                ]
            )
        #endif
        if workspace?.isSystemWorkspace == false {
            finishInitialSystemWorkspaceSessionListRefreshDeferral(refreshIfStillSystem: false)
        }
        let initialActiveTabID = workspace?.activeComposeTabID
        workspaceSwitchInFlight = workspace != nil
        activeSessionLoadInProgressTabID = initialActiveTabID
        if workspace != nil {
            publishLoadingTranscriptPresentation(tabID: initialActiveTabID)
        }
        stopOpenCodeModelsSubscription()
        stopCursorModelsSubscription()
        sidebarAutoArchiveTask?.cancel()
        sidebarAutoArchiveTask = nil
        uiRefreshTask?.cancel()
        uiRefreshTask = nil
        pendingUIRefreshScopesByTabID.removeAll()
        pendingAssistantPresentationByTabID.removeAll()

        #if DEBUG
            let teardownStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
            let teardownSessionCount = sessions.count
        #endif
        let cleanupTargets = sessions.values.map {
            prepareWorkspaceSwitchSessionDiscard(
                $0,
                reason: "Cancelled due to workspace switch"
            )
        }
        for session in sessions.values where session.runState.isActive {
            await cancelAgentRun(tabID: session.tabID, cause: .ordinary)
        }
        claudeCoordinator.detachAllClaudeToolTrackingHandlersForWorkspaceSwitch()
        codexCoordinator.stop()
        claudeCoordinator.stop()
        for sessionID in Set(cleanupTargets.compactMap(\.boundSessionID)) {
            await releaseSessionWorktreeOwnership(sessionID: sessionID)
        }
        #if DEBUG
            WorkspaceRestorePerfLog.event(
                "agentMode.workspaceSwitch.discardPrepared",
                fields: [
                    "windowID": "\(windowID)",
                    "workspaceID": WorkspaceRestorePerfLog.shortID(workspace?.id),
                    "sessionCount": "\(teardownSessionCount)",
                    "duration": teardownStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured"
                ]
            )
            let clearStateStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
        #endif
        pendingRemoteStartWindowPicker = nil
        sessions.removeAll()
        lastProcessedTabID = nil
        if workspace == nil {
            workspaceSwitchInFlight = false
            clearBindings()
        }
        tabsWithActiveAgentRun.removeAll()
        mcpControlledTabIDs.removeAll()
        tabDraftText.removeAll()
        sidebarObservedRunStateByTabID.removeAll()
        await applyEditsApprovalStore.cleanupWindowScopes(
            windowID: windowID,
            reason: "Cancelled due to workspace switch"
        )
        workspaceSwitchProvider.scheduleBackgroundCleanup(
            targets: cleanupTargets,
            reason: "workspace_switch"
        )
        guard sessionIndexStore.isWorkspaceActivationCurrent(owner, workspace: workspace),
              sessionIndexStore.isOwnerCurrent(owner)
        else {
            return
        }
        #if DEBUG
            WorkspaceRestorePerfLog.event(
                "agentMode.workspaceSwitch.clearState",
                fields: [
                    "windowID": "\(windowID)",
                    "workspaceID": WorkspaceRestorePerfLog.shortID(workspace?.id),
                    "duration": clearStateStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured"
                ]
            )
        #endif
        scheduleSkillCatalogRefresh()

        guard let workspace else {
            activeSessionLoadInProgressTabID = nil
            #if DEBUG
                WorkspaceRestorePerfLog.event(
                    "agentMode.workspaceSwitch.end",
                    fields: [
                        "windowID": "\(windowID)",
                        "workspaceID": WorkspaceRestorePerfLog.shortID(nil),
                        "outcome": "noWorkspace",
                        "duration": workspaceSwitchStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured"
                    ]
                )
            #endif
            return
        }
        refreshSessionListCache(for: workspace, owner: owner)
        #if DEBUG
            WorkspaceRestorePerfLog.event(
                "agentMode.workspaceSwitch.refreshScheduled",
                fields: [
                    "windowID": "\(windowID)",
                    "workspaceID": WorkspaceRestorePerfLog.shortID(workspace.id),
                    "activeTabID": WorkspaceRestorePerfLog.shortID(workspace.activeComposeTabID),
                    "frozenOrderTabs": "\(sidebarRestoreFrozenOrderByTabID.count)"
                ]
            )
        #endif
        let resolvedActiveTabID = workspace.activeComposeTabID
        if let resolvedActiveTabID {
            activeSessionLoadInProgressTabID = resolvedActiveTabID
            onTabChanged(resolvedActiveTabID, allowDuringWorkspaceSwitch: true)
            #if DEBUG
                WorkspaceRestorePerfLog.event(
                    "agentMode.workspaceSwitch.end",
                    fields: [
                        "windowID": "\(windowID)",
                        "workspaceID": WorkspaceRestorePerfLog.shortID(workspace.id),
                        "outcome": "activeTabChanged",
                        "duration": workspaceSwitchStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured"
                    ]
                )
            #endif
            return
        }
        activeSessionLoadInProgressTabID = nil
        if workspace.composeTabs.isEmpty {
            workspaceSwitchInFlight = false
            clearBindings()
            #if DEBUG
                WorkspaceRestorePerfLog.event(
                    "agentMode.workspaceSwitch.end",
                    fields: [
                        "windowID": "\(windowID)",
                        "workspaceID": WorkspaceRestorePerfLog.shortID(workspace.id),
                        "outcome": "emptyWorkspace",
                        "duration": workspaceSwitchStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured"
                    ]
                )
            #endif
        } else {
            setActiveTranscriptBindingsHydrated(true)
            #if DEBUG
                WorkspaceRestorePerfLog.event(
                    "agentMode.workspaceSwitch.end",
                    fields: [
                        "windowID": "\(windowID)",
                        "workspaceID": WorkspaceRestorePerfLog.shortID(workspace.id),
                        "outcome": "bindingsHydrated",
                        "duration": workspaceSwitchStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured"
                    ]
                )
            #endif
        }
    }

    private func persistedSidebarTabs(for workspace: WorkspaceModel) -> [ComposeTabState] {
        let activeTabIDs = Set(workspace.composeTabs.map(\.id))
        return workspace.composeTabs + workspace.stashedTabs.map(\.tab)
            .filter { !activeTabIDs.contains($0.id) }
    }

    private func invalidateSidebarRestoreOrdering() {
        sessionIndexStore.invalidateSidebarRestoreOrdering()
    }

    nonisolated static func shouldSkipSessionListCacheRefresh(
        for workspace: WorkspaceModel,
        isInitialSystemWorkspaceRefreshDeferred: Bool
    ) -> Bool {
        workspace.isSystemWorkspace && isInitialSystemWorkspaceRefreshDeferred
    }

    private func refreshSessionListCache(
        for workspace: WorkspaceModel,
        owner explicitOwner: SessionIndexOwner? = nil
    ) {
        guard let owner = explicitOwner ?? sessionIndexOwner,
              owner.workspaceID == workspace.id,
              sessionIndexStore.isOwnerCurrent(owner)
        else {
            return
        }

        #if DEBUG
            let requestBuildStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
        #endif
        let persistedTabs = persistedSidebarTabs(for: workspace)
        var tabNameByID: [UUID: String] = [:]
        tabNameByID.reserveCapacity(persistedTabs.count)
        for tab in persistedTabs {
            tabNameByID[tab.id] = tab.name
        }
        let validTabIDs = Set(tabNameByID.keys)
        var boundSessionIDByTabID: [UUID: UUID] = [:]
        boundSessionIDByTabID.reserveCapacity(persistedTabs.count)
        for tab in persistedTabs {
            if let activeAgentSessionID = tab.activeAgentSessionID {
                boundSessionIDByTabID[tab.id] = activeAgentSessionID
            }
        }
        for session in sessions.values where validTabIDs.contains(session.tabID) {
            if let sessionID = session.activeAgentSessionID {
                boundSessionIDByTabID[session.tabID] = sessionID
            } else {
                boundSessionIDByTabID.removeValue(forKey: session.tabID)
            }
        }
        let prioritizedTabID = workspace.activeComposeTabID
        let fullRequest = AgentSessionSidebarBuildRequest(
            workspace: workspace,
            tabNameByID: tabNameByID,
            validTabIDs: validTabIDs,
            boundSessionIDByTabID: boundSessionIDByTabID,
            prioritizedTabID: nil
        )
        #if DEBUG
            WorkspaceRestorePerfLog.event(
                "agentSessionIndex.requestBuilt",
                fields: [
                    "windowID": "\(windowID)",
                    "workspaceID": WorkspaceRestorePerfLog.shortID(workspace.id),
                    "activationEpoch": "\(owner.activationEpoch)",
                    "duration": requestBuildStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured",
                    "persistedTabs": "\(persistedTabs.count)",
                    "validTabs": "\(validTabIDs.count)",
                    "boundSessions": "\(boundSessionIDByTabID.count)",
                    "frozenOrderTabs": "\(ownerValidatedSidebarRestoreFrozenOrderByTabID.count)",
                    "hasPrioritizedTab": "\(prioritizedTabID != nil)",
                    "prioritizedTabID": WorkspaceRestorePerfLog.shortID(prioritizedTabID),
                    "isSystemWorkspace": "\(workspace.isSystemWorkspace)",
                    "deferralArmed": "\(initialSystemWorkspaceSessionListRefreshDeferralReason != nil)"
                ]
            )
        #endif

        cancelSessionIndexRefresh(releaseFrozenOrder: false, owner: owner)
        sessionListCacheGeneration &+= 1
        let token = SessionIndexRefreshToken(owner: owner, generation: sessionListCacheGeneration)
        activeSessionIndexRefreshToken = token
        activeSessionIndexRefreshWorkspace = workspace
        activeSessionIndexRefreshValidTabIDs = validTabIDs
        activeSessionIndexRefreshBoundSessionIDByTabID = boundSessionIDByTabID
        activeSessionIndexRefreshBaselineEntries = sessionIndex
        activeSessionIndexRefreshPrioritizedEntries.removeAll()
        activeSessionIndexRefreshFullEntries.removeAll()
        activeSessionIndexRefreshHasPublishedFullBatch = false
        sessionIndexStore.setSessionListCacheReady(false, for: owner)

        if Self.shouldSkipSessionListCacheRefresh(
            for: workspace,
            isInitialSystemWorkspaceRefreshDeferred: initialSystemWorkspaceSessionListRefreshDeferralReason != nil
        ) {
            completeSkippedSessionListCacheRefresh(
                for: workspace,
                token: token,
                reason: initialSystemWorkspaceSessionListRefreshDeferralReason ?? "initialSystemWorkspaceDeferred"
            )
            return
        }

        let prioritizedBuilder = sidebarPrioritizedIndexBuilder
        let streamBuilder = sidebarIndexStreamBuilder
        let restoreBatchSize = Self.sessionSidebarRestoreBatchSize
        sessionListCacheTask = Task.detached(priority: .userInitiated) { [weak self] in
            guard let self else { return }
            #if DEBUG
                let taskStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
                var prioritizedDurationMS: Double?
                var streamDurationMS: Double?
                var streamBatchCount = 0
                var streamEntryCount = 0
            #endif
            do {
                if let prioritizedTabID, let prioritizedTabName = tabNameByID[prioritizedTabID] {
                    let prioritizedBoundSessionIDByTabID = boundSessionIDByTabID[prioritizedTabID]
                        .map { [prioritizedTabID: $0] } ?? [:]
                    #if DEBUG
                        let prioritizedStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
                    #endif
                    let prioritizedResult = try await prioritizedBuilder(
                        AgentSessionSidebarBuildRequest(
                            workspace: workspace,
                            tabNameByID: [prioritizedTabID: prioritizedTabName],
                            validTabIDs: [prioritizedTabID],
                            boundSessionIDByTabID: prioritizedBoundSessionIDByTabID
                        )
                    )
                    #if DEBUG
                        if let prioritizedStartMS {
                            prioritizedDurationMS = WorkspaceRestorePerfLog.elapsedMS(since: prioritizedStartMS)
                        }
                    #endif
                    guard !Task.isCancelled else { return }
                    await applySidebarIndexBatch(
                        AgentSessionSidebarBuildBatch(
                            entriesBySessionID: prioritizedResult.entriesBySessionID,
                            preferredSessionIDByTabID: prioritizedResult.preferredSessionIDByTabID
                        ),
                        token: token,
                        isFullRefresh: false
                    )
                }
                await Task.yield()
                guard await notePrioritizedActiveSessionRestoreStatus(
                    token: token,
                    prioritizedTabID: prioritizedTabID
                ) else {
                    return
                }

                var streamRetryCount = 0
                while true {
                    do {
                        #if DEBUG
                            let streamStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
                        #endif
                        let stream = await streamBuilder(fullRequest, restoreBatchSize)
                        for try await batch in stream {
                            #if DEBUG
                                streamBatchCount += 1
                                streamEntryCount += batch.entriesBySessionID.count
                            #endif
                            guard !Task.isCancelled else { return }
                            await applySidebarIndexBatch(
                                batch,
                                token: token,
                                isFullRefresh: true
                            )
                        }
                        guard !Task.isCancelled else { return }
                        #if DEBUG
                            if let streamStartMS {
                                streamDurationMS = WorkspaceRestorePerfLog.elapsedMS(since: streamStartMS)
                            }
                        #endif
                        break
                    } catch {
                        guard !Task.isCancelled else { return }
                        guard streamRetryCount < Self.sessionSidebarRestoreRetryLimit,
                              await prepareSidebarIndexStreamRetry(token: token)
                        else {
                            throw error
                        }
                        streamRetryCount += 1
                        #if DEBUG
                            WorkspaceRestorePerfLog.log(
                                "agentSessionIndex.refreshRetry windowID=\(windowID) workspaceID=\(WorkspaceRestorePerfLog.shortID(workspace.id)) activationEpoch=\(owner.activationEpoch) generation=\(token.generation) retry=\(streamRetryCount) error=\(String(describing: error))"
                            )
                        #endif
                        await Task.yield()
                    }
                }
                #if DEBUG
                    if let taskStartMS {
                        WorkspaceRestorePerfLog.log(
                            "agentSessionIndex.refreshComplete windowID=\(windowID) workspaceID=\(WorkspaceRestorePerfLog.shortID(workspace.id)) activationEpoch=\(owner.activationEpoch) generation=\(token.generation) batches=\(streamBatchCount) streamEntries=\(streamEntryCount) retries=\(streamRetryCount) prioritized=\(prioritizedDurationMS.map(WorkspaceRestorePerfLog.formatMS) ?? "notRun") stream=\(streamDurationMS.map(WorkspaceRestorePerfLog.formatMS) ?? "notMeasured") total=\(WorkspaceRestorePerfLog.formatElapsedMS(since: taskStartMS))"
                        )
                    }
                #endif
                await applySidebarIndexCompletion(token: token)
            } catch {
                guard !Task.isCancelled else { return }
                #if DEBUG
                    if let taskStartMS {
                        WorkspaceRestorePerfLog.log(
                            "agentSessionIndex.refreshFailure windowID=\(windowID) workspaceID=\(WorkspaceRestorePerfLog.shortID(workspace.id)) activationEpoch=\(owner.activationEpoch) generation=\(token.generation) batches=\(streamBatchCount) streamEntries=\(streamEntryCount) total=\(WorkspaceRestorePerfLog.formatElapsedMS(since: taskStartMS)) error=\(String(describing: error))"
                        )
                    }
                #endif
                await applySidebarIndexFailure(token: token)
            }
        }
    }

    private func completeSkippedSessionListCacheRefresh(
        for workspace: WorkspaceModel,
        token: SessionIndexRefreshToken,
        reason: String
    ) {
        guard activeSessionIndexRefreshToken == token,
              sessionIndexStore.isOwnerCurrent(token.owner),
              workspace.id == token.owner.workspaceID
        else {
            return
        }
        activeSessionIndexRefreshBaselineEntries.removeAll()
        activeSessionIndexRefreshPrioritizedEntries.removeAll()
        activeSessionIndexRefreshFullEntries.removeAll()
        publishSessionIndexReplacement([:], token: token)
        sessionListCacheTask = nil
        activeSessionIndexRefreshToken = nil
        activeSessionIndexRefreshWorkspace = nil
        activeSessionIndexRefreshValidTabIDs.removeAll()
        activeSessionIndexRefreshBoundSessionIDByTabID.removeAll()
        activeSessionIndexRefreshHasPublishedFullBatch = false
        sessionIndexStore.setSessionListCacheReady(true, for: token.owner)
        sessionIndexStore.releaseSidebarRestoreFrozenOrder(for: token.owner)
        scheduledSendCoordinator?.workspaceDidLoad()
        #if DEBUG
            WorkspaceRestorePerfLog.log(
                "agentSessionIndex.refreshSkipped windowID=\(windowID) workspaceID=\(WorkspaceRestorePerfLog.shortID(workspace.id)) activationEpoch=\(token.owner.activationEpoch) generation=\(token.generation) reason=\(reason) managerInitialized=\(workspaceManager?.isInitialized == true) managerSwitching=\(workspaceManager?.isSwitchingWorkspace == true)"
            )
        #endif
    }

    private func shouldAcceptSidebarIndexEntry(_ entry: AgentSessionIndexEntry) -> Bool {
        switch persistentBindingResolution(for: entry.id) {
        case let .unique(tabID):
            return tabID == entry.tabID
        case .ambiguous:
            return false
        case .notFound:
            if let liveBinding = sessions[entry.tabID]?.activeAgentSessionID {
                return liveBinding == entry.id
            }
            if let workspaceBinding = workspaceManager?.activeAgentSessionID(forTabID: entry.tabID) {
                return workspaceBinding == entry.id
            }
            return true
        }
    }

    private func shouldAcceptSidebarIndexEntry(
        _ entry: AgentSessionIndexEntry,
        token: SessionIndexRefreshToken
    ) -> Bool {
        guard activeSessionIndexRefreshToken == token,
              sessionIndexStore.isOwnerCurrent(token.owner),
              activeSessionIndexRefreshValidTabIDs.contains(entry.tabID)
        else {
            return false
        }
        if let explicitSessionID = activeSessionIndexRefreshBoundSessionIDByTabID[entry.tabID] {
            return explicitSessionID == entry.id
        }
        if activeSessionIndexRefreshBoundSessionIDByTabID.contains(where: { tabID, sessionID in
            sessionID == entry.id && tabID != entry.tabID
        }) {
            return false
        }
        if let liveBinding = sessions[entry.tabID]?.activeAgentSessionID {
            return liveBinding == entry.id
        }
        return true
    }

    private func applySidebarIndexBatch(
        _ batch: AgentSessionSidebarBuildBatch,
        token: SessionIndexRefreshToken,
        isFullRefresh: Bool
    ) {
        #if DEBUG
            let applyStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
        #endif
        guard activeSessionIndexRefreshToken == token,
              sessionIndexStore.isOwnerCurrent(token.owner)
        else {
            return
        }
        var acceptedEntries: [UUID: AgentSessionIndexEntry] = [:]
        var updatedTabIDs: Set<UUID> = []
        for (sessionID, entry) in batch.entriesBySessionID
            where shouldAcceptSidebarIndexEntry(entry, token: token)
        {
            acceptedEntries[sessionID] = entry
            updatedTabIDs.insert(entry.tabID)
        }
        for tabID in batch.preferredSessionIDByTabID.keys
            where activeSessionIndexRefreshValidTabIDs.contains(tabID)
        {
            updatedTabIDs.insert(tabID)
        }

        if isFullRefresh {
            activeSessionIndexRefreshFullEntries.merge(acceptedEntries) { _, new in new }
            activeSessionIndexRefreshHasPublishedFullBatch = true
            var provisional = activeSessionIndexRefreshBaselineEntries
            provisional.merge(activeSessionIndexRefreshPrioritizedEntries) { _, new in new }
            provisional.merge(activeSessionIndexRefreshFullEntries) { _, new in new }
            publishSessionIndexReplacement(provisional, token: token)
        } else if !activeSessionIndexRefreshHasPublishedFullBatch {
            activeSessionIndexRefreshPrioritizedEntries.merge(acceptedEntries) { _, new in new }
            var provisional = activeSessionIndexRefreshBaselineEntries
            provisional.merge(activeSessionIndexRefreshPrioritizedEntries) { _, new in new }
            publishSessionIndexReplacement(provisional, token: token)
        }
        let resumeTriggered = resumePendingActiveSessionLoadIfNeeded(updatedTabIDs: updatedTabIDs)
        #if DEBUG
            WorkspaceRestorePerfLog.event(
                "agentSessionIndex.applyBatch",
                fields: [
                    "windowID": "\(windowID)",
                    "activationEpoch": "\(token.owner.activationEpoch)",
                    "generation": "\(token.generation)",
                    "isFullRefresh": "\(isFullRefresh)",
                    "entries": "\(batch.entriesBySessionID.count)",
                    "acceptedEntries": "\(acceptedEntries.count)",
                    "updatedTabs": "\(updatedTabIDs.count)",
                    "sessionIndexAfter": "\(sessionIndex.count)",
                    "resumeTriggered": "\(resumeTriggered)",
                    "total": applyStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured"
                ]
            )
        #endif
    }

    @discardableResult
    private func resumePendingActiveSessionLoadIfNeeded(updatedTabIDs: Set<UUID>) -> Bool {
        guard let targetTabID = activeSessionLoadInProgressTabID,
              updatedTabIDs.contains(targetTabID)
        else {
            return false
        }
        guard explicitActiveSessionID(for: targetTabID) != nil else {
            return false
        }
        guard workspaceManager?.isSwitchingWorkspace != true else {
            return false
        }
        lastProcessedTabID = nil
        onTabChanged(targetTabID)
        return true
    }

    private func prepareSidebarIndexStreamRetry(token: SessionIndexRefreshToken) -> Bool {
        guard activeSessionIndexRefreshToken == token,
              sessionIndexStore.isOwnerCurrent(token.owner)
        else {
            return false
        }

        activeSessionIndexRefreshFullEntries.removeAll()
        activeSessionIndexRefreshHasPublishedFullBatch = false
        var provisional = activeSessionIndexRefreshBaselineEntries
        provisional.merge(activeSessionIndexRefreshPrioritizedEntries) { _, new in new }
        publishSessionIndexReplacement(provisional, token: token)
        return true
    }

    private func applySidebarIndexCompletion(token: SessionIndexRefreshToken) {
        guard activeSessionIndexRefreshToken == token,
              sessionIndexStore.isOwnerCurrent(token.owner)
        else {
            return
        }
        publishSessionIndexReplacement(activeSessionIndexRefreshFullEntries, token: token)
        sessionListCacheTask = nil
        activeSessionIndexRefreshToken = nil
        activeSessionIndexRefreshWorkspace = nil
        activeSessionIndexRefreshValidTabIDs.removeAll()
        activeSessionIndexRefreshBoundSessionIDByTabID.removeAll()
        activeSessionIndexRefreshBaselineEntries.removeAll()
        activeSessionIndexRefreshPrioritizedEntries.removeAll()
        activeSessionIndexRefreshFullEntries.removeAll()
        activeSessionIndexRefreshHasPublishedFullBatch = false
        sessionIndexStore.setSessionListCacheReady(true, for: token.owner)
        sessionIndexStore.releaseSidebarRestoreFrozenOrder(for: token.owner)
        scheduledSendCoordinator?.workspaceDidLoad()
        scheduleSidebarAutoArchive(reason: .sessionListReady)
    }

    private func applySidebarIndexFailure(token: SessionIndexRefreshToken) {
        guard activeSessionIndexRefreshToken == token,
              sessionIndexStore.isOwnerCurrent(token.owner)
        else {
            return
        }
        publishSessionIndexReplacement(activeSessionIndexRefreshBaselineEntries, token: token)
        sessionListCacheTask = nil
        activeSessionIndexRefreshToken = nil
        activeSessionIndexRefreshWorkspace = nil
        activeSessionIndexRefreshValidTabIDs.removeAll()
        activeSessionIndexRefreshBoundSessionIDByTabID.removeAll()
        activeSessionIndexRefreshBaselineEntries.removeAll()
        activeSessionIndexRefreshPrioritizedEntries.removeAll()
        activeSessionIndexRefreshFullEntries.removeAll()
        activeSessionIndexRefreshHasPublishedFullBatch = false
        sessionIndexStore.setSessionListCacheReady(false, for: token.owner)
        sessionIndexStore.releaseSidebarRestoreFrozenOrder(for: token.owner)
    }

    private func notePrioritizedActiveSessionRestoreStatus(
        token: SessionIndexRefreshToken,
        prioritizedTabID: UUID?
    ) -> Bool {
        #if DEBUG
            let waitStartMS = WorkspaceRestorePerfLog.timestampMSIfEnabled()
            func logActiveRestoreWait(outcome: String, waited: Bool) {
                WorkspaceRestorePerfLog.event(
                    "agentSessionIndex.activeRestoreWait",
                    fields: [
                        "windowID": "\(windowID)",
                        "generation": "\(token.generation)",
                        "prioritizedTabID": WorkspaceRestorePerfLog.shortID(prioritizedTabID),
                        "outcome": outcome,
                        "waited": "\(waited)",
                        "duration": waitStartMS.map { WorkspaceRestorePerfLog.formatElapsedMS(since: $0) } ?? "notMeasured"
                    ]
                )
            }
        #endif
        guard let prioritizedTabID else {
            let shouldContinue = activeSessionIndexRefreshToken == token
                && sessionIndexStore.isOwnerCurrent(token.owner)
            #if DEBUG
                logActiveRestoreWait(outcome: "noPrioritizedTab", waited: false)
            #endif
            return shouldContinue
        }
        guard activeSessionIndexRefreshToken == token,
              sessionIndexStore.isOwnerCurrent(token.owner)
        else {
            #if DEBUG
                logActiveRestoreWait(outcome: "generationChangedBeforeStatus", waited: false)
            #endif
            return false
        }
        guard activeSessionLoadInProgressTabID == prioritizedTabID else {
            #if DEBUG
                logActiveRestoreWait(outcome: "notActiveLoadingTarget", waited: false)
            #endif
            return true
        }
        guard sessions[prioritizedTabID]?.persistedLoadTask != nil else {
            let shouldContinue = activeSessionIndexRefreshToken == token
                && sessionIndexStore.isOwnerCurrent(token.owner)
            #if DEBUG
                logActiveRestoreWait(outcome: "notWaitingNoPersistedLoadTask", waited: false)
            #endif
            return shouldContinue
        }
        #if DEBUG
            logActiveRestoreWait(outcome: "notWaitingLoadInProgress", waited: false)
        #endif
        return true
    }

    /// Direct removal entry (tests and non-prompt callers): admits an operation for `tabIDs` and
    /// commits it. Production removals are driven by `PromptViewModel` through the preflight and
    /// the operation-owned final commit.
    /// Direct removal entry (tests and non-prompt callers): admits, prepares, and commits the
    /// complete batch through the same atomic lifecycle as Prompt-driven removal.
    func handleComposeTabsWillClose(
        _ tabIDs: Set<UUID>,
        reason: PromptViewModel.ComposeTabRemovalReason
    ) async {
        guard let operationID = await admitComposeTabRemoval(tabIDs: tabIDs, reason: reason) else { return }
        defer { finalizeComposeTabRemoval(operationID: operationID) }
        guard await prepareComposeTabRemoval(operationID: operationID) else { return }
        guard commitComposeTabRemoval(
            operationID: operationID,
            promptMutation: { true },
            promptCleanup: { _ in }
        ) else { return }
        await awaitComposeTabRemovalCleanup(operationID: operationID)
    }

    /// Settles every captured owner while removal can still be refused. This phase preserves
    /// terminal-ingestion barriers and the captured persistence context through every await.
    func prepareComposeTabRemoval(operationID: UUID) async -> Bool {
        guard let operation = composeTabRemovalOperations[operationID],
              operation.phase == .admitted,
              removalOperationContextIsCurrent(operation),
              removalTargetSetIsCurrent(operation)
        else {
            if let operation = composeTabRemovalOperations[operationID] {
                abortComposeTabRemoval(operation, vetoedTabIDs: operation.requestedTabIDs)
            }
            return false
        }
        operation.phase = .preparing
        for target in operation.targets {
            target.session.applyEditsApprovalSubscriptionTask?.cancel()
        }

        func ownerStillCurrent(_ target: ComposeTabRemovalOperation.Target) -> Bool {
            operation.phase == .preparing
                && removalOperationContextIsCurrent(operation)
                && removalTargetOwnerIsCurrent(target)
        }

        // Capture every resource identity before any terminal helper clears session-owned handles.
        for target in operation.targets {
            let session = target.session
            operation.cleanupDescriptorsByTabID[target.tabID] = ComposeTabRemovalOperation.CleanupDescriptor(
                tabID: target.tabID,
                session: session,
                boundSessionID: session.activeAgentSessionID ?? boundSessionID(for: target.tabID),
                runID: session.runID,
                approvalScope: applyEditsScope(for: target.tabID),
                approvalSubscriptionID: session.applyEditsApprovalSubscriptionID,
                approvalScopeGeneration: session.applyEditsApprovalScopeGeneration,
                mcpContext: session.mcpControlContext,
                deletionCandidates: []
            )
        }
        for tabID in operation.absentTabIDs {
            operation.cleanupDescriptorsByTabID[tabID] = ComposeTabRemovalOperation.CleanupDescriptor(
                tabID: tabID,
                session: nil,
                boundSessionID: boundSessionID(for: tabID),
                runID: nil,
                approvalScope: applyEditsScope(for: tabID),
                approvalSubscriptionID: nil,
                approvalScopeGeneration: nil,
                mcpContext: nil,
                deletionCandidates: []
            )
        }

        for target in operation.targets {
            let session = target.session
            let tabID = target.tabID
            guard ownerStillCurrent(target),
                  session.activeComposerSubmitAttempt == nil,
                  !session.isPreparingInitialWorktree,
                  !session.isChangingExecutionLocation,
                  !session.worktreeBindingTransitionInProgress,
                  !session.ownsLiveScheduledAttempt
            else {
                abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                return false
            }

            removePendingUIRefresh(for: tabID)
            cancelPersistedLoad(for: session)
            session.drainPendingAssistantDelta()
            cancelPendingQuestion(for: session)
            cancelPendingApproval(for: session)
            cancelPendingApplyEditsReview(for: session, reason: "Cancelled because tab is closing")
            cancelPendingInstruction(for: session)

            if let descriptor = operation.cleanupDescriptorsByTabID[tabID],
               let context = descriptor.mcpContext
            {
                await mcpDeactivateControlContext(
                    sessionID: context.sessionID,
                    ifOwnedBy: context,
                    restorationGeneration: .captured(descriptor.approvalScopeGeneration),
                    cleanupSessionStore: true
                )
                guard ownerStillCurrent(target),
                      session.mcpControlContext == nil
                else {
                    abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                    return false
                }
            }

            #if DEBUG
                if let hook = test_composeTabRemovalEarlyTeardownHook {
                    await hook(session)
                }
                guard ownerStillCurrent(target) else {
                    abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                    return false
                }
            #endif

            // The terminal barrier owns final provider output. Do not clear ephemeral buffers first.
            if session.remoteHost != nil {
                await retireRemoteIngestion(for: session)
            } else if session.runState.isActive {
                // Closing the tab is the user's confirmed stop of its run.
                _ = await cancelAgentRun(
                    target: makeRunCancelTarget(tabID: tabID, session: session),
                    cause: .userCancel,
                    completion: .terminalTeardownCompleted
                )
            } else if isTabRunning(tabID)
                || session.activeRunOwnership != nil
                || session.terminalCommitInProgress
            {
                await cancelAgentRun(tabID: tabID, cause: .userCancel, completion: .terminalTeardownCompleted)
            }
            guard ownerStillCurrent(target) else {
                abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                return false
            }

            await cleanupACPStateForDeletedSession(session)
            guard ownerStillCurrent(target) else {
                abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                return false
            }
            await codexCoordinator.shutdownCodexSession(session)
            guard ownerStillCurrent(target) else {
                abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                return false
            }
            await claudeCoordinator.shutdownClaudeSession(session)
            guard ownerStillCurrent(target) else {
                abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                return false
            }

            // Subscription identifiers were captured above; only now may session-owned ephemeral
            // state be cleared without dropping terminal output. Text buffered during the
            // shutdown awaits is applied first so the final save below includes it.
            session.drainPendingAssistantDelta()
            session.cancelEphemeralRuntimeState()
            if let stopTask = session.staleResetRecoveryTask {
                await stopTask.value
                guard ownerStillCurrent(target) else {
                    abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                    return false
                }
            }

            #if DEBUG
                if let hook = test_composeTabsWillCloseBeforeFinalSaveHook {
                    await hook(session)
                }
                guard ownerStillCurrent(target) else {
                    abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                    return false
                }
            #endif
            await runComposeTabRemovalFinalSave(for: target, operation: operation)
            guard ownerStillCurrent(target) else {
                abortComposeTabRemoval(operation, vetoedTabIDs: [tabID])
                return false
            }
        }

        // One bounded reconsideration preserves the actual-snapshot receipt/coalescing contract.
        for target in operation.targets
            where ownerStillCurrent(target)
            && target.session.staleResetRecovery == nil
            && !removalTargetIsSettled(target)
        {
            target.session.staleResetRemovalAdmission?.isFinalSaveCompleted = false
            await runComposeTabRemovalFinalSave(for: target, operation: operation)
            guard ownerStillCurrent(target) else {
                abortComposeTabRemoval(operation, vetoedTabIDs: [target.tabID])
                return false
            }
        }

        guard removalOperationContextIsCurrent(operation), removalTargetSetIsCurrent(operation) else {
            abortComposeTabRemoval(operation, vetoedTabIDs: operation.requestedTabIDs)
            return false
        }
        let vetoedTabIDs = Set(operation.targets.lazy.filter {
            !self.removalTargetIsConsented($0) || !self.removalTargetIsSettled($0)
        }.map(\.tabID))
        guard vetoedTabIDs.isEmpty else {
            abortComposeTabRemoval(operation, vetoedTabIDs: vetoedTabIDs)
            return false
        }

        if operation.reason != .stash,
           !AppLaunchConfiguration.current.suppressesAgentSessionPersistence
        {
            for tabID in operation.requestedTabIDs.sorted(by: { $0.uuidString < $1.uuidString }) {
                do {
                    let candidates = try await dataService.deletionCandidates(
                        forComposeTabID: tabID,
                        for: operation.workspace
                    )
                    guard removalOperationContextIsCurrent(operation),
                          removalTargetSetIsCurrent(operation)
                    else {
                        abortComposeTabRemoval(operation, vetoedTabIDs: operation.requestedTabIDs)
                        return false
                    }
                    if var descriptor = operation.cleanupDescriptorsByTabID[tabID] {
                        descriptor.deletionCandidates = candidates
                        operation.cleanupDescriptorsByTabID[tabID] = descriptor
                    }
                } catch {
                    if var descriptor = operation.cleanupDescriptorsByTabID[tabID] {
                        descriptor.deletionDiscoverySucceeded = false
                        operation.cleanupDescriptorsByTabID[tabID] = descriptor
                    }
                    operation.cleanupFailures.append(
                        "candidate discovery tab=\(tabID.uuidString) workspace=\(operation.workspaceID.uuidString): \(error.localizedDescription)"
                    )
                }
            }
        }

        guard removalOperationContextIsCurrent(operation),
              removalTargetSetIsCurrent(operation),
              operation.targets.allSatisfy({
                  removalTargetIsConsented($0) && removalTargetIsSettled($0)
              })
        else {
            abortComposeTabRemoval(operation, vetoedTabIDs: operation.requestedTabIDs)
            return false
        }
        operation.phase = .prepared
        return true
    }

    /// Applies Prompt and Agent logical removal in one synchronous MainActor critical section.
    /// No validation or rollback remains after the Prompt mutation succeeds.
    @discardableResult
    func commitComposeTabRemoval(
        operationID: UUID,
        promptMutation: @MainActor () -> Bool,
        promptCleanup: @MainActor @escaping (@escaping @MainActor () -> Bool) async -> Void
    ) -> Bool {
        // Once window close begins, nothing new commits: the close drains only cleanup tasks
        // that already exist, so a later commit could outlive it.
        guard !hasPreparedForWindowClose,
              let operation = composeTabRemovalOperations[operationID],
              operation.phase == .prepared,
              removalOperationContextIsCurrent(operation),
              removalTargetSetIsCurrent(operation),
              operation.targets.allSatisfy({
                  removalTargetIsConsented($0) && removalTargetIsSettled($0)
              })
        else {
            if let operation = composeTabRemovalOperations[operationID] {
                abortComposeTabRemoval(operation, vetoedTabIDs: operation.requestedTabIDs)
            }
            return false
        }

        let manager = workspaceManager
        if let manager, !manager.beginSynchronousComposeTabRemovalMutation() {
            abortComposeTabRemoval(operation, vetoedTabIDs: operation.requestedTabIDs)
            return false
        }
        defer { manager?.endSynchronousComposeTabRemovalMutation() }

        // The manager guard intentionally makes the ordinary context predicate false while this
        // synchronous stack is active; validate the underlying captured owner directly.
        guard sessionPersistenceContextIsCurrent(operation.persistenceContext),
              operation.persistenceContext.workspaceOwner.map(sessionIndexStore.isOwnerCurrent) == true,
              removalTargetSetIsCurrent(operation),
              promptMutation()
        else {
            abortComposeTabRemoval(operation, vetoedTabIDs: operation.requestedTabIDs)
            return false
        }

        for target in operation.targets {
            let session = target.session
            commitStaleResetRemoval(session)
            releaseScheduledSendForRemovedSession(
                session,
                deletesPersistedSession: operation.reason != .stash
            )
            cleanupSidebarRunAttention(tabIDs: [target.tabID])
            remoteRunLocallyFallbackItemIDByTabID.removeValue(forKey: target.tabID)
            if operation.reason != .stash {
                tabDraftText.removeValue(forKey: target.tabID)
            }
            sessions.removeValue(forKey: target.tabID)
            tabsWithActiveAgentRun.remove(target.tabID)
            mcpControlledTabIDs.remove(target.tabID)
        }
        for tabID in operation.absentTabIDs {
            cleanupSidebarRunAttention(tabIDs: [tabID])
            remoteRunLocallyFallbackItemIDByTabID.removeValue(forKey: tabID)
            tabsWithActiveAgentRun.remove(tabID)
            mcpControlledTabIDs.remove(tabID)
            if operation.reason != .stash {
                tabDraftText.removeValue(forKey: tabID)
            }
        }

        operation.phase = .committed
        operation.cleanupTask = Task { @MainActor [weak self, operation] in
            guard let self else { return }
            operation.phase = .cleaning
            await performCommittedComposeTabRemovalCleanup(
                operation,
                promptCleanup: promptCleanup
            )
        }
        return true
    }

    func awaitComposeTabRemovalCleanup(operationID: UUID) async {
        await composeTabRemovalOperations[operationID]?.cleanupTask?.value
    }

    private func performCommittedComposeTabRemovalCleanup(
        _ operation: ComposeTabRemovalOperation,
        promptCleanup: @MainActor (@escaping @MainActor () -> Bool) async -> Void
    ) async {
        for failure in operation.cleanupFailures {
            print("[AgentMode] compose-tab removal cleanup warning: \(failure)")
        }

        for tabID in operation.requestedTabIDs.sorted(by: { $0.uuidString < $1.uuidString }) {
            guard let descriptor = operation.cleanupDescriptorsByTabID[tabID] else { continue }

            #if DEBUG
                if let session = descriptor.session,
                   let hook = test_composeTabRemovalPhaseTwoHook
                {
                    await hook(session)
                }
            #endif

            if let subscriptionID = descriptor.approvalSubscriptionID {
                await applyEditsApprovalStore.unsubscribe(
                    scope: descriptor.approvalScope,
                    id: subscriptionID
                )
            }
            if let generation = descriptor.approvalScopeGeneration {
                _ = await applyEditsApprovalStore.cleanupScope(
                    descriptor.approvalScope,
                    ifOwnedBy: generation
                )
            }
            if let context = descriptor.mcpContext {
                await AgentRunSessionStore.cleanup(registration: context.registration)
            }
            await cleanupMCPRunRoutingIfPresent(
                boundSessionID: descriptor.boundSessionID,
                liveSession: nil,
                explicitRunID: descriptor.runID,
                reason: "compose_tab_close"
            )
            await releaseSessionWorktreeOwnership(sessionID: descriptor.boundSessionID)

            if operation.reason != .stash {
                var deletionSucceededForTab = descriptor.deletionDiscoverySucceeded
                for candidate in descriptor.deletionCandidates {
                    do {
                        let result = try await dataService.deleteAgentSession(
                            ifCurrent: candidate,
                            for: operation.workspace
                        )
                        switch result {
                        case .deleted, .alreadyAbsent:
                            if operation.persistenceContext.workspaceOwner.map(sessionIndexStore.isOwnerCurrent) == true,
                               ownerValidatedSessionIndex[candidate.sessionID]?.tabID == tabID
                            {
                                removeSessionIndex(sessionID: candidate.sessionID)
                            }
                        case .ownershipChanged:
                            deletionSucceededForTab = false
                            print(
                                "[AgentMode] compose-tab removal preserved changed session " +
                                    "workspace=\(operation.workspaceID.uuidString) " +
                                    "tab=\(tabID.uuidString) session=\(candidate.sessionID.uuidString) " +
                                    "storage=\(candidate.storagePath)"
                            )
                        }
                    } catch {
                        deletionSucceededForTab = false
                        print(
                            "[AgentMode] compose-tab removal deletion failed " +
                                "workspace=\(operation.workspaceID.uuidString) " +
                                "tab=\(tabID.uuidString) session=\(candidate.sessionID.uuidString) " +
                                "storage=\(candidate.storagePath): \(error.localizedDescription)"
                        )
                    }
                }
                if deletionSucceededForTab,
                   operation.persistenceContext.workspaceOwner.map(sessionIndexStore.isOwnerCurrent) == true
                {
                    sessionIndexStore.removeSortDate(forTabID: tabID)
                }
            }

            clearRemoteStartWindowPickerIfOwned(by: tabID)
            remoteCoordinator.stop(tabID: tabID)
            if let boundSessionID = descriptor.boundSessionID {
                scheduledSendCoordinator?.tabDidClose(sessionID: boundSessionID)
            }
            #if DEBUG
                AgentModePerfDiagnostics.markSidebarDeleteAgentCleanupComplete(
                    tabID: tabID,
                    source: "AgentModeViewModel.performCommittedComposeTabRemovalCleanup",
                    fields: ["reason": String(describing: operation.reason)]
                )
            #endif
        }

        await promptCleanup { [weak self, operation] in
            guard let self else { return false }
            return sessionPersistenceContextIsCurrent(
                operation.persistenceContext,
                requireSwitchIdle: true
            )
        }

        operation.phase = .finished
        if operation.isCallerFinalized {
            releaseComposeTabReservations(for: operation)
            composeTabRemovalOperations.removeValue(forKey: operation.id)
            notifyScheduledSendBusyStateMayHaveChanged(tabIDs: operation.requestedTabIDs)
        }
    }

    /// The operation's final save for one captured owner: drains a save already in flight, runs
    /// the save, and records a receipt identifying the snapshot actually made durable (or the
    /// clean live state), classified as clean / written / recovery / unsaved. From then on saves
    /// for that owner are refused (`isFinalSaveCompleted`), so nothing can be discovered after
    /// this save except through the operation's own reconsideration.
    private func runComposeTabRemovalFinalSave(
        for target: ComposeTabRemovalOperation.Target,
        operation: ComposeTabRemovalOperation
    ) async {
        let session = target.session
        if let sessionID = session.activeAgentSessionID {
            await awaitInFlightSave(sessionID: sessionID)
        }
        guard removalOperationContextIsCurrent(operation),
              removalTargetOwnerIsCurrent(target)
        else { return }
        let wasDirty = session.isDirty
        let outcome = await flushSaveDetailed(
            for: target.tabID,
            context: operation.persistenceContext
        )
        guard removalOperationContextIsCurrent(operation),
              removalTargetOwnerIsCurrent(target)
        else { return }
        // The final save owns durability: a debounce handle left behind by earlier scheduling
        // (flushing cancels but does not clear it) is retired here; the reservation prevents any
        // new one.
        session.saveDebounceTask?.cancel()
        session.saveDebounceTask = nil
        let kind: AgentStaleResetRemovalAdmission.FinalSaveKind
        var receiptRevision = session.sourceItemsRevision
        var receiptGeneration = session.persistenceMutationGeneration
        switch outcome {
        case let .written(receipt):
            kind = .written
            receiptRevision = receipt.sourceItemsRevision
            receiptGeneration = receipt.persistenceMutationGeneration
        case .suppressed:
            kind = .clean
        case .resetAcknowledged, .deferredBehindInFlightSave:
            kind = .unsaved
        case .notWritten:
            if session.staleResetRecovery != nil {
                kind = .recovery
            } else if persistenceWorkspace == nil || (!wasDirty && !session.isDirty) {
                // Nothing to persist to, or nothing was dirty: the live state is the durable state.
                kind = .clean
            } else {
                kind = .unsaved
            }
        }
        session.staleResetRemovalAdmission?.finalSaveRevision = receiptRevision
        session.staleResetRemovalAdmission?.finalSaveMutationGeneration = receiptGeneration
        session.staleResetRemovalAdmission?.finalSaveKind = kind
        session.staleResetRemovalAdmission?.isFinalSaveCompleted = true
    }

    // MARK: - Persistence

    func currentSessionPersistenceContext() -> SessionPersistenceContext? {
        guard let workspace = persistenceWorkspace else { return nil }
        return SessionPersistenceContext(
            workspace: workspace,
            workspaceOwner: sessionIndexOwner
        )
    }

    func sessionPersistenceContextIsCurrent(
        _ context: SessionPersistenceContext,
        requireSwitchIdle: Bool = true
    ) -> Bool {
        guard persistenceWorkspace?.id == context.workspaceID else { return false }
        if requireSwitchIdle, workspaceManager?.isSwitchingWorkspace == true {
            return false
        }
        if let owner = context.workspaceOwner {
            return sessionIndexStore.isOwnerCurrent(owner)
        }
        return workspaceManager == nil
    }

    private func makeSaveCommitToken(
        for session: AgentTabSession,
        context: SessionPersistenceContext
    ) -> SessionSaveCommitToken? {
        guard let binding = session.persistentSessionBindingIdentity,
              binding.sessionID == session.activeAgentSessionID,
              !session.bindingTransitionInProgress
        else {
            return nil
        }
        return SessionSaveCommitToken(
            tabID: session.tabID,
            sessionIdentity: ObjectIdentifier(session),
            workspaceID: context.workspaceID,
            workspaceOwner: context.workspaceOwner,
            binding: binding,
            bindingTransitionGeneration: session.bindingTransitionGeneration,
            sourceItemsRevision: session.sourceItemsRevision,
            persistenceMutationGeneration: session.persistenceMutationGeneration,
            saveRequestGeneration: session.saveRequestGeneration
        )
    }

    private func isSaveCommitTokenOwnerCurrent(
        _ token: SessionSaveCommitToken,
        requireWorkspaceMatch: Bool = true
    ) -> Bool {
        if requireWorkspaceMatch {
            guard persistenceWorkspace?.id == token.workspaceID,
                  workspaceManager?.isSwitchingWorkspace != true
            else { return false }
            if let owner = token.workspaceOwner,
               !sessionIndexStore.isOwnerCurrent(owner)
            {
                return false
            }
        }
        guard let session = sessions[token.tabID],
              ObjectIdentifier(session) == token.sessionIdentity,
              session.persistentSessionBindingIdentity == token.binding,
              session.bindingTransitionGeneration == token.bindingTransitionGeneration,
              !session.bindingTransitionInProgress
        else {
            return false
        }
        return true
    }

    private func isSaveCommitTokenCurrent(
        _ token: SessionSaveCommitToken,
        requireWorkspaceMatch: Bool = true
    ) -> Bool {
        guard isSaveCommitTokenOwnerCurrent(token, requireWorkspaceMatch: requireWorkspaceMatch),
              let session = sessions[token.tabID]
        else {
            return false
        }
        guard session.sourceItemsRevision == token.sourceItemsRevision,
              session.persistenceMutationGeneration == token.persistenceMutationGeneration,
              session.saveRequestGeneration == token.saveRequestGeneration
        else {
            return false
        }
        return true
    }

    private func requestFreshSaveForCurrentOwner(
        sessionID: UUID,
        fallbackSession: AgentTabSession,
        context: SessionPersistenceContext? = nil
    ) {
        if let context, !sessionPersistenceContextIsCurrent(context) {
            return
        }
        let currentOwner = try? authoritativeLiveSession(for: sessionID)
        if let currentOwner {
            currentOwner.isDirty = true
            saveRequestedWhileInFlightSessionIDs.insert(sessionID)
        } else if fallbackSession.activeAgentSessionID == sessionID {
            fallbackSession.isDirty = true
            saveRequestedWhileInFlightSessionIDs.insert(sessionID)
        }
    }

    func scheduleSave(for tabID: UUID) {
        guard !AppLaunchConfiguration.current.suppressesAgentSessionPersistence else { return }
        guard let session = sessions[tabID] else { return }
        session.saveRequestGeneration &+= 1
        if session.staleResetRecovery != nil || session.staleResetRemovalAdmission?.blocksScheduledSaves == true {
            // Retained, unsavable view (no futile debounce task; the edit stays dirty until an
            // explicit reload restores authority), or an owner reserved/retired by a removal
            // operation whose final save owns durability.
            return
        }
        #if DEBUG
            let replacedPendingSave = session.saveDebounceTask != nil
            AgentModePerfDiagnostics.increment("save.schedule", tabID: tabID)
            if replacedPendingSave {
                AgentModePerfDiagnostics.increment("save.schedule.replaced", tabID: tabID)
            }
            AgentModePerfDiagnostics.event("save.schedule", tabID: tabID, fields: ["replaced": String(replacedPendingSave), "dirty": String(session.isDirty)])
        #endif
        session.saveDebounceTask?.cancel()
        let sleep = saveTimerSleep
        let debounceDeadline = ContinuousClock.now + Self.saveDebounceInterval
        session.saveDebounceTask = Task { [weak self] in
            try? await sleep(.debounce, debounceDeadline)
            guard !Task.isCancelled else { return }
            await self?.saveSession(for: tabID)
        }
    }

    func scheduleSaveForCommandOutput(tabID: UUID, minInterval: TimeInterval = 5.0) {
        guard let session = sessions[tabID] else { return }
        let now = Date()
        if let lastSaveAt = session.lastCommandOutputSaveAt,
           now.timeIntervalSince(lastSaveAt) < minInterval
        {
            #if DEBUG
                AgentModePerfDiagnostics.increment("save.commandOutput.skipped", tabID: tabID)
                AgentModePerfDiagnostics.event(
                    "save.commandOutput.skipped",
                    tabID: tabID,
                    fields: [
                        "elapsed": String(format: "%.2fs", now.timeIntervalSince(lastSaveAt)),
                        "minInterval": String(format: "%.2fs", minInterval)
                    ]
                )
            #endif
            return
        }
        session.lastCommandOutputSaveAt = now
        #if DEBUG
            AgentModePerfDiagnostics.increment("save.commandOutput.scheduled", tabID: tabID)
            AgentModePerfDiagnostics.event("save.commandOutput.scheduled", tabID: tabID, fields: ["minInterval": String(format: "%.2fs", minInterval)])
        #endif
        scheduleSave(for: tabID)
    }

    /// Precise result of one immediate session save. Durable commitment is reported separately
    /// from whether the in-memory projection could be marked clean: a save whose snapshot was
    /// written but whose commit token went stale (a request coalesced behind it) is still a
    /// durable write, and callers that only need durability (initial creation of a scheduled
    /// message) must not treat it as failure.
    /// Identity of the snapshot a save actually made durable: the content revision and
    /// persistence-mutation generation captured when the snapshot was built, not the live values
    /// observed after the write returned.
    struct SessionSaveReceipt: Equatable {
        let sourceItemsRevision: Int
        let persistenceMutationGeneration: UInt64
        /// `false` when a newer request coalesced behind the write (a fresh save was requested).
        let projectionClean: Bool
    }

    enum SessionSaveOutcome: Equatable {
        /// Persistence is suppressed for this launch; nothing is written and nothing is pending.
        case suppressed
        /// The session file was durably written by this call; the receipt identifies exactly the
        /// snapshot written.
        case written(SessionSaveReceipt)
        /// The transcript reset carried by this save was already durable; the newer unsaved edits
        /// stay dirty and a fresh owner-current save was scheduled.
        case resetAcknowledged
        /// A save for this durable session is already in flight; this request was coalesced
        /// behind it and nothing was written by this call.
        case deferredBehindInFlightSave
        /// Skipped or failed before any durable write.
        case notWritten

        /// The historical Boolean contract: the file was durably written by this call and the
        /// projection is clean (or persistence is suppressed).
        var isCleanSuccess: Bool {
            switch self {
            case .suppressed, .resetAcknowledged:
                true
            case let .written(receipt):
                receipt.projectionClean
            case .deferredBehindInFlightSave, .notWritten:
                false
            }
        }

        /// The session file was durably written by this call, clean projection or not.
        var didWriteDurably: Bool {
            if case .written = self { return true }
            return false
        }
    }

    /// Immediate session save. Returns `true` only when the session file was durably written
    /// by this call and the projection is clean (or persistence is suppressed); every skipped,
    /// coalesced, or failed path returns `false` so dispatch-attempt callers can react instead of
    /// assuming success. Callers that must distinguish durable commitment from a clean projection
    /// use `saveSessionDetailed(for:)`.
    @discardableResult
    func saveSession(for tabID: UUID) async -> Bool {
        await saveSessionDetailed(for: tabID).isCleanSuccess
    }

    @discardableResult
    func saveSessionDetailed(
        for tabID: UUID,
        context explicitContext: SessionPersistenceContext? = nil
    ) async -> SessionSaveOutcome {
        #if DEBUG
            let diagnosticsStartMS = AgentModePerfDiagnostics.timestampMSIfEnabled()
            AgentModePerfDiagnostics.increment("save.session.invoked", tabID: tabID)
        #endif
        guard !AppLaunchConfiguration.current.suppressesAgentSessionPersistence else {
            #if DEBUG
                AgentModePerfDiagnostics.event("save.session.skipped", tabID: tabID, fields: ["reason": "suppressed"])
            #endif
            return .suppressed
        }
        guard let session = sessions[tabID],
              let context = explicitContext ?? currentSessionPersistenceContext(),
              sessionPersistenceContextIsCurrent(context),
              session.isDirty || session.activeAgentSessionID == nil || !session.pendingAssistantDelta.isEmpty
        else {
            #if DEBUG
                AgentModePerfDiagnostics.event("save.session.skipped", tabID: tabID, fields: ["reason": "missingContextOwnerOrClean"])
            #endif
            return .notWritten
        }
        let workspace = context.workspace

        if session.staleResetRecovery != nil {
            // The retained snapshot is never written: authority was rejected by a committed peer
            // reset and is re-adopted only through the explicitly confirmed reload.
            #if DEBUG
                AgentModePerfDiagnostics.event("save.session.skipped", tabID: tabID, fields: ["reason": "staleResetRecovery"])
            #endif
            return .notWritten
        }
        if let admission = session.staleResetRemovalAdmission, admission.isFinalSaveCompleted || admission.isCommitted {
            // The removal operation's final save completed for this owner: no later save may
            // run, so nothing unsavable can be discovered between that save, the final batch
            // check, and removal. A changed owner is re-saved by the operation itself.
            #if DEBUG
                AgentModePerfDiagnostics.event("save.session.skipped", tabID: tabID, fields: ["reason": "removalFinalSaveCompleted"])
            #endif
            return .notWritten
        }
        // Buffered assistant text belongs in this snapshot (R3): it is applied through its
        // producer's flush before any revision, item snapshot, or commit token is captured.
        session.drainPendingAssistantDelta()
        guard session.isDirty || session.activeAgentSessionID == nil else {
            return .notWritten
        }

        if session.activeAgentSessionID == nil, !hasPersistableConversationContent(session) {
            return .notWritten
        }
        guard let sessionID = ensureSessionBoundToTab(session) else {
            return .notWritten
        }
        session.saveRequestGeneration &+= 1
        if saveInFlightSessionIDs.contains(sessionID) {
            saveRequestedWhileInFlightSessionIDs.insert(sessionID)
            return .deferredBehindInFlightSave
        }
        saveInFlightSessionIDs.insert(sessionID)
        defer {
            saveInFlightSessionIDs.remove(sessionID)
            for waiter in saveCompletionWaiters.removeValue(forKey: sessionID) ?? [] {
                waiter.resume()
            }
            if saveRequestedWhileInFlightSessionIDs.remove(sessionID) != nil,
               sessionPersistenceContextIsCurrent(context)
            {
                if let currentOwner = try? authoritativeLiveSession(for: sessionID) {
                    scheduleSave(for: currentOwner.tabID)
                } else if sessions[tabID] === session,
                          session.activeAgentSessionID == sessionID
                {
                    scheduleSave(for: tabID)
                }
            }
        }
        var workingItemsSnapshot = session.items
        var shouldRefreshAfterPreparation = false
        let existingTranscript = session.transcript
        let previousBaseProjection = session.baseTranscriptProjection
        let previousProjection = session.transcriptProjection
        let previousProjectionProtection = session.transcriptProjectionProtection
        let isActiveOwnedForSave = canBuildOrPublishActiveTranscriptBindings(for: session)
        if !session.runState.isActive {
            let repairedCount = AgentTranscriptIO.finalizePendingToolCalls(
                in: &workingItemsSnapshot,
                terminalState: session.runState,
                includeExplicitRepoPromptToolCalls: session.selectedAgent == .codexExec || session.selectedAgent.acpProviderID != nil,
                nonToolBoundary: Self.pendingToolFinalizationNonToolBoundary
            )
            if repairedCount > 0 {
                session.setItemsSilently(workingItemsSnapshot, reason: .pendingToolFinalizationRepair)
                session.isDirty = true
                refreshDerivedTranscriptState(for: session, reason: .saveSession)
                #if DEBUG
                    AgentModePerfDiagnostics.increment("save.session.localPendingToolRepair", tabID: tabID)
                    AgentModePerfDiagnostics.event(
                        "save.session.localPendingToolRepair",
                        tabID: tabID,
                        fields: [
                            "activeOwned": String(isActiveOwnedForSave),
                            "repairedCount": String(repairedCount)
                        ]
                    )
                #endif
            }
        }
        var projectionProtection = transcriptProjectionProtection(
            for: session,
            transcript: session.transcript
        )
        let importPolicy = AgentTranscriptImportPolicy.liveSession(
            hidePendingQuestionToolCall: session.hasPendingQuestionUI
        )
        if !isActiveOwnedForSave,
           session.derivedTranscriptRefreshTask != nil || session.pendingDerivedTranscriptRefreshReason != nil
        {
            let scheduledReason = session.pendingDerivedTranscriptRefreshReason ?? .liveMutation
            refreshDerivedTranscriptState(for: session, reason: scheduledReason)
            projectionProtection = transcriptProjectionProtection(
                for: session,
                transcript: session.transcript
            )
        }
        let canReusePresentation = !shouldRefreshAfterPreparation
            && canReuseDerivedTranscriptForSave(
                for: session,
                projectionProtection: projectionProtection
            )
        let builtPresentation: AgentBuiltTranscriptPresentation?
        let persistableSnapshot: PersistableTranscriptSnapshot
        if canReusePresentation {
            let reusedPresentation = builtTranscriptPresentationSnapshot(for: session)
            builtPresentation = reusedPresentation
            persistableSnapshot = PersistableTranscriptSnapshot(
                transcript: reusedPresentation.transcript,
                projectionCounts: reusedPresentation.projectionCounts,
                canonicalVisibleRowCount: reusedPresentation.canonicalVisibleRowCount,
                lastUserMessageAt: AgentTranscriptIO.lastUserInteractionDate(in: reusedPresentation.transcript)
                    ?? AgentTranscriptIO.lastUserInteractionDate(in: workingItemsSnapshot)
            )
        } else if isActiveOwnedForSave {
            let transcriptSnapshot = AgentTranscriptIO.rebuiltTranscriptPreservingCompactedPrefix(
                existingTranscript: existingTranscript,
                workingItems: workingItemsSnapshot,
                terminalState: session.runState,
                nextSequenceIndex: session.nextSequenceIndex,
                policy: importPolicy,
                protection: projectionProtection
            )
            let appliedPresentation = applyTranscriptPresentation(
                transcriptSnapshot,
                sourceItems: workingItemsSnapshot,
                to: session
            )
            builtPresentation = appliedPresentation
            persistableSnapshot = PersistableTranscriptSnapshot(
                transcript: appliedPresentation.transcript,
                projectionCounts: appliedPresentation.projectionCounts,
                canonicalVisibleRowCount: appliedPresentation.canonicalVisibleRowCount,
                lastUserMessageAt: AgentTranscriptIO.lastUserInteractionDate(in: appliedPresentation.transcript)
                    ?? AgentTranscriptIO.lastUserInteractionDate(in: workingItemsSnapshot)
            )
        } else {
            #if DEBUG
                // Captured before the fallback: labels the sync-state inputs that differ from the stamp.
                let syncDeltaLabel = AgentDerivedTranscriptSyncState.diagnosticDeltaLabel(
                    from: session.derivedTranscriptSyncState,
                    to: makeDerivedTranscriptSyncState(for: session, projectionProtection: projectionProtection)
                )
            #endif
            builtPresentation = nil
            persistableSnapshot = persistableTranscriptSnapshot(
                for: session,
                workingItems: workingItemsSnapshot,
                existingTranscript: existingTranscript,
                importPolicy: importPolicy,
                projectionProtection: projectionProtection
            )
            #if DEBUG
                AgentModePerfDiagnostics.increment("save.session.persistenceOnlySnapshot", tabID: tabID)
                AgentModePerfDiagnostics.event(
                    "save.session.persistenceOnlySnapshot",
                    tabID: tabID,
                    fields: [
                        "currentTabID": AgentModePerfDiagnostics.shortID(currentTabID),
                        "sourceItemsRevision": String(session.sourceItemsRevision),
                        "syncDelta": syncDeltaLabel
                    ]
                )
            #endif
        }
        let presentationChanged = isActiveOwnedForSave && !canReusePresentation && builtPresentation != nil && (
            session.transcript != existingTranscript
                || session.baseTranscriptProjection != previousBaseProjection
                || session.transcriptProjection != previousProjection
                || session.transcriptProjectionProtection != previousProjectionProtection
        )
        if isActiveOwnedForSave, let builtPresentation {
            let shouldReconcileWorkingItems = session.items == workingItemsSnapshot
                && (
                    AgentTranscriptIO.containsExcludedLegacyItems(workingItemsSnapshot, policy: importPolicy)
                        || AgentTranscriptIO.fullDetailTurnEnvelopeChanged(
                            from: existingTranscript,
                            to: builtPresentation.transcript
                        )
                        || (!canReusePresentation && builtPresentation.sanitizedActivityCount > 0)
                )
            if shouldReconcileWorkingItems {
                let trimmedWorkingItems = AgentTranscriptIO.workingSourceItems(from: builtPresentation.transcript)
                if trimmedWorkingItems != session.items {
                    session.setItemsSilently(trimmedWorkingItems, reason: .retentionCompaction)
                    markDerivedTranscriptSynchronized(
                        for: session,
                        projectionProtection: builtPresentation.projectionProtection
                    )
                    workingItemsSnapshot = trimmedWorkingItems
                    shouldRefreshAfterPreparation = true
                }
            } else if session.items != workingItemsSnapshot {
                workingItemsSnapshot = session.items
            }
        } else if session.items != workingItemsSnapshot {
            workingItemsSnapshot = session.items
        }
        if presentationChanged {
            shouldRefreshAfterPreparation = true
        }
        if shouldRefreshAfterPreparation {
            // Only refresh sessions that can publish active bindings now. Inactive
            // persistence-only saves must not feed back into UI projection work.
            if isActiveOwnedForSave {
                #if DEBUG
                    AgentModePerfDiagnostics.increment("save.session.innerRefresh", tabID: tabID)
                    AgentModePerfDiagnostics.event("save.session.innerRefresh", tabID: tabID)
                #endif
                requestUIRefresh(tabID: tabID)
            } else {
                #if DEBUG
                    AgentModePerfDiagnostics.increment("save.session.innerRefreshSkippedInactive", tabID: tabID)
                    AgentModePerfDiagnostics.event(
                        "save.session.innerRefreshSkipped",
                        tabID: tabID,
                        fields: [
                            "reason": "inactiveTab",
                            "currentTabID": AgentModePerfDiagnostics.shortID(currentTabID)
                        ]
                    )
                #endif
            }
        }

        // Build the persisted session only for the binding generation captured below.
        let lastUserMessageAt = persistableSnapshot.lastUserMessageAt
        let canonicalItemCount = persistableSnapshot.canonicalVisibleRowCount
        let sessionName = resolvedSessionDisplayName(for: tabID)
        var agentSession = makePersistedAgentSession(
            for: session,
            tabID: tabID,
            sessionID: sessionID,
            workspaceID: workspace.id,
            sessionName: sessionName,
            persistableSnapshot: persistableSnapshot
        )
        guard let saveToken = makeSaveCommitToken(for: session, context: context),
              isSaveCommitTokenCurrent(saveToken)
        else {
            requestFreshSaveForCurrentOwner(
                sessionID: sessionID,
                fallbackSession: session,
                context: context
            )
            return .notWritten
        }

        let finalizedItemRemovals = session.pendingFinalizedScheduledSendItemRemovals
        let transcriptResetReceipt = session.pendingTranscriptResetReceipt
        // Captured lifetime: an existing incarnation saves under its own service-issued state
        // (never refreshed after a deletion or missing-file failure); a genuine initial creation
        // first commits the session file exclusively from this snapshot, then saves normally.
        let acquisition = await acquirePersistenceState(
            for: session,
            sessionID: sessionID,
            workspace: workspace,
            context: context,
            initialSession: agentSession,
            trustedCanonicalItemCount: canonicalItemCount
        )
        // Exclusive creation in this call durably committed exactly this snapshot. Every later
        // exit that writes nothing more reports that real write as durable but not clean (as a
        // coalesced save does) instead of `.notWritten`; the projection stays dirty, and the
        // deletion/reset handlers below still run.
        let notWrittenOutcome: SessionSaveOutcome = acquisition.createdDurably
            ? .written(SessionSaveReceipt(
                sourceItemsRevision: saveToken.sourceItemsRevision,
                persistenceMutationGeneration: saveToken.persistenceMutationGeneration,
                projectionClean: false
            ))
            : .notWritten
        guard let persistenceState = acquisition.state else {
            if acquisition.createdDurably {
                // The creation's authority is not usable for this save (the context or owner
                // changed meanwhile): a fresh owner-current save writes the newer projection.
                requestFreshSaveForCurrentOwner(
                    sessionID: sessionID,
                    fallbackSession: session,
                    context: context
                )
                return notWrittenOutcome
            }
            // Fail closed: a hydrated tab without captured ownership of an existing incarnation
            // never overwrites that file from memory. Surface it instead of failing silently.
            if session.persistenceRevokedSessionID != sessionID {
                #if DEBUG
                    AgentModePerfDiagnostics.event(
                        "save.session.unowned",
                        tabID: tabID,
                        fields: [
                            "sessionID": sessionID.uuidString,
                            "hasLoadedPersistedState": String(session.hasLoadedPersistedState),
                            "pinnedIncarnation": session.persistedIncarnationSessionID?.uuidString ?? "nil"
                        ]
                    )
                #endif
                print("[AgentModeVM] save skipped: no captured persistence ownership for session \(sessionID) (tab \(tabID)); the existing file is never overwritten from memory")
            }
            return .notWritten
        }
        // Ownership must still be current after the state capture. Content/request generations
        // are deliberately not re-checked here: a coalesced request that arrived during the
        // capture bumps `saveRequestGeneration` without writing anything itself, so aborting now
        // would leave nothing on disk. The snapshot built above is still written; the existing
        // post-save token check requests a fresh save for any newer content.
        guard isSaveCommitTokenOwnerCurrent(saveToken),
              session.activeAgentSessionID == sessionID
        else {
            requestFreshSaveForCurrentOwner(
                sessionID: sessionID,
                fallbackSession: session,
                context: context
            )
            return notWrittenOutcome
        }
        // Owner saves always target the existing incarnation (creation already committed above):
        // an explicitly deleted or missing file is never recreated by a queued or debounced save.
        let fileCreationPolicy: AgentSessionFileCreationPolicy = .requireExisting
        let saveReceipt = SessionSaveReceipt(
            sourceItemsRevision: saveToken.sourceItemsRevision,
            persistenceMutationGeneration: saveToken.persistenceMutationGeneration,
            projectionClean: true
        )
        do {
            #if DEBUG
                if let hook = test_saveSessionBeforeWriteHook {
                    await hook(session)
                }
            #endif
            guard isSaveCommitTokenOwnerCurrent(saveToken) else {
                return notWrittenOutcome
            }
            // A pending history import commits in this same save (rows + ledger + receipt).
            let historyImport = session.pendingHistoryImportCommit.flatMap { pending in
                agentSession.providerHistoryRecovery?.lastImportCommit == pending ? pending : nil
            }
            let commit = try await dataService.saveAgentSession(
                agentSession,
                for: workspace,
                preparation: .alreadyCanonicalTranscript,
                trustedCanonicalItemCount: canonicalItemCount,
                intentionallyRemovingFinalizedScheduledSendItems: finalizedItemRemovals,
                committingTranscriptReset: transcriptResetReceipt,
                fileCreationPolicy: fileCreationPolicy,
                persistenceState: persistenceState,
                committingHistoryImport: historyImport
            )
            let fileURL = commit.fileURL
            // Acknowledgements are identity-aware: only the owner that issued this save adopts
            // the committed state, clears the exact removals it carried, and consumes its reset.
            if isSaveCommitTokenOwnerCurrent(saveToken),
               session.activeAgentSessionID == sessionID
            {
                session.persistenceState = commit.persistenceState
                recoveryPersistenceStateDidChange(for: session)
                session.persistedIncarnationSessionID = sessionID
                if !finalizedItemRemovals.isEmpty {
                    session.pendingFinalizedScheduledSendItemRemovals.removeAll { removal in
                        finalizedItemRemovals.contains(removal)
                    }
                }
                if let transcriptResetReceipt, session.pendingTranscriptResetReceipt == transcriptResetReceipt {
                    session.pendingTranscriptResetReceipt = nil
                }
                if let historyImport {
                    session.committedHistoryImportID = historyImport.importID
                    if session.pendingHistoryImportCommit == historyImport {
                        session.pendingHistoryImportCommit = nil
                    }
                }
            }
            agentSession.fileURL = fileURL
            guard isSaveCommitTokenCurrent(saveToken) else {
                // The snapshot is durable; a request that coalesced behind it keeps the projection
                // dirty and a fresh owner-current save is requested for the newer content.
                requestFreshSaveForCurrentOwner(
                    sessionID: sessionID,
                    fallbackSession: session,
                    context: context
                )
                return commit.disposition == .resetAlreadyCommitted
                    ? notWrittenOutcome
                    : .written(SessionSaveReceipt(
                        sourceItemsRevision: saveReceipt.sourceItemsRevision,
                        persistenceMutationGeneration: saveReceipt.persistenceMutationGeneration,
                        projectionClean: false
                    ))
            }
            if commit.disposition == .resetAlreadyCommitted {
                // The reset barrier was already durable; this acknowledges it, not the newer
                // unsaved edits, which stay dirty and are written by a fresh owner-current save.
                session.isDirty = true
                scheduleSave(for: tabID)
                return .resetAcknowledged
            }
            session.isDirty = false
            // A clean receipt of the current owner and projection satisfies the maximum wait.
            clearTranscriptSaveMaxWait(session)
            session.lastUserMessageAt = lastUserMessageAt
            if let lastUserMessageAt {
                sessionIndexStore.setSortDate(lastUserMessageAt, forTabID: tabID)
            } else {
                sessionIndexStore.removeSortDate(forTabID: tabID)
            }
            upsertSessionIndex(
                sessionID: sessionID,
                tabID: tabID,
                name: sessionName,
                lastUserMessageAt: lastUserMessageAt,
                savedAt: agentSession.savedAt,
                lastRunStateRaw: agentSession.lastRunState,
                itemCount: canonicalItemCount,
                agentKindRaw: agentSession.agentKind,
                agentModelRaw: agentSession.agentModel,
                agentReasoningEffortRaw: agentSession.agentReasoningEffort,
                autoEditEnabled: agentSession.autoEditEnabled,
                parentSessionID: agentSession.parentSessionID,
                isMCPOriginated: agentSession.isMCPOriginated,
                origin: agentSession.origin,
                profile: agentSession.profile,
                worktreeBindingSummaries: agentSession.worktreeBindings.worktreeBindingSummaries,
                remoteHostID: agentSession.remoteHost?.hostID,
                remoteHostName: agentSession.remoteHost?.hostDisplayName,
                remoteSessionID: agentSession.remoteHost?.normalizedRemoteSessionID,
                activeWorktreeMergeSummaries: agentSession.worktreeMergeOperations.activeWorktreeMergeSummaries,
                scheduledSendSummary: AgentSessionScheduledSendSummary.make(from: agentSession.scheduledSend),
                lastScheduledDispatch: agentSession.lastScheduledDispatch
            )
            #if DEBUG
                if let diagnosticsStartMS {
                    AgentModePerfDiagnostics.event(
                        "save.session.complete",
                        tabID: tabID,
                        fields: [
                            "duration": AgentModePerfDiagnostics.formatElapsedMS(since: diagnosticsStartMS),
                            "itemCount": String(canonicalItemCount)
                        ]
                    )
                }
            #endif
            return .written(saveReceipt)
        } catch AgentScheduledSendMutationError.staleDeletionGeneration,
            AgentScheduledSendMutationError.invalidPersistenceStamp,
            AgentScheduledSendMutationError.sessionDeleted,
            AgentScheduledSendMutationError.staleIncarnation
        {
            guard isSaveCommitTokenOwnerCurrent(saveToken) else { return notWrittenOutcome }
            // Committed deletion or a stale lifetime for this exact owner: drop every schedule
            // projection so no later writer recreates the file from this tab's stale state, and
            // never acquire a fresh stamp for it.
            #if DEBUG
                AgentModePerfDiagnostics.event("save.session.deleted", tabID: tabID, fields: ["sessionID": sessionID.uuidString])
            #endif
            handleDurableSessionDeleted(session, sessionID: sessionID)
            return notWrittenOutcome
        } catch AgentScheduledSendMutationError.sessionNotFound {
            guard isSaveCommitTokenOwnerCurrent(saveToken) else { return notWrittenOutcome }
            // Valid lifetime, file missing: accidental loss, not deletion. The dirty data and the
            // captured ownership are kept; the retained recovery (if any) reconstructs the file and
            // a later save writes normally. Nothing is recreated from this tab's transcript.
            #if DEBUG
                AgentModePerfDiagnostics.event("save.session.missingFile", tabID: tabID, fields: ["sessionID": sessionID.uuidString])
            #endif
            print("[AgentModeVM] session file missing for \(sessionID); save deferred until it is restored")
            return notWrittenOutcome
        } catch let AgentScheduledSendMutationError.staleTranscriptResetGeneration(_, reportedResetGeneration) {
            guard isSaveCommitTokenOwnerCurrent(saveToken) else { return notWrittenOutcome }
            // A committed reset this owner does not know about: fail closed. The stale transcript
            // is never rewritten under a refreshed stamp. The exact owner that issued this save
            // retains its working view and drops authority; only an explicitly confirmed paired
            // reload replaces it (`handleStaleTranscriptResetForOwner`).
            #if DEBUG
                AgentModePerfDiagnostics.event("save.session.staleReset", tabID: tabID, fields: ["sessionID": sessionID.uuidString])
            #endif
            handleStaleTranscriptResetForOwner(
                session,
                saveToken: saveToken,
                submittedState: persistenceState,
                reportedResetGeneration: reportedResetGeneration
            )
            return notWrittenOutcome
        } catch {
            #if DEBUG
                AgentModePerfDiagnostics.event("save.session.error", tabID: tabID, fields: ["error": String(describing: error)])
            #endif
            print("[AgentModeVM] Failed to save session: \(error)")
            return notWrittenOutcome
        }
    }

    /// Full persisted snapshot of `session` for `sessionID`: the single builder shared by the
    /// normal save and the recovery transcript-reset commit.
    func makePersistedAgentSession(
        for session: AgentTabSession,
        tabID: UUID,
        sessionID: UUID,
        workspaceID: UUID,
        sessionName: String,
        persistableSnapshot: PersistableTranscriptSnapshot
    ) -> AgentSession {
        let undeliveredRemoteUserItemIDs = Set(session.items.lazy.filter {
            $0.kind == .user && $0.isUndeliveredRemoteSend
        }.map(\.id))
        let persistedRemoteResendPayloadsByItemID: [String: PersistedRemoteResendPayload] = Dictionary(
            uniqueKeysWithValues: session.remoteResendPayloadsByItemID.compactMap { itemID, payload in
                guard undeliveredRemoteUserItemIDs.contains(itemID) else { return nil }
                return (
                    itemID.uuidString,
                    PersistedRemoteResendPayload(
                        providerText: payload.providerText,
                        wasStart: payload.wasStart,
                        modelSelectionRaw: payload.modelSelectionRaw,
                        sessionName: payload.sessionName,
                        workspaceName: payload.workspaceName,
                        windowID: payload.windowID,
                        workspaceID: payload.workspaceID
                    )
                )
            }
        )
        let toolNameByItemID: [UUID: String] = Dictionary(
            uniqueKeysWithValues: session.items.compactMap { item in
                item.toolName.map { (item.id, $0) }
            }
        )
        let uiToolResultPayloadsByItemID: [String: String] = Dictionary(
            uniqueKeysWithValues: session.ephemeralToolResultPayloadByItemID.compactMap { itemID, rawPayload in
                guard let uiPayload = AgentToolResultPersistencePolicy.uiFacingOracleIdentityJSON(
                    toolName: toolNameByItemID[itemID],
                    rawResultJSON: rawPayload
                ) else {
                    return nil
                }
                return (itemID.uuidString, uiPayload)
            }
        )
        var agentSession = AgentSession(
            id: sessionID,
            workspaceID: workspaceID,
            composeTabID: tabID,
            name: sessionName,
            items: [],
            uiToolResultPayloadsByItemID: uiToolResultPayloadsByItemID,
            transcript: persistableSnapshot.transcript,
            itemCount: persistableSnapshot.canonicalVisibleRowCount,
            transcriptProjectionCounts: persistableSnapshot.projectionCounts,
            lastUserMessageAt: persistableSnapshot.lastUserMessageAt,
            agentKind: session.selectedAgent.rawValue,
            agentModel: session.selectedModelRaw,
            ohMyPiThinkingSelections: session.ohMyPiThinkingSelections.nilIfEmpty,
            agentReasoningEffort: session.selectedReasoningEffortRaw,
            lastRunState: session.runState.rawValue,
            providerSessionID: session.providerSessionID,
            remoteHost: session.remoteHost,
            remoteResendPayloadsByItemID: persistedRemoteResendPayloadsByItemID,
            locallyAttributedStartItemID: session.locallyAttributedStartItemID,
            autoEditEnabled: session.autoEditEnabled,
            providerTokenUsageByTurn: session.providerTokenUsageByTurn,
            providerUsage: session.usageAccounting.flatMap {
                $0.ownerSessionID == sessionID ? $0.persistedRepresentation : nil
            },
            parentSessionID: session.parentSessionID,
            pendingHandoffPayload: session.pendingHandoff.payload,
            pendingHandoffCreatedAt: session.pendingHandoff.createdAt,
            pendingHandoffSourceItemID: session.pendingHandoff.sourceItemID,
            pendingHandoffPayloadID: session.pendingHandoff.payloadID,
            pendingHandoffDefersProviderLockUntilSend: session.pendingHandoff.defersProviderLockUntilSend,
            scheduledSend: session.scheduledSend,
            lastScheduledDispatch: session.lastScheduledDispatch,
            isMCPOriginated: session.isMCPOriginated,
            origin: session.origin,
            profile: session.profile,
            worktreeBindings: session.worktreeBindings,
            worktreeMergeOperations: session.worktreeMergeOperations,
            providerHistoryRecovery: session.providerHistoryRecovery
        )
        codexCoordinator.applyCodexPersistence(from: session, to: &agentSession)
        return agentSession
    }

    /// Whether an unbound session has anything a save would persist (unbound sessions without
    /// conversation content are never written).
    func hasPersistableConversationContent(_ session: AgentTabSession) -> Bool {
        !session.items.isEmpty || !session.transcript.turns.isEmpty || session.runState.isActive || session.hasPendingQuestionUI || session.pendingApproval != nil || session.pendingPermissionsRequest != nil || session.pendingApplyEditsReview != nil || session.pendingWorktreeMergeReview != nil || session.worktreeMergeOperations.contains { $0.status.isActive } || session.scheduledSend != nil
    }

    func isSaveInFlight(sessionID: UUID) -> Bool {
        saveInFlightSessionIDs.contains(sessionID)
    }

    /// Suspends until no save is in flight for the durable session (removal operations settle
    /// outstanding saves before their final save and before the final batch check).
    func awaitInFlightSave(sessionID: UUID) async {
        while saveInFlightSessionIDs.contains(sessionID) {
            await withCheckedContinuation { continuation in
                saveCompletionWaiters[sessionID, default: []].append(continuation)
            }
        }
    }

    @discardableResult
    func flushSave(for tabID: UUID) async -> Bool {
        await flushSaveDetailed(for: tabID).isCleanSuccess
    }

    /// Immediate save with the precise durable outcome (see `SessionSaveOutcome`).
    @discardableResult
    func flushSaveDetailed(
        for tabID: UUID,
        context: SessionPersistenceContext? = nil
    ) async -> SessionSaveOutcome {
        guard let session = sessions[tabID] else { return .notWritten }
        session.saveDebounceTask?.cancel()
        return await saveSessionDetailed(for: tabID, context: context)
    }

    private func persistCurrentSession() {
        guard !AppLaunchConfiguration.current.suppressesAgentSessionPersistence else { return }
        guard let tabID = currentTabID else { return }
        Task {
            await flushSave(for: tabID)
        }
    }

    // MARK: - User Interaction

    func ensureMCPServerEnabledForThreadStart() async {
        await mcpServerEnabler()
    }

    func hasLiveRunRouteInCurrentMCPServer(_ runID: UUID) -> Bool {
        mcpServer?.hasLiveRunID(runID) == true
    }

    @discardableResult
    func submitUserTurnCreatingSessionIfNeeded(text: String) async -> UserTurnSubmissionResult {
        guard let sourceTabID = currentTabID else {
            return .blocked(message: "")
        }
        guard let target = makeComposerSubmitTarget(tabID: sourceTabID, session: sessions[sourceTabID]) else {
            return .blocked(message: Self.staleComposerSubmitTargetMessage)
        }
        return await submitUserTurnCreatingSessionIfNeeded(text: text, target: target)
    }

    @discardableResult
    func submitUserTurnCreatingSessionIfNeeded(
        text: String,
        target: AgentComposerSubmitTarget
    ) async -> UserTurnSubmissionResult {
        await submitUserTurnCreatingSessionIfNeeded(
            text: text,
            target: target,
            createAndActivateSessionTab: { [weak self] in
                await self?.createAndActivateSessionTab()
            }
        )
    }

    @discardableResult
    func submitUserTurnCreatingSessionIfNeeded(
        text: String,
        target: AgentComposerSubmitTarget,
        createAndActivateSessionTab: () async -> UUID?
    ) async -> UserTurnSubmissionResult {
        let attempt = AgentComposerSubmitAttempt(
            id: UUID(),
            target: target,
            inputRevision: 0,
            noticeRevision: 0,
            rawDraftSnapshot: text
        )
        switch claimComposerSubmitAttempt(attempt, requireActiveTabOwnership: false) {
        case let .claimed(claim):
            return await executeComposerSubmitAttempt(
                text: text,
                claim: claim,
                createAndActivateSessionTab: createAndActivateSessionTab
            )
        case .rejected:
            return .blocked(message: Self.staleComposerSubmitTargetMessage)
        }
    }

    @discardableResult
    func executeComposerSubmitAttempt(
        text: String,
        claim: AgentComposerSubmitClaim
    ) async -> UserTurnSubmissionResult {
        await executeComposerSubmitAttempt(
            text: text,
            claim: claim,
            createAndActivateSessionTab: { [weak self] in
                await self?.createAndActivateSessionTab()
            }
        )
    }

    @discardableResult
    func executeComposerSubmitAttempt(
        text: String,
        claim: AgentComposerSubmitClaim,
        createAndActivateSessionTab: () async -> UUID?
    ) async -> UserTurnSubmissionResult {
        let target = claim.attempt.target
        let claimedSourceSession = claim.sourceSession
        guard composerSubmitClaimIsCurrent(claim) else {
            return .blocked(message: Self.staleComposerSubmitTargetMessage)
        }
        defer {
            releaseComposerSubmitClaim(claim)
        }

        switch target.route {
        case .existingAgentSession:
            guard let preparedSession = try? await ensureSessionReady(tabID: target.tabID) else {
                return .blocked(message: Self.composeTabRemovalInProgressMessage)
            }
            guard preparedSession === claimedSourceSession,
                  composerSubmitClaimIsCurrent(claim)
            else {
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            if let blockedMessage = newWorkBlockedMessage(for: preparedSession) {
                return .blocked(message: blockedMessage)
            }
            if let rejectionReason = submitTargetRejectionReason(
                target,
                session: preparedSession,
                validateSubmissionToken: false
            ) {
                logRejectedSubmitTarget(target, session: preparedSession, reason: rejectionReason)
                resyncAfterRejectedSubmitTarget(target)
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            let pendingState = Self.pendingUserTurnState(from: preparedSession)
            guard let initialLocation = target.expectedInitialStartLocation,
                  initialLocation != .local,
                  pendingState.initialStartLocation == initialLocation
            else {
                let result = await submitUserTurnAdmittingRecoveryInput(
                    text: text,
                    tabID: target.tabID,
                    origin: .composer,
                    isStillCurrent: {
                        self.composerSubmitClaimIsCurrent(claim) && self.sessions[target.tabID] === preparedSession
                    }
                )
                if result == .submitted {
                    clearComposerDraftIfUnchanged(for: claim)
                }
                return result
            }
            let sourceSnapshot = FirstSendSourceSnapshot(
                session: preparedSession,
                fallbackSelectedAgent: selectedAgent,
                fallbackSelectedModelRaw: selectedModelRaw,
                fallbackSelectedReasoningEffortRaw: selectedReasoningEffortRaw,
                fallbackAutoEditEnabled: autoEditEnabled
            )
            preparedSession.isPreparingInitialWorktree = true
            syncComposerUIState(tabID: target.tabID)
            syncStatusPillsUIState()
            defer {
                preparedSession.isPreparingInitialWorktree = false
                if target.tabID == currentTabID {
                    syncComposerUIState(tabID: target.tabID)
                    syncStatusPillsUIState()
                }
            }
            if let blocked = preflightInitialUserTurn(text: text, session: preparedSession) {
                return blocked
            }
            do {
                try await prepareInitialExecutionLocation(initialLocation, for: preparedSession) {
                    !Task.isCancelled
                        && self.composerSubmitClaimIsCurrent(claim)
                        && self.sessions[target.tabID] === preparedSession
                        && self.composerSourceAgentSessionID(
                            tabID: target.tabID,
                            session: preparedSession
                        ) == target.expectedSourceAgentSessionID
                        && sourceSnapshot.matches(self.sessions[target.tabID])
                        && Self.pendingUserTurnState(from: preparedSession) == pendingState
                }
            } catch {
                return .blocked(message: (error as? LocalizedError)?.errorDescription ?? error.localizedDescription)
            }
            guard composerSourceAgentSessionID(tabID: target.tabID, session: preparedSession)
                == target.expectedSourceAgentSessionID
            else {
                logRejectedSubmitTarget(target, session: preparedSession, reason: "agent_session_id_mismatch")
                resyncAfterRejectedSubmitTarget(target)
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            guard !Task.isCancelled,
                  composerSubmitClaimIsCurrent(claim),
                  sessions[target.tabID] === preparedSession,
                  sourceSnapshot.matches(sessions[target.tabID]),
                  Self.pendingUserTurnState(from: preparedSession) == pendingState
            else {
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            if let blocked = preflightInitialUserTurn(text: text, session: preparedSession) {
                return blocked
            }
            preparedSession.pendingInitialStartLocation = .local
            if target.tabID == currentTabID {
                applySessionToBindings(preparedSession)
            }
            let result = await submitUserTurnAdmittingRecoveryInput(
                text: text,
                tabID: target.tabID,
                origin: .composer,
                isStillCurrent: {
                    self.composerSubmitClaimIsCurrent(claim) && self.sessions[target.tabID] === preparedSession
                }
            )
            if result == .submitted {
                clearComposerDraftIfUnchanged(for: claim)
            }
            return result
        case .createAgentSessionFromSourceTab:
            let sourceSession = claimedSourceSession
            let sourceSnapshot = FirstSendSourceSnapshot(
                session: sourceSession,
                fallbackSelectedAgent: selectedAgent,
                fallbackSelectedModelRaw: selectedModelRaw,
                fallbackSelectedReasoningEffortRaw: selectedReasoningEffortRaw,
                fallbackAutoEditEnabled: autoEditEnabled
            )
            let pendingState = Self.pendingUserTurnState(from: sourceSession)
            let preparesExecutionLocation = pendingState.initialStartLocation != .local
            if preparesExecutionLocation {
                do {
                    try await preflightInitialExecutionLocationWorkspace {
                        !Task.isCancelled
                            && self.composerSubmitClaimIsCurrent(claim)
                            && self.sessions[target.tabID] === sourceSession
                            && sourceSnapshot.matches(self.sessions[target.tabID])
                            && Self.pendingUserTurnState(from: sourceSession) == pendingState
                    }
                } catch {
                    return .blocked(message: (error as? LocalizedError)?.errorDescription ?? error.localizedDescription)
                }
                sourceSession.isPreparingInitialWorktree = true
                syncComposerUIState(tabID: target.tabID)
                syncStatusPillsUIState()
            }
            defer {
                if preparesExecutionLocation {
                    sourceSession.isPreparingInitialWorktree = false
                    if target.tabID == currentTabID {
                        syncComposerUIState(tabID: target.tabID)
                        syncStatusPillsUIState()
                    }
                }
            }
            guard let destinationTabID = await createAndActivateSessionTab() else {
                return .blocked(message: "Failed to create a new agent session.")
            }
            guard !Task.isCancelled,
                  composerSubmitClaimIsCurrent(claim)
            else {
                await discardFreshFirstSendDestinationIfPossible(destinationTabID)
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            guard sessions[target.tabID] === sourceSession else {
                await discardFreshFirstSendDestinationIfPossible(destinationTabID)
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            if let rejectionReason = submitTargetRejectionReason(
                target,
                session: sourceSession,
                validateSubmissionToken: false
            ) {
                logRejectedSubmitTarget(target, session: sessions[target.tabID], reason: rejectionReason)
                resyncAfterRejectedSubmitTarget(target)
                await discardFreshFirstSendDestinationIfPossible(destinationTabID)
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            guard composerSubmitClaimIsCurrent(claim),
                  sourceSnapshot.matches(sessions[target.tabID])
            else {
                logRejectedSubmitTarget(target, session: sessions[target.tabID], reason: "source_pending_state_changed")
                resyncAfterRejectedSubmitTarget(target)
                await discardFreshFirstSendDestinationIfPossible(destinationTabID)
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            guard destinationTabID != target.tabID else {
                logRejectedSubmitTarget(target, session: sessions[target.tabID], reason: "invalid_first_send_destination")
                resyncAfterRejectedSubmitTarget(target)
                await discardFreshFirstSendDestinationIfPossible(destinationTabID)
                return .blocked(message: "Failed to create a new agent session.")
            }
            guard let destinationSession = session(for: destinationTabID, createIfNeeded: true),
                  isFreshFirstSendDestination(destinationSession)
            else {
                logRejectedSubmitTarget(target, session: sessions[target.tabID], reason: "invalid_first_send_destination")
                resyncAfterRejectedSubmitTarget(target)
                await discardFreshFirstSendDestinationIfPossible(destinationTabID)
                return .blocked(message: "Failed to create a new agent session.")
            }
            if preparesExecutionLocation {
                destinationSession.isPreparingInitialWorktree = true
                syncComposerUIState(tabID: destinationTabID)
            }
            defer {
                if preparesExecutionLocation {
                    destinationSession.isPreparingInitialWorktree = false
                    if destinationTabID == currentTabID {
                        syncComposerUIState(tabID: destinationTabID)
                    }
                }
            }
            sourceSnapshot.applySessionSettings(to: destinationSession)
            // V1-3: install unconditionally so the destination's remote-host state
            // always matches what the source's run-location pill showed at send
            // time. An empty pending state (remoteHost == nil) reconciles away
            // the unconditional `createAndActivateSessionTab()` workspace-default
            // auto-bind after an explicit "This Mac" selection on the source;
            // otherwise the post-prepare `pendingUserTurnState == pendingState`
            // guard below can never be satisfied and the first send blocks.
            installPendingUserTurnState(pendingState, on: destinationSession)
            if let blocked = preflightInitialUserTurn(text: text, session: destinationSession) {
                clearPendingUserTurnState(on: destinationSession)
                await discardFreshFirstSendDestinationIfPossible(destinationTabID)
                return blocked
            }
            if preparesExecutionLocation {
                do {
                    try await prepareInitialExecutionLocation(pendingState.initialStartLocation, for: destinationSession) {
                        !Task.isCancelled
                            && self.composerSubmitClaimIsCurrent(claim)
                            && self.sessions[destinationTabID] === destinationSession
                            && self.sessions[target.tabID] === sourceSession
                            && sourceSnapshot.matches(self.sessions[target.tabID])
                            && Self.pendingUserTurnState(from: destinationSession) == pendingState
                    }
                } catch {
                    clearPendingUserTurnState(on: destinationSession)
                    await discardFreshFirstSendDestinationIfPossible(destinationTabID)
                    return .blocked(message: (error as? LocalizedError)?.errorDescription ?? error.localizedDescription)
                }
            }
            guard !Task.isCancelled,
                  composerSubmitClaimIsCurrent(claim),
                  sessions[destinationTabID] === destinationSession,
                  sessions[target.tabID] === sourceSession,
                  sourceSnapshot.matches(sessions[target.tabID]),
                  Self.pendingUserTurnState(from: destinationSession) == pendingState
            else {
                clearPendingUserTurnState(on: destinationSession)
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            if let blocked = preflightInitialUserTurn(text: text, session: destinationSession) {
                clearPendingUserTurnState(on: destinationSession)
                return blocked
            }
            destinationSession.pendingInitialStartLocation = .local
            if destinationTabID == currentTabID {
                applySessionToBindings(destinationSession)
            }
            let result = await submitUserTurnAdmittingRecoveryInput(
                text: text,
                tabID: destinationTabID,
                origin: .composer,
                isStillCurrent: {
                    self.composerSubmitClaimIsCurrent(claim)
                        && self.sessions[destinationTabID] === destinationSession
                        && self.sessions[target.tabID] === sourceSession
                }
            )
            guard result == .submitted else {
                clearPendingUserTurnState(on: destinationSession)
                return result
            }
            clearPendingUserTurnState(on: sourceSession)
            // V1-3: the clear wiped the still-sessionless source tab's remote-run
            // intent while leaving its pinned host-default model raw behind.
            // Re-apply the binding the pill actually showed at send time so the
            // source stays coherent (bound + pinned) for the next first-send;
            // an explicit "This Mac" source (pendingState.remoteHost == nil)
            // stays unbound. The re-apply only fails when the host was revoked
            // or removed mid-flight (the user turn landed on the destination,
            // so hasSubmittedTurn cannot trip here) — in that case drop the
            // leftover pinned sentinel so the unbound source stays coherent.
            if let boundHostID = pendingState.remoteHost?.hostID,
               !applyHostRunLocation(hostID: boundHostID, to: sourceSession),
               sourceSession.selectedModelRaw == RemoteHostAgentCatalog.hostDefaultModelID
            {
                sourceSession.selectedModelRaw = defaultModelRaw(for: sourceSession.selectedAgent)
            }
            clearComposerDraftIfUnchanged(for: claim)
            return result
        }
    }

    @discardableResult
    func submitUserTurnCreatingSessionIfNeeded(
        text: String,
        sourceTabID: UUID,
        createAndActivateSessionTab: () async -> UUID?
    ) async -> UserTurnSubmissionResult {
        guard let target = makeComposerSubmitTarget(tabID: sourceTabID, session: sessions[sourceTabID]) else {
            return .blocked(message: Self.staleComposerSubmitTargetMessage)
        }
        return await submitUserTurnCreatingSessionIfNeeded(
            text: text,
            target: target,
            createAndActivateSessionTab: createAndActivateSessionTab
        )
    }

    @MainActor
    struct FirstSendSourceSnapshot {
        let sourceSessionExisted: Bool
        let selectedAgent: AgentProviderKind
        let selectedModelRaw: String
        let selectedReasoningEffortRaw: String?
        let autoEditEnabled: Bool
        let profile: AgentSessionProfile
        let selectedWorkflow: AgentWorkflowDefinition?
        let imageAttachments: [AgentImageAttachment]
        let taggedFileAttachments: [AgentTaggedFileAttachment]
        let initialStartLocation: AgentInitialStartLocation
        let remoteHost: AgentSessionRemoteHostBinding?

        init(
            session: AgentTabSession?,
            fallbackSelectedAgent: AgentProviderKind,
            fallbackSelectedModelRaw: String,
            fallbackSelectedReasoningEffortRaw: String?,
            fallbackAutoEditEnabled: Bool
        ) {
            sourceSessionExisted = session != nil
            selectedAgent = session?.selectedAgent ?? fallbackSelectedAgent
            selectedModelRaw = session?.selectedModelRaw ?? fallbackSelectedModelRaw
            selectedReasoningEffortRaw = session?.selectedReasoningEffortRaw ?? fallbackSelectedReasoningEffortRaw
            autoEditEnabled = session?.autoEditEnabled ?? fallbackAutoEditEnabled
            profile = session?.profile ?? .standard
            selectedWorkflow = session?.selectedWorkflow
            imageAttachments = session?.pendingImageAttachments ?? []
            taggedFileAttachments = session?.pendingTaggedFileAttachments ?? []
            initialStartLocation = session?.pendingInitialStartLocation ?? .local
            remoteHost = session?.remoteHost
        }

        func matches(_ session: AgentTabSession?) -> Bool {
            guard let session else { return !sourceSessionExisted }
            guard sourceSessionExisted else { return false }
            return selectedAgent == session.selectedAgent
                && selectedModelRaw == session.selectedModelRaw
                && selectedReasoningEffortRaw == session.selectedReasoningEffortRaw
                && autoEditEnabled == session.autoEditEnabled
                && profile == session.profile
                && selectedWorkflow == session.selectedWorkflow
                && imageAttachments == session.pendingImageAttachments
                && taggedFileAttachments == session.pendingTaggedFileAttachments
                && initialStartLocation == session.pendingInitialStartLocation
                && remoteHost == session.remoteHost
        }

        func applySessionSettings(to session: AgentTabSession) {
            session.selectedAgent = selectedAgent
            session.selectedModelRaw = selectedModelRaw
            session.selectedReasoningEffortRaw = selectedReasoningEffortRaw
            session.autoEditEnabled = autoEditEnabled
            _ = session.adoptSessionProfile(profile)
        }
    }

    func isFreshFirstSendDestination(_ session: AgentTabSession) -> Bool {
        !session.runState.isActive
            && session.runID == nil
            && session.activeRunAttemptID == nil
            && session.items.isEmpty
            && session.transcript.turns.isEmpty
            && session.pendingImageAttachments.isEmpty
            && session.pendingTaggedFileAttachments.isEmpty
            && session.selectedWorkflow == nil
    }

    func preflightInitialUserTurn(text: String, session: AgentTabSession) -> UserTurnSubmissionResult? {
        let trimmedText = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let attachments = session.pendingImageAttachments
        let taggedFiles = session.pendingTaggedFileAttachments
        guard !trimmedText.isEmpty || !attachments.isEmpty || !taggedFiles.isEmpty else {
            return .blocked(message: "")
        }
        if session.profile == .knowledge,
           !KnowledgeSessionPolicy.supportedProviders.contains(session.selectedAgent)
        {
            return .blocked(
                message: "Knowledge sessions currently support Claude Code and Codex. Start a standard session for other providers."
            )
        }
        if session.remoteHost == nil {
            guard AgentModelCatalog.isAgentAvailable(session.selectedAgent, availability: agentAvailabilityContext) else {
                return .blocked(message: unavailableAgentMessage(for: session.selectedAgent))
            }
        }
        let workflow = session.selectedWorkflow
        if let nativeSlashCommand = resolvedNativeSlashCommand(in: trimmedText, session: session),
           let validationFailure = validateNativeSlashCommandUsage(
               nativeSlashCommand,
               session: session,
               attachments: attachments,
               taggedFiles: taggedFiles,
               activeWorkflow: workflow
           )
        {
            return validationFailure
        }
        if resolvedNativeSlashCommand(in: trimmedText, session: session) == nil,
           let validationFailure = validateSlashSkillUsage(in: trimmedText, activeWorkflow: workflow)
        {
            return validationFailure
        }
        return nil
    }

    private enum InitialNewWorktreePreparationError: LocalizedError {
        case unavailable(String)
        case failed(String)
        case retainedWorktree(path: String, underlying: String)

        var errorDescription: String? {
            switch self {
            case let .unavailable(message), let .failed(message):
                message
            case let .retainedWorktree(path, underlying):
                "The new worktree was created at \(path), but could not be bound to this thread. It was not removed; use worktree management to inspect or remove it. Error: \(underlying)"
            }
        }
    }

    private func preflightInitialExecutionLocationWorkspace(
        validating operationIsCurrent: () -> Bool
    ) async throws {
        guard let workspaceManager,
              let workspace = workspaceManager.activeWorkspace,
              !workspace.isSystemWorkspace,
              let primaryRoot = workspace.repoPaths.first,
              let promptManager
        else {
            throw InitialNewWorktreePreparationError.unavailable(
                "Execution location requires an active Git-backed project workspace. Select Work locally or open a Git workspace."
            )
        }
        guard !Task.isCancelled, operationIsCurrent() else {
            throw InitialNewWorktreePreparationError.unavailable(Self.staleComposerSubmitTargetMessage)
        }
        let primaryPath = Self.standardizedWorkspacePath((primaryRoot as NSString).expandingTildeInPath) ?? primaryRoot
        let visibleRoots = await promptManager.workspaceFileContextStore.rootRefs(scope: .visibleWorkspace)
        guard !Task.isCancelled, operationIsCurrent() else {
            throw InitialNewWorktreePreparationError.unavailable(Self.staleComposerSubmitTargetMessage)
        }
        guard visibleRoots.contains(where: {
            (Self.standardizedWorkspacePath($0.standardizedFullPath) ?? $0.standardizedFullPath) == primaryPath
        }) else {
            throw InitialNewWorktreePreparationError.unavailable(
                "Execution location requires the primary workspace root to be loaded before starting this thread. Select Work locally or reload the workspace."
            )
        }
        guard let resolvedRepo = await VCSService.shared.resolveRepo(from: URL(fileURLWithPath: primaryPath)),
              resolvedRepo.backendKind == .git
        else {
            throw InitialNewWorktreePreparationError.unavailable(
                "Execution location requires a Git-backed primary workspace root. Select Work locally or open a Git workspace."
            )
        }
        guard !Task.isCancelled, operationIsCurrent() else {
            throw InitialNewWorktreePreparationError.unavailable(Self.staleComposerSubmitTargetMessage)
        }
    }

    func prepareInitialExecutionLocation(
        _ choice: AgentInitialStartLocation,
        for session: AgentTabSession,
        validating operationIsCurrent: () -> Bool
    ) async throws {
        guard let sessionID = session.activeAgentSessionID,
              let workspaceManager,
              let workspace = workspaceManager.activeWorkspace,
              !workspace.isSystemWorkspace,
              let primaryRoot = workspace.repoPaths.first,
              let promptManager
        else {
            throw InitialNewWorktreePreparationError.unavailable(
                "Execution location requires an active Git-backed project workspace. Select Work locally or open a Git workspace."
            )
        }
        guard !Task.isCancelled,
              isReadyForInitialNewWorktreeCommit(session),
              operationIsCurrent()
        else {
            throw InitialNewWorktreePreparationError.unavailable(Self.staleComposerSubmitTargetMessage)
        }
        let primaryPath = Self.standardizedWorkspacePath((primaryRoot as NSString).expandingTildeInPath) ?? primaryRoot
        let visibleRoots = await promptManager.workspaceFileContextStore.rootRefs(scope: .visibleWorkspace)
        guard !Task.isCancelled, operationIsCurrent() else {
            throw InitialNewWorktreePreparationError.unavailable(Self.staleComposerSubmitTargetMessage)
        }
        guard let logicalRoot = visibleRoots.first(where: {
            (Self.standardizedWorkspacePath($0.standardizedFullPath) ?? $0.standardizedFullPath) == primaryPath
        }) else {
            throw InitialNewWorktreePreparationError.unavailable(
                "Execution location requires the primary workspace root to be loaded before starting this thread. Select Work locally or reload the workspace."
            )
        }
        guard let resolvedRepo = await VCSService.shared.resolveRepo(from: URL(fileURLWithPath: primaryPath)),
              resolvedRepo.backendKind == .git
        else {
            throw InitialNewWorktreePreparationError.unavailable(
                "Execution location requires a Git-backed primary workspace root. Select Work locally or open a Git workspace."
            )
        }
        guard !Task.isCancelled, operationIsCurrent() else {
            throw InitialNewWorktreePreparationError.unavailable(Self.staleComposerSubmitTargetMessage)
        }
        let repo = GitRepoDescriptor(rootURL: resolvedRepo.rootURL)
        var createdWorktree: GitWorktreeDescriptor?
        do {
            let existingWorktrees = try await VCSService.shared.listGitWorktrees(at: repo.rootURL)
            guard !Task.isCancelled,
                  isReadyForInitialNewWorktreeCommit(session),
                  operationIsCurrent()
            else {
                throw InitialNewWorktreePreparationError.unavailable(Self.staleComposerSubmitTargetMessage)
            }
            let worktree: GitWorktreeDescriptor
            let bindingSource: String
            switch choice {
            case .local:
                return
            case .newWorktree:
                let mainRootPath = existingWorktrees.first(where: \.isMain)?.path ?? repo.rootPath
                let plan = try GitWorktreeDefaultPathPlanner.plan(
                    .init(
                        mainWorktreeRoot: URL(fileURLWithPath: mainRootPath),
                        existingWorktreeRoots: existingWorktrees.map { URL(fileURLWithPath: $0.path) },
                        purpose: .agentStart(sessionID: sessionID.uuidString)
                    )
                )
                worktree = try await VCSService.shared.createGitWorktree(request: plan.createRequest, at: repo.rootURL)
                createdWorktree = worktree
                bindingSource = "agent_ui.initial_send"
            case let .existingWorktree(selection):
                guard let selected = existingWorktrees.first(where: {
                    $0.repository.repositoryID == selection.repositoryID && $0.worktreeID == selection.worktreeID
                }), !selected.isPrunable else {
                    throw InitialNewWorktreePreparationError.failed("The selected existing worktree is no longer available. Choose another execution location.")
                }
                worktree = selected
                bindingSource = "agent_ui.initial_send_existing"
            }
            func locationBindingFailure(_ message: String) -> InitialNewWorktreePreparationError {
                if let createdWorktree {
                    return .retainedWorktree(path: createdWorktree.path, underlying: message)
                }
                return .failed("Could not bind the selected existing worktree: \(message)")
            }
            guard !Task.isCancelled,
                  isReadyForInitialNewWorktreeCommit(session),
                  operationIsCurrent()
            else {
                throw locationBindingFailure(Self.staleComposerSubmitTargetMessage)
            }
            let label = GitWorktreeDisplayLabelHumanizer.seededVisualIdentityLabel(
                sessionName: resolvedSessionDisplayName(for: session.tabID),
                worktreeName: worktree.name,
                branch: worktree.branch,
                isMain: worktree.isMain
            )
            let identity = try GlobalSettingsStore.shared.ensureWorktreeVisualIdentity(
                repositoryID: worktree.repository.repositoryID,
                worktreeID: worktree.worktreeID,
                label: label
            )
            let binding = AgentSessionWorktreeBinding(
                id: UUID().uuidString,
                repositoryID: worktree.repository.repositoryID,
                repoKey: worktree.repository.repoKey,
                logicalRootPath: logicalRoot.standardizedFullPath,
                logicalRootName: logicalRoot.name,
                worktreeID: worktree.worktreeID,
                worktreeRootPath: worktree.path,
                worktreeName: worktree.name,
                branch: worktree.branch,
                head: worktree.head,
                visualLabel: identity.label,
                visualColorHex: identity.colorHex,
                source: bindingSource
            )
            guard !Task.isCancelled,
                  operationIsCurrent(),
                  isReadyForInitialNewWorktreeCommit(session)
            else {
                throw locationBindingFailure(Self.staleComposerSubmitTargetMessage)
            }
            do {
                _ = try await transitionWorktreeBindings(
                    [binding],
                    forSessionID: sessionID,
                    intent: .initialSend
                )
            } catch {
                throw locationBindingFailure(
                    (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
                )
            }
        } catch let error as InitialNewWorktreePreparationError {
            throw error
        } catch {
            let message = (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
            if let createdWorktree {
                throw InitialNewWorktreePreparationError.retainedWorktree(path: createdWorktree.path, underlying: message)
            }
            throw InitialNewWorktreePreparationError.failed("Could not prepare the selected execution location: \(message)")
        }
    }

    private func isReadyForInitialNewWorktreeCommit(_ session: AgentTabSession) -> Bool {
        session.isPreparingInitialWorktree
            && !session.hasSentFirstMessage
            && session.runState == .idle
            && session.runID == nil
            && session.activeRunAttemptID == nil
            && session.providerSessionID == nil
            && session.codexConversationID == nil
            && session.worktreeBindings.isEmpty
            && session.items.isEmpty
            && session.transcript.turns.isEmpty
            && session.mcpControlContext == nil
            && !session.isMCPOriginated
            && session.parentSessionID == nil
            && !session.pendingHandoff.hasPayload
    }

    func discardFreshFirstSendDestinationIfPossible(_ tabID: UUID) async {
        guard let session = sessions[tabID], isFreshFirstSendDestination(session) else { return }
        if promptManager?.currentComposeTabs.contains(where: { $0.id == tabID }) == true {
            await promptManager?.closeComposeTab(tabID)
        } else {
            clearRemoteStartWindowPickerIfOwned(by: tabID)
            remoteCoordinator.stop(tabID: tabID)
            sessions.removeValue(forKey: tabID)
            sessionIndexStore.removeSortDate(forTabID: tabID)
            removePendingUIRefresh(for: tabID)
        }
    }

    /// Submits one user turn. `admitted` is the durably admitted snapshot (R12) and is required
    /// whenever recovery admission is not inactive; `nil` selects the legacy untracked input of
    /// inactive admission explicitly (F1: no implicit default).
    @discardableResult
    func submitUserTurn(
        text: String,
        tabID: UUID,
        codexAttemptID: UUID?,
        admitted: AdmittedUserTurnInput?
    ) -> UserTurnSubmissionResult {
        guard let session = session(for: tabID, createIfNeeded: true) else {
            return .blocked(message: Self.composeTabRemovalInProgressMessage)
        }
        if let blockedMessage = newWorkBlockedMessage(for: session) {
            return .blocked(message: blockedMessage)
        }
        let trimmedText = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let attachmentsToSend = admitted?.attachments ?? session.pendingImageAttachments
        let taggedFilesToSend = admitted?.taggedFiles ?? session.pendingTaggedFileAttachments
        guard !trimmedText.isEmpty || !attachmentsToSend.isEmpty || !taggedFilesToSend.isEmpty else {
            return .blocked(message: "")
        }
        if session.remoteHost == nil {
            guard AgentModelCatalog.isAgentAvailable(session.selectedAgent, availability: agentAvailabilityContext) else {
                return .blocked(message: unavailableAgentMessage(for: session.selectedAgent))
            }
        }

        scheduleSkillCatalogRefresh()

        let activeWorkflow = if let admitted { admitted.workflow } else { session.selectedWorkflow }
        let nativePreparedTurn: NativeSlashPreparedUserTurn?
        if let nativeSlashCommand = resolvedNativeSlashCommand(in: trimmedText, session: session) {
            if let validationFailure = validateNativeSlashCommandUsage(
                nativeSlashCommand,
                session: session,
                attachments: attachmentsToSend,
                taggedFiles: taggedFilesToSend,
                activeWorkflow: activeWorkflow
            ) {
                return validationFailure
            }
            switch nativeSlashCommand.command.behavior {
            case .controlPlane:
                // An explicit recovery action's payload is a user turn; a control-plane command has
                // no dispatch its hold could settle on (review A P1-01).
                if admitted?.identity.actionAuthorization != nil {
                    return .blocked(message: "A recovery message can't run a slash command. Nothing was sent.")
                }
                let goalAction: CodexAgentModeCoordinator.GoalSlashAction? = nativeSlashCommand.command == .goal
                    ? CodexAgentModeCoordinator.goalSlashAction(from: nativeSlashCommand.argumentsText)
                    : nil
                let progressRestoreState = beginNativeSlashControlProgressIfNeeded(
                    command: nativeSlashCommand.command,
                    action: goalAction,
                    session: session
                )
                appendOptimisticGoalObjectiveUserBubbleIfNeeded(
                    action: goalAction,
                    session: session,
                    workflow: activeWorkflow
                )
                Task { [weak self] in
                    guard let self else { return }
                    if let codexAttemptID {
                        guard await session.codexSteerAckTracker.awaitDispatchAuthorization(
                            attemptID: codexAttemptID
                        ) else { return }
                    }
                    let result = await submitNativeSlashCommandAfterHydration(
                        tabID: tabID,
                        invocation: nativeSlashCommand,
                        selectedWorkflowForGoal: activeWorkflow,
                        progressRestoreState: progressRestoreState
                    )
                    guard let codexAttemptID else { return }
                    let state: CodexSteerAckTracker.TerminalState = switch result {
                    case .succeeded:
                        .controlAccepted
                    case let .failed(message):
                        .failed(message: message)
                    case nil:
                        .stale(reason: "Native Codex slash command could not be delivered because the session changed before execution.")
                    }
                    session.codexSteerAckTracker.resolve(attemptID: codexAttemptID, state: state)
                }
                return .submitted
            case .userTurnWrapper:
                nativePreparedTurn = prepareNativeSlashPreparedUserTurn(nativeSlashCommand)
            }
        } else {
            nativePreparedTurn = nil
        }
        // F1: a user turn under non-inactive admission needs its admitted snapshot; refuse before any
        // clearing, bubble, attachment reservation, or MCP signal (control-plane commands above
        // carry no user turn).
        if admitted == nil, session.recoveryAdmissionMode != .inactive {
            return .blocked(message: Self.durableQueueAdmissionRequiredMessage)
        }
        if nativePreparedTurn == nil,
           let validationFailure = validateSlashSkillUsage(in: trimmedText, activeWorkflow: activeWorkflow)
        {
            return validationFailure
        }

        // If no explicit workflow but a slash-skill is present, create a display-only
        // workflow for the chat bubble so the user sees which skill was used.
        // template is nil → wrapUserText is a no-op; actual expansion happens later
        // via expandSlashSkillInvocationIfNeeded in the augmentation path.
        let bubbleWorkflow: AgentWorkflowDefinition? = {
            if let nativePreparedTurn {
                return nativePreparedTurn.bubbleWorkflow
            }
            if activeWorkflow != nil {
                return activeWorkflow
            }
            guard let invocation = resolvedSlashSkillInvocations(in: trimmedText).first else { return nil }
            return invocation.definition.asBubbleWorkflowDefinition()
        }()

        // Capture and clear workflow before sending. An admitted composer snapshot removes only what
        // it submitted, so edits made since admission survive (R12); an admitted non-composer input
        // (MCP) never touches the composer.
        if let admitted {
            if admitted.consumesComposer {
                consumeSubmittedComposerInput(admitted, session: session)
            }
        } else {
            session.selectedWorkflow = nil
            selectedWorkflow = nil
            session.pendingImageAttachments.removeAll()
            session.pendingTaggedFileAttachments.removeAll()
        }

        if session.activeAgentSessionID != nil, !session.hasLoadedPersistedState {
            Self.logCodexDebug("[AgentModeVM][RunID] deferring send until hydration completes for tab \(tabID)")
            Task { [weak self] in
                guard let self else { return }
                await submitUserTurnAfterHydration(
                    tabID: tabID,
                    trimmedText: trimmedText,
                    attachmentsToSend: attachmentsToSend,
                    taggedFilesToSend: taggedFilesToSend,
                    activeWorkflow: bubbleWorkflow,
                    nativePreparedTurn: nativePreparedTurn,
                    codexAttemptID: codexAttemptID,
                    admitted: admitted
                )
            }
            return .submitted
        }

        return submitPreparedUserTurn(
            tabID: tabID,
            session: session,
            trimmedText: trimmedText,
            attachmentsToSend: attachmentsToSend,
            taggedFilesToSend: taggedFilesToSend,
            activeWorkflow: bubbleWorkflow,
            nativePreparedTurn: nativePreparedTurn,
            codexAttemptID: codexAttemptID,
            admitted: admitted
        )
    }

    /// R12: removes exactly the admitted snapshot's attachments, tagged files, and workflow from the
    /// live composer (by identity). Anything added or changed since admission stays.
    private func consumeSubmittedComposerInput(_ admitted: AdmittedUserTurnInput, session: AgentTabSession) {
        let submittedImageIDs = Set(admitted.attachments.map(\.id))
        if !submittedImageIDs.isEmpty {
            session.pendingImageAttachments.removeAll { submittedImageIDs.contains($0.id) }
        }
        let submittedTaggedFiles = admitted.taggedFiles
        if !submittedTaggedFiles.isEmpty {
            session.pendingTaggedFileAttachments.removeAll { submittedTaggedFiles.contains($0) }
        }
        if let submittedWorkflow = admitted.workflow, session.selectedWorkflow == submittedWorkflow {
            session.selectedWorkflow = nil
            if session.tabID == currentTabID {
                selectedWorkflow = nil
            }
        }
    }

    /// Composer and MCP submission with durable recovery admission (lossless restart). When the
    /// session requires it, the input is committed `queued` (composer revision consumed, pending
    /// handoff captured) BEFORE the synchronous submit clears pending state or appends the bubble;
    /// a refused or failed commit returns `.blocked` with the composer untouched, and the committed
    /// identity (its item ID is the bubble's) and one immutable snapshot of the submitted input (R12)
    /// are carried unchanged to every route. An admitted input whose submit is refused synchronously
    /// is released per R01 (`releaseRefusedRecoveryAdmission`: withdrawn only once nothing depends on
    /// it). Sessions that do not require admission, and native control-plane commands (no user
    /// turn), submit as before.
    ///
    /// `reservedPayloadOnly` (recovery continuations, review B F5): exactly `text` is sent as a new
    /// admitted user turn. The live composer (draft text, attachments, tagged files, selected
    /// workflow, interview-first) is neither read nor consumed, no workflow wraps the text, slash
    /// commands are refused, and every non-admitted fallback is refused instead of submitting the
    /// composer's state.
    func submitUserTurnAdmittingRecoveryInput(
        text: String,
        tabID: UUID,
        origin: AgentRecoveryIntentOrigin,
        codexAttemptID: UUID? = nil,
        workflowOverride: AgentWorkflowDefinition? = nil,
        nativePreparedTurn: NativeSlashPreparedUserTurn? = nil,
        userItemID: UUID = UUID(),
        reservedPayloadOnly: Bool = false,
        actionAuthorization: AgentRecoveryActionAuthorization? = nil,
        isStillCurrent: @MainActor () -> Bool = { true }
    ) async -> UserTurnSubmissionResult {
        // Only a reserved recovery payload carries an action's authority (review A P1-01).
        guard actionAuthorization == nil || reservedPayloadOnly else {
            return .blocked(message: Self.recoveryReservedPayloadUnadmittedMessage)
        }
        let submit: (AdmittedUserTurnInput?) -> UserTurnSubmissionResult = { [weak self] admitted in
            guard let self else { return .blocked(message: Self.composeTabRemovalInProgressMessage) }
            guard let session = sessions[tabID] else {
                return .blocked(message: Self.composeTabRemovalInProgressMessage)
            }
            let submitTurn: () -> UserTurnSubmissionResult = {
                if let nativePreparedTurn {
                    return self.submitPreparedUserTurn(
                        tabID: tabID,
                        session: session,
                        trimmedText: text.trimmingCharacters(in: .whitespacesAndNewlines),
                        attachmentsToSend: [],
                        taggedFilesToSend: [],
                        activeWorkflow: nativePreparedTurn.bubbleWorkflow,
                        nativePreparedTurn: nativePreparedTurn,
                        codexAttemptID: codexAttemptID,
                        admitted: admitted
                    )
                }
                return self.submitUserTurn(
                    text: text,
                    tabID: tabID,
                    codexAttemptID: codexAttemptID,
                    admitted: admitted
                )
            }
            // MCP turns always run under their own (possibly empty) workflow; composer turns use the
            // composer's selection.
            guard origin == .mcp else { return submitTurn() }
            return withMCPWorkflowOverride(session: session, workflow: workflowOverride, operation: submitTurn)
        }
        guard let session = session(for: tabID, createIfNeeded: true) else {
            return .blocked(message: Self.composeTabRemovalInProgressMessage)
        }
        guard requiresDurableRecoveryAdmission(for: session) else {
            return reservedPayloadOnly ? .blocked(message: Self.recoveryReservedPayloadUnadmittedMessage) : submit(nil)
        }
        // Refusals the synchronous submit would return before projecting anything admit nothing.
        if let blockedMessage = newWorkBlockedMessage(for: session) {
            return .blocked(message: blockedMessage)
        }
        let trimmedText = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if reservedPayloadOnly {
            guard !trimmedText.isEmpty, nativePreparedTurn == nil, origin != .composer, origin != .mcp else {
                return .blocked(message: Self.recoveryReservedPayloadUnadmittedMessage)
            }
            guard resolvedNativeSlashCommand(in: trimmedText, session: session) == nil else {
                return .blocked(message: "A recovery continuation can't run a slash command. Nothing was sent.")
            }
        }
        let consumesComposer = origin == .composer
        // R12: the whole submitted input is captured synchronously, before any await. A native
        // prepared turn carries no composer attachments (it submits none).
        let capturesComposerInput = consumesComposer && nativePreparedTurn == nil
        let attachments = capturesComposerInput ? session.pendingImageAttachments : []
        let taggedFiles = capturesComposerInput ? session.pendingTaggedFileAttachments : []
        guard !trimmedText.isEmpty || !attachments.isEmpty || !taggedFiles.isEmpty else {
            return .blocked(message: "")
        }
        if nativePreparedTurn == nil,
           resolvedNativeSlashCommand(in: trimmedText, session: session)?.command.behavior == .controlPlane
        {
            return submit(nil)
        }
        let workflow = reservedPayloadOnly ? nil : (origin == .mcp ? workflowOverride : session.selectedWorkflow)
        let interviewFirst = consumesComposer && effectiveInterviewFirst(for: session)
        let admission = await admitRecoveryInput(
            session: session,
            userItemID: userItemID,
            origin: origin,
            text: consumesComposer ? text : trimmedText,
            attachments: attachments,
            taggedFiles: taggedFiles,
            workflow: workflow,
            interviewFirst: interviewFirst,
            consumesComposer: consumesComposer,
            actionAuthorization: actionAuthorization
        )
        switch admission {
        case .notRequired:
            return reservedPayloadOnly ? .blocked(message: Self.recoveryReservedPayloadUnadmittedMessage) : submit(nil)
        case let .blocked(message):
            return .blocked(message: message)
        case let .admitted(identity, lane, content, admittedAttachments):
            let admitted = AdmittedUserTurnInput(
                identity: identity,
                content: content,
                attachments: admittedAttachments,
                taggedFiles: taggedFiles,
                workflow: workflow,
                interviewFirst: interviewFirst,
                consumesComposer: consumesComposer
            )
            guard isStillCurrent(), sessions[tabID] === session, session.recoveryLane === lane, !lane.isRetired else {
                await releaseRefusedRecoveryAdmission(admitted, lane: lane, session: session)
                return .blocked(message: Self.staleComposerSubmitTargetMessage)
            }
            let result = submit(admitted)
            if result != .submitted {
                await releaseRefusedRecoveryAdmission(admitted, lane: lane, session: session)
            }
            return result
        }
    }

    func clearRemoteStartWindowPickerIfOwned(by tabID: UUID) {
        guard pendingRemoteStartWindowPicker?.tabID == tabID else { return }
        pendingRemoteStartWindowPicker = nil
    }

    private func presentRemoteStartWindowPickerIfPossible(
        error: Error,
        session: AgentTabSession,
        message: String,
        modelSelectionRaw: String?,
        sessionName: String?,
        workspaceName: String?,
        optimisticUserItemID: UUID
    ) -> Bool {
        guard sessions[session.tabID] === session else { return false }
        // A picker choice is an explicit user retry of the same item and intent (never automatic).
        let hostName = session.remoteHost?.hostDisplayName ?? "remote host"
        let pending = RemoteStartWindowPickerState(
            error: RemoteInputHandoffError.remoteError(of: error),
            tabID: session.tabID,
            hostName: hostName,
            message: message,
            modelSelectionRaw: modelSelectionRaw,
            sessionName: sessionName,
            workspaceName: workspaceName,
            optimisticUserItemID: optimisticUserItemID
        )
        guard let pending else { return false }
        if let existingPending = pendingRemoteStartWindowPicker {
            let isSamePair = existingPending.tabID == pending.tabID
                && existingPending.optimisticUserItemID == pending.optimisticUserItemID
            if !isSamePair {
                resolveDisplacedRemoteStartWindowPicker(
                    existingPending,
                    commandCode: "remote_start_superseded",
                    prefix: "Remote start superseded",
                    message: "Send again and choose a host window to start remotely."
                )
            }
        }
        pendingRemoteStartWindowPicker = pending
        session.pendingRemoteOptimisticUserItemIDs.insert(optimisticUserItemID)
        session.pendingRemoteOptimisticProviderTextByItemID[optimisticUserItemID] = message
        session.remoteResendInFlightItemIDs.insert(optimisticUserItemID)
        session.mutateItemsBatch { items in
            if let index = items.firstIndex(where: { $0.id == optimisticUserItemID }) {
                items[index].isUndeliveredRemoteSend = true
            }
        }
        session.remoteResendPayloadsByItemID[optimisticUserItemID] = AgentRemoteResendPayload(
            providerText: message,
            wasStart: true,
            modelSelectionRaw: modelSelectionRaw,
            sessionName: sessionName,
            workspaceName: pending.workspaceName
        )
        session.runState = .waitingForUser
        session.setRunningStatus("Choose a window on \(pending.hostName)…", source: .transport)
        requestUIRefresh(tabID: session.tabID, urgent: true)
        scheduleSave(for: session.tabID)
        return true
    }

    func failRemoteSend(
        session: AgentTabSession,
        tabID: UUID,
        optimisticUserItemID: UUID,
        prefix: String,
        error: Error,
        resendPayload: AgentRemoteResendPayload? = nil
    ) {
        if let resendPayload {
            session.remoteResendPayloadsByItemID[optimisticUserItemID] = resendPayload
        }
        // Keep the optimistic ID pending: an in-doubt delivery can still be replaced
        // by host truth during catch-up without duplicating the user turn.
        session.runState = .failed
        session.setRunningStatus(nil, source: nil)
        let remoteError = RemoteInputHandoffError.remoteError(of: error)
        let description = RemoteAgentModeCoordinator.describe(
            remoteError,
            workspaceName: workspaceManager?.activeWorkspace?.name,
            hostName: session.remoteHost?.hostDisplayName
        )
        // Delivery unknown is never presented as a plain failure: the host may have the input.
        let text = Self.isRemoteDeliveryUnknown(error)
            ? "\(prefix): \(description) The host may have received it; check before resending."
            : "\(prefix): \(description)"
        let commandCode = (remoteError as? RemoteClientError)?.commandError?.code ?? ""
        let usesSystemPresentation = Self.remoteFailureOffersLocalFallback(error)
            || ["workspace_not_open", "workspace_mismatch"]
            .contains(commandCode)
        let item = usesSystemPresentation
            ? AgentChatItem.system(text, sequenceIndex: session.nextSequenceIndex)
            : AgentChatItem.error(text, sequenceIndex: session.nextSequenceIndex)
        session.appendItem(item)
        session.mutateItemsBatch { items in
            if let index = items.firstIndex(where: { $0.id == optimisticUserItemID }) {
                items[index].isUndeliveredRemoteSend = true
            }
        }
        if Self.remoteFailureOffersLocalFallback(error) {
            remoteRunLocallyFallbackItemIDByTabID[tabID] = item.id
        } else {
            remoteRunLocallyFallbackItemIDByTabID.removeValue(forKey: tabID)
        }
        requestUIRefresh(tabID: tabID, urgent: true)
        scheduleSave(for: tabID)
    }

    struct UndeliveredRemoteSendPresentation: Equatable {
        let isUndelivered: Bool
        let resendActionLabel: String?
    }

    func undeliveredPresentation(
        for item: AgentChatItem,
        tabID: UUID?
    ) -> UndeliveredRemoteSendPresentation {
        let isUndelivered = item.kind == .user && item.isUndeliveredRemoteSend
        let resendSession = tabID.flatMap { sessions[$0] }
        let hasResendPayload = resendSession?.remoteHost != nil
            && resendSession?.remoteResendPayloadsByItemID[item.id] != nil
        let resendIsInFlight = resendSession?.remoteResendInFlightItemIDs.contains(item.id) == true
        return UndeliveredRemoteSendPresentation(
            isUndelivered: isUndelivered,
            resendActionLabel: isUndelivered && hasResendPayload && !resendIsInFlight ? "Resend" : nil
        )
    }

    func resendUndeliveredRemoteUserTurn(tabID: UUID, itemID: UUID) {
        guard let session = sessions[tabID],
              session.remoteHost != nil,
              session.items.contains(where: {
                  $0.id == itemID && $0.kind == .user && $0.isUndeliveredRemoteSend
              }),
              let payload = session.remoteResendPayloadsByItemID[itemID],
              session.remoteResendInFlightItemIDs.insert(itemID).inserted
        else { return }

        session.pendingRemoteOptimisticProviderTextByItemID[itemID] = payload.providerText
        let hasAdoptedSession = session.remoteHost?.normalizedRemoteSessionID != nil
        let startAttributionMatches = session.locallyAttributedStartItemID == nil
            || session.locallyAttributedStartItemID == itemID
        if payload.wasStart, hasAdoptedSession, startAttributionMatches {
            session.mutateItemsBatch { items in
                if let index = items.firstIndex(where: { $0.id == itemID }) {
                    items[index].isUndeliveredRemoteSend = false
                }
            }
            session.remoteResendPayloadsByItemID.removeValue(forKey: itemID)
            session.remoteResendInFlightItemIDs.remove(itemID)
            session.appendItem(.system("Remote send was already delivered."))
            // Host truth reconciles the stale terminal run state. wasStart payloads only
            // exist on root tabs, so attachPersistedSessionIfNeeded's parent-terminal guard is inert here.
            remoteCoordinator.attachPersistedSessionIfNeeded(session)
            requestUIRefresh(tabID: tabID, urgent: true)
            scheduleSave(for: tabID)
            return
        }

        let shouldStartRemote = payload.wasStart && !hasAdoptedSession
        let priorNonRunningRunState = session.runState.isActive ? AgentSessionRunState.failed : session.runState
        let resendStatusPrefix = "Sending to "
        session.runState = .running
        session.setRunningStatus(
            "\(resendStatusPrefix)\(session.remoteHost?.hostDisplayName ?? "remote host")…",
            source: .transport
        )
        session.pendingRemoteOptimisticUserItemIDs.insert(itemID)
        requestUIRefresh(tabID: tabID, urgent: true)

        Task { [weak self, weak session] in
            guard let self, let session else { return }
            do {
                // Resend is an explicit user action on the existing item (never a new intent).
                guard let dispatch = await remoteExplicitRetryDispatch(for: session, userItemID: itemID) else {
                    throw Self.remoteDispatchUnavailableError
                }
                if shouldStartRemote {
                    try await remoteCoordinator.startRemoteSession(
                        session: session,
                        message: payload.providerText,
                        modelSelectionRaw: payload.modelSelectionRaw,
                        sessionName: payload.sessionName,
                        windowID: payload.windowID,
                        workspaceID: payload.workspaceID,
                        workspaceName: payload.workspaceName,
                        dispatch: dispatch
                    )
                    session.locallyAttributedStartItemID = itemID
                } else {
                    try await remoteCoordinator.steer(session: session, text: payload.providerText, dispatch: dispatch)
                }
                session.mutateItemsBatch { items in
                    if let index = items.firstIndex(where: { $0.id == itemID }) {
                        items[index].isUndeliveredRemoteSend = false
                    }
                }
                session.remoteResendPayloadsByItemID.removeValue(forKey: itemID)
                session.remoteResendInFlightItemIDs.remove(itemID)
                requestUIRefresh(tabID: tabID, urgent: true)
                scheduleSave(for: tabID)
            } catch {
                guard sessions[tabID] === session else {
                    session.remoteResendInFlightItemIDs.remove(itemID)
                    return
                }
                let isTargetError = shouldStartRemote
                    && Self.isRemoteStartTargetError(RemoteInputHandoffError.remoteError(of: error))
                let retryPayload = isTargetError
                    ? AgentRemoteResendPayload(
                        providerText: payload.providerText,
                        wasStart: payload.wasStart,
                        modelSelectionRaw: payload.modelSelectionRaw,
                        sessionName: payload.sessionName,
                        workspaceName: payload.workspaceName,
                        windowID: nil,
                        workspaceID: nil
                    )
                    : payload
                if isTargetError {
                    session.remoteResendPayloadsByItemID[itemID] = retryPayload
                }

                let itemStillEligible = session.items.contains {
                    $0.id == itemID && $0.kind == .user && $0.isUndeliveredRemoteSend
                }
                guard itemStillEligible, session.remoteHost != nil else {
                    session.remoteResendPayloadsByItemID.removeValue(forKey: itemID)
                    session.remoteResendInFlightItemIDs.remove(itemID)
                    if !session.items.contains(where: { $0.id == itemID }) {
                        session.pendingRemoteOptimisticUserItemIDs.remove(itemID)
                        session.pendingRemoteOptimisticProviderTextByItemID.removeValue(forKey: itemID)
                    }
                    if session.runningStatusSource == .transport,
                       session.runningStatusText?.hasPrefix(resendStatusPrefix) == true
                    {
                        session.setRunningStatus(nil, source: nil)
                    }
                    if session.remoteHost == nil {
                        session.runState = priorNonRunningRunState
                    }
                    requestUIRefresh(tabID: tabID, urgent: true)
                    scheduleSave(for: tabID)
                    return
                }

                if isTargetError,
                   presentRemoteStartWindowPickerIfPossible(
                       error: error,
                       session: session,
                       message: retryPayload.providerText,
                       modelSelectionRaw: retryPayload.modelSelectionRaw,
                       sessionName: retryPayload.sessionName,
                       workspaceName: retryPayload.workspaceName,
                       optimisticUserItemID: itemID
                   )
                {
                    return
                }

                session.remoteResendInFlightItemIDs.remove(itemID)
                failRemoteSend(
                    session: session,
                    tabID: tabID,
                    optimisticUserItemID: itemID,
                    prefix: "Remote send failed",
                    error: error,
                    resendPayload: retryPayload
                )
            }
        }
    }

    private static func isRemoteStartTargetError(_ error: Error) -> Bool {
        RemoteStartWindowPickerState.isTargetError(RemoteInputHandoffError.remoteError(of: error))
    }

    private static func remoteFailureOffersLocalFallback(_ error: Error) -> Bool {
        guard let remoteError = RemoteInputHandoffError.remoteError(of: error) as? RemoteClientError else { return false }
        switch remoteError {
        case .hostNotFound, .hostRevoked, .missingDeviceKey, .timeout, .transport, .connectionClosed:
            return true
        case .security, .invalidTicket, .protocolViolation, .rateLimited, .revoked,
             .bindingRequired, .ambiguousStartTarget, .inDoubt, .insufficientScope,
             .sessionExpired, .interactionAlreadyResolved, .authentication, .command:
            return false
        }
    }

    func recoverRemoteStartByOpeningWorkspace() {
        guard let pending = pendingRemoteStartWindowPicker,
              let workspaceName = pending.openableWorkspaceName
        else { return }
        guard let session = sessions[pending.tabID],
              let hostID = session.remoteHost?.hostID
        else {
            cancelRemoteStartWindowPicker()
            return
        }

        pendingRemoteStartWindowPicker = nil
        let openingStatus = "Opening '\(workspaceName)' on \(pending.hostName)…"
        session.setRunningStatus(openingStatus, source: .transport)
        requestUIRefresh(tabID: pending.tabID, urgent: true)

        Task { [weak self, weak session] in
            guard let session else { return }
            guard let self else {
                session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                return
            }

            let nameOnlyPayload = AgentRemoteResendPayload(
                providerText: pending.message,
                wasStart: true,
                modelSelectionRaw: pending.modelSelectionRaw,
                sessionName: pending.sessionName,
                workspaceName: workspaceName
            )
            do {
                try await remoteCoordinator.openWorkspaceForStartRecovery(
                    hostID: hostID,
                    workspaceName: workspaceName
                )
            } catch {
                guard sessions[pending.tabID] === session else {
                    session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                    return
                }
                session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                failRemoteSend(
                    session: session,
                    tabID: pending.tabID,
                    optimisticUserItemID: pending.optimisticUserItemID,
                    prefix: "Remote start failed",
                    error: error,
                    resendPayload: nameOnlyPayload
                )
                return
            }

            if let activeWorkspace = workspaceManager?.activeWorkspace,
               activeWorkspace.name
               .trimmingCharacters(in: .whitespacesAndNewlines)
               .caseInsensitiveCompare(workspaceName) == .orderedSame
            {
                remoteCoordinator.resetWorkspaceOpenEpisode(
                    hostID: hostID,
                    clientWorkspaceID: activeWorkspace.id
                )
            }

            guard sessions[pending.tabID] === session else {
                session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                return
            }

            if session.remoteHost?.normalizedRemoteSessionID != nil {
                if session.runningStatusSource == .transport,
                   session.runningStatusText == openingStatus
                {
                    session.setRunningStatus(nil, source: nil)
                }
                session.mutateItemsBatch { items in
                    if let index = items.firstIndex(where: { $0.id == pending.optimisticUserItemID }) {
                        items[index].isUndeliveredRemoteSend = false
                    }
                }
                session.remoteResendPayloadsByItemID.removeValue(forKey: pending.optimisticUserItemID)
                session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                session.appendItem(.system("Remote send was already delivered."))
                remoteCoordinator.attachPersistedSessionIfNeeded(session)
                requestUIRefresh(tabID: pending.tabID, urgent: true)
                scheduleSave(for: pending.tabID)
                return
            }

            do {
                // Workspace-open retry: an explicit user action on the existing item.
                guard let dispatch = await remoteExplicitRetryDispatch(
                    for: session,
                    userItemID: pending.optimisticUserItemID
                ) else {
                    throw Self.remoteDispatchUnavailableError
                }
                try await remoteCoordinator.startRemoteSession(
                    session: session,
                    message: pending.message,
                    modelSelectionRaw: pending.modelSelectionRaw,
                    sessionName: pending.sessionName,
                    windowID: nil,
                    workspaceID: nil,
                    workspaceName: workspaceName,
                    dispatch: dispatch
                )
                session.locallyAttributedStartItemID = pending.optimisticUserItemID
                session.mutateItemsBatch { items in
                    if let index = items.firstIndex(where: { $0.id == pending.optimisticUserItemID }) {
                        items[index].isUndeliveredRemoteSend = false
                    }
                }
                session.remoteResendPayloadsByItemID.removeValue(forKey: pending.optimisticUserItemID)
                session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                requestUIRefresh(tabID: pending.tabID, urgent: true)
                scheduleSave(for: pending.tabID)
            } catch {
                guard sessions[pending.tabID] === session else {
                    session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                    return
                }
                // Selector-exclusivity backstop: this retry must remain name-only even if picker presentation fails.
                if session.remoteResendPayloadsByItemID[pending.optimisticUserItemID] != nil {
                    session.remoteResendPayloadsByItemID[pending.optimisticUserItemID] = nameOnlyPayload
                }
                if presentRemoteStartWindowPickerIfPossible(
                    error: error,
                    session: session,
                    message: pending.message,
                    modelSelectionRaw: pending.modelSelectionRaw,
                    sessionName: pending.sessionName,
                    workspaceName: workspaceName,
                    optimisticUserItemID: pending.optimisticUserItemID
                ) {
                    return
                }
                session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                failRemoteSend(
                    session: session,
                    tabID: pending.tabID,
                    optimisticUserItemID: pending.optimisticUserItemID,
                    prefix: "Remote start failed",
                    error: error,
                    resendPayload: nameOnlyPayload
                )
            }
        }
    }

    func selectRemoteStartWindow(_ option: RemoteStartWindowOption) {
        guard let pending = pendingRemoteStartWindowPicker else { return }
        pendingRemoteStartWindowPicker = nil
        guard let session = sessions[pending.tabID] else { return }
        session.pendingRemoteOptimisticUserItemIDs.insert(pending.optimisticUserItemID)
        session.pendingRemoteOptimisticProviderTextByItemID[pending.optimisticUserItemID] = pending.message
        requestUIRefresh(tabID: pending.tabID, urgent: true)
        Task { [weak self, weak session] in
            guard let self, let session else { return }
            do {
                // Picker choice: an explicit user action on the existing item.
                guard let dispatch = await remoteExplicitRetryDispatch(
                    for: session,
                    userItemID: pending.optimisticUserItemID
                ) else {
                    throw Self.remoteDispatchUnavailableError
                }
                try await remoteCoordinator.startRemoteSession(
                    session: session,
                    message: pending.message,
                    modelSelectionRaw: pending.modelSelectionRaw,
                    sessionName: pending.sessionName,
                    windowID: option.windowID,
                    // Guard only against the host-reported workspace of the chosen
                    // window — never a client-local workspace UUID.
                    workspaceID: option.workspaceID,
                    workspaceName: nil,
                    dispatch: dispatch
                )
                session.locallyAttributedStartItemID = pending.optimisticUserItemID
                session.mutateItemsBatch { items in
                    if let index = items.firstIndex(where: { $0.id == pending.optimisticUserItemID }) {
                        items[index].isUndeliveredRemoteSend = false
                    }
                }
                session.remoteResendPayloadsByItemID.removeValue(forKey: pending.optimisticUserItemID)
                session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                requestUIRefresh(tabID: pending.tabID, urgent: true)
                scheduleSave(for: pending.tabID)
            } catch {
                let isTargetError = Self.isRemoteStartTargetError(error)
                let existingPayload = session.remoteResendPayloadsByItemID[pending.optimisticUserItemID]
                let failedPayload = AgentRemoteResendPayload(
                    providerText: pending.message,
                    wasStart: true,
                    modelSelectionRaw: pending.modelSelectionRaw,
                    sessionName: pending.sessionName,
                    workspaceName: isTargetError ? (pending.workspaceName ?? existingPayload?.workspaceName) : nil,
                    windowID: isTargetError ? nil : option.windowID,
                    workspaceID: isTargetError ? nil : option.workspaceID
                )
                if session.remoteResendPayloadsByItemID[pending.optimisticUserItemID] != nil {
                    session.remoteResendPayloadsByItemID[pending.optimisticUserItemID] = failedPayload
                }
                if presentRemoteStartWindowPickerIfPossible(
                    error: error,
                    session: session,
                    message: pending.message,
                    modelSelectionRaw: pending.modelSelectionRaw,
                    sessionName: pending.sessionName,
                    workspaceName: pending.workspaceName,
                    optimisticUserItemID: pending.optimisticUserItemID
                ) {
                    return
                }
                session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
                failRemoteSend(
                    session: session,
                    tabID: pending.tabID,
                    optimisticUserItemID: pending.optimisticUserItemID,
                    prefix: "Remote start failed",
                    error: error,
                    resendPayload: failedPayload
                )
            }
        }
    }

    private func resolveDisplacedRemoteStartWindowPicker(
        _ pending: RemoteStartWindowPickerState,
        commandCode: String,
        prefix: String,
        message: String
    ) {
        guard let session = sessions[pending.tabID] else { return }
        let existingPayload = session.remoteResendPayloadsByItemID[pending.optimisticUserItemID]
        session.remoteResendInFlightItemIDs.remove(pending.optimisticUserItemID)
        failRemoteSend(
            session: session,
            tabID: pending.tabID,
            optimisticUserItemID: pending.optimisticUserItemID,
            prefix: prefix,
            error: RemoteClientError.fromCommandError(code: commandCode, message: message),
            resendPayload: AgentRemoteResendPayload(
                providerText: pending.message,
                wasStart: true,
                modelSelectionRaw: pending.modelSelectionRaw,
                sessionName: pending.sessionName,
                workspaceName: pending.workspaceName ?? existingPayload?.workspaceName
            )
        )
    }

    func cancelRemoteStartWindowPicker() {
        guard let pending = pendingRemoteStartWindowPicker else { return }
        pendingRemoteStartWindowPicker = nil
        resolveDisplacedRemoteStartWindowPicker(
            pending,
            commandCode: "remote_start_cancelled",
            prefix: "Remote start cancelled",
            message: "Send again and choose a host window to start remotely."
        )
    }

    private func submitUserTurnAfterHydration(
        tabID: UUID,
        trimmedText: String,
        attachmentsToSend: [AgentImageAttachment],
        taggedFilesToSend: [AgentTaggedFileAttachment],
        activeWorkflow: AgentWorkflowDefinition?,
        nativePreparedTurn: NativeSlashPreparedUserTurn?,
        codexAttemptID: UUID?,
        admitted: AdmittedUserTurnInput?
    ) async {
        guard let session = sessions[tabID] else {
            // R01: never withdrawn here; the admitted intent stays held for explicit recovery.
            recoveryCoordinator?.noteRecoveryActionSubmissionEnded(admitted?.identity.actionAuthorization)
            return
        }
        await prepareSessionForRunStart(tabID: tabID, session: session)
        guard let hydratedSession = sessions[tabID] else {
            recoveryCoordinator?.noteRecoveryActionSubmissionEnded(admitted?.identity.actionAuthorization)
            return
        }
        let result = submitPreparedUserTurn(
            tabID: tabID,
            session: hydratedSession,
            trimmedText: trimmedText,
            attachmentsToSend: attachmentsToSend,
            taggedFilesToSend: taggedFilesToSend,
            activeWorkflow: activeWorkflow,
            nativePreparedTurn: nativePreparedTurn,
            codexAttemptID: codexAttemptID,
            admitted: admitted
        )
        // The caller already reported `.submitted`; a refusal after hydration releases the admitted
        // intent under R01 (held unless its exact draft is durably back in the composer).
        if result != .submitted, let admitted {
            // A recovery action's submission settles here: nothing was or can be handed off.
            recoveryCoordinator?.noteRecoveryActionSubmissionEnded(admitted.identity.actionAuthorization)
            // Send saved (review A P1-06): the saved intent was the user's message before this choice;
            // a refused re-dispatch keeps it queued (never withdrawn), exactly as before the choice.
            if !admitted.resendsAuthorizedSavedIntent, let lane = hydratedSession.recoveryLane {
                await releaseRefusedRecoveryAdmission(admitted, lane: lane, session: hydratedSession)
            }
        }
    }

    private static func shouldWakeParentAgentRunWaitersForActiveSubmit(
        selectedAgent: AgentProviderKind,
        codexCompactionInFlight: Bool
    ) -> Bool {
        selectedAgent != .codexExec || codexCompactionInFlight
    }

    #if DEBUG
        static func test_shouldWakeParentAgentRunWaitersForActiveSubmit(
            selectedAgent: AgentProviderKind,
            codexCompactionInFlight: Bool
        ) -> Bool {
            shouldWakeParentAgentRunWaitersForActiveSubmit(
                selectedAgent: selectedAgent,
                codexCompactionInFlight: codexCompactionInFlight
            )
        }
    #endif

    private func removeUnconfirmedMCPOptimisticCodexUserItem(
        session: AgentTabSession,
        tabID: UUID,
        itemID: UUID?,
        reason: String
    ) {
        guard let itemID,
              let index = session.items.firstIndex(where: { $0.id == itemID })
        else { return }
        guard session.removeItem(at: index) != nil else { return }
        Self.steeringDebugLog(
            "[AgentRunSteeringWake] removed unconfirmed MCP Codex optimistic item tab=\(tabID) itemID=\(itemID) reason=\(reason)"
        )
        requestUIRefresh(tabID: tabID, urgent: true)
        scheduleSave(for: tabID)
    }

    @discardableResult
    private func submitPreparedUserTurn(
        tabID: UUID,
        session: AgentTabSession,
        trimmedText: String,
        attachmentsToSend: [AgentImageAttachment],
        taggedFilesToSend: [AgentTaggedFileAttachment],
        activeWorkflow: AgentWorkflowDefinition?,
        nativePreparedTurn: NativeSlashPreparedUserTurn?,
        codexAttemptID: UUID?,
        admitted: AdmittedUserTurnInput?
    ) -> UserTurnSubmissionResult {
        Self.logCodexDebug("[AgentModeVM] submitUserTurn: tabID=\(tabID), selectedAgent=\(session.selectedAgent), attachments=\(attachmentsToSend.count), taggedFiles=\(taggedFilesToSend.count), workflow=\(activeWorkflow?.displayName ?? "none")")
        let admittedIdentity = admitted?.identity
        // F1: every route below needs a durable identity unless admission is inactive. Refuse before
        // the bubble, attachment reservation, interview-first consumption, or any MCP signal.
        if admittedIdentity == nil, session.recoveryAdmissionMode != .inactive {
            return .blocked(message: Self.durableQueueAdmissionRequiredMessage)
        }
        // Review A P1-01: an explicit recovery action's own payload only starts a local run, whose
        // dispatch evidence settles the action's hold; a live run or remote host never queues it.
        if admittedIdentity?.actionAuthorization != nil, session.runState.isActive || session.remoteHost != nil {
            return .blocked(message: Self.recoveryActionSessionBusyMessage)
        }
        // Review A P1-06 / O11: Send saved reuses its intent's one bubble, which its preparation
        // placed (or found) as the clean request of the final turn and committed before the queue
        // receipt. Without that exact, still-current preparation nothing is appended or sent: an
        // absent bubble was reconstructed and saved by the preparation, never here. Decided
        // synchronously with the reuse below (no suspension between check and use).
        var reusedUserItem: AgentChatItem?
        if let admitted, admitted.resendsAuthorizedSavedIntent {
            switch recoverySavedPreparedBubble(
                admitted,
                session: session,
                trimmedText: trimmedText,
                attachments: attachmentsToSend,
                taggedFiles: taggedFilesToSend,
                workflow: activeWorkflow
            ) {
            case let .success(item):
                reusedUserItem = item
            case let .failure(refusal):
                return .blocked(message: refusal.message)
            }
        }

        let prepared = appendPreparedUserTurn(
            tabID: tabID,
            session: session,
            trimmedText: trimmedText,
            attachmentsToSend: attachmentsToSend,
            taggedFilesToSend: taggedFilesToSend,
            activeWorkflow: activeWorkflow,
            nativePreparedTurn: nativePreparedTurn,
            inputSource: .composer,
            preassignedUserItemID: admittedIdentity?.userItemID,
            admittedInterviewFirst: admitted.map(\.interviewFirst),
            consumesComposerInterview: admitted?.consumesComposer ?? true,
            reusedUserItem: reusedUserItem
        )
        let userItem = prepared.userItem
        let effectiveUserText = prepared.effectiveUserText
        let wrappedText = prepared.wrappedText
        let codexCompactionInFlight = prepared.codexCompactionInFlight
        let stagedCodexComputerUseActivationID = prepared.stagedCodexComputerUseActivationID

        if session.runState == .running,
           !session.isMCPInstructionDispatchInProgress
        {
            Self.steeringDebugLog("[AgentRunSteeringWake] manual active submit accepted tab=\(tabID) runState=\(session.runState.rawValue) agent=\(session.selectedAgent.displayName) runID=\(String(describing: session.runID)) hasMCPContext=\(session.mcpControlContext != nil)")
            if let runID = session.runID,
               Self.shouldWakeParentAgentRunWaitersForActiveSubmit(
                   selectedAgent: session.selectedAgent,
                   codexCompactionInFlight: codexCompactionInFlight
               )
            {
                Task { @MainActor [weak self] in
                    guard let self, let mcpServer else { return }
                    await mcpServer.wakeAgentRunWaitersOwnedByActiveRun(
                        runID: runID,
                        source: "manual-active-submit-parent-run",
                        publicationForSessionID: { [weak self] childSessionID in
                            self?.mcpWaitPublication(sessionID: childSessionID)
                        }
                    )
                }
            }
            if session.mcpControlContext != nil {
                wakeCurrentMCPWaitersForSteeringRequestFireAndForget(for: session, source: "manual-active-submit-controlled-session")
            }
        }

        if shouldSignalMCPInstructionDeliveredAfterOptimisticSubmit(for: session) {
            signalMCPInstructionDeliveredFireAndForget(for: session)
        }

        if session.remoteHost != nil {
            // The input's admission identity: its committed queue receipt, or untracked while
            // admission is inactive (fail closed when mandatory without one).
            guard let remoteDispatch = remoteSendDispatch(
                for: session,
                userItemID: userItem.id,
                receipt: admittedIdentity?.queueReceipt
            ) else {
                return .blocked(message: Self.durableQueueAdmissionRequiredMessage)
            }
            remoteRunLocallyFallbackItemIDByTabID.removeValue(forKey: tabID)
            session.pendingRemoteOptimisticUserItemIDs.insert(userItem.id)
            session.pendingRemoteOptimisticProviderTextByItemID[userItem.id] = wrappedText
            let shouldStartRemote = Self.shouldStartRemoteTurn(
                runState: session.runState,
                remoteSessionID: session.remoteHost?.remoteSessionID
            )
            let modelSelectionRaw = RemoteHostAgentCatalog.modelIDForStart(session.selectedModelRaw)
            let selectedModelRaw = session.selectedModelRaw.trimmingCharacters(in: .whitespacesAndNewlines)
            if modelSelectionRaw == nil,
               !selectedModelRaw.isEmpty,
               selectedModelRaw != RemoteHostAgentCatalog.hostDefaultModelID
            {
                session.selectedModelRaw = RemoteHostAgentCatalog.hostDefaultModelID
                if tabID == currentTabID {
                    setSelectedModelRawDuringStateRestore(RemoteHostAgentCatalog.hostDefaultModelID)
                }
                scheduleSave(for: tabID)
                syncComposerUIState(tabID: tabID)
                syncStatusPillsUIState()
            }
            var didDeriveRemoteSessionName = false
            if shouldStartRemote {
                let currentSessionName = resolvedSessionDisplayName(for: tabID)
                let preparedSessionName = AgentSessionTitleNaming.sessionNameForRemoteStart(
                    currentTitle: currentSessionName,
                    userText: effectiveUserText
                )
                if AgentSessionTitleNaming.isDefaultSessionTitle(currentSessionName),
                   preparedSessionName != AgentSession.validatedName(currentSessionName)
                {
                    renameSession(tabID: tabID, to: preparedSessionName)
                    didDeriveRemoteSessionName = true
                }
            }
            let sessionName = resolvedSessionDisplayName(for: tabID)
            let workspaceName = workspaceManager?.activeWorkspace?.name
            Task { [weak self, weak session] in
                guard let self, let session else { return }
                do {
                    if shouldStartRemote {
                        // First send cannot use the client-local workspace UUID as a
                        // host selector, but the workspace name can disambiguate a
                        // single matching host window. Picker retries still use
                        // host-reported window/workspace identifiers.
                        try await remoteCoordinator.startRemoteSession(
                            session: session,
                            message: wrappedText,
                            modelSelectionRaw: modelSelectionRaw,
                            sessionName: sessionName,
                            windowID: nil,
                            workspaceID: nil,
                            workspaceName: workspaceName,
                            allowHostSessionNameAdoptionFromStartName: didDeriveRemoteSessionName,
                            dispatch: remoteDispatch
                        )
                        session.locallyAttributedStartItemID = userItem.id
                    } else {
                        try await remoteCoordinator.steer(session: session, text: wrappedText, dispatch: remoteDispatch)
                    }
                } catch {
                    if shouldStartRemote,
                       presentRemoteStartWindowPickerIfPossible(
                           error: error,
                           session: session,
                           message: wrappedText,
                           modelSelectionRaw: modelSelectionRaw,
                           sessionName: sessionName,
                           workspaceName: workspaceName,
                           optimisticUserItemID: userItem.id
                       )
                    {
                        return
                    }
                    failRemoteSend(
                        session: session,
                        tabID: tabID,
                        optimisticUserItemID: userItem.id,
                        prefix: "Remote send failed",
                        error: error,
                        resendPayload: AgentRemoteResendPayload(
                            providerText: wrappedText,
                            wasStart: shouldStartRemote,
                            modelSelectionRaw: modelSelectionRaw,
                            sessionName: sessionName,
                            workspaceName: workspaceName
                        )
                    )
                }
            }
            return UserTurnSubmissionResult.submitted
        }

        if session.selectedAgent == .codexExec {
            // The admitted durable identity (queue ID == intent ID), or untracked while admission is
            // inactive; fail closed when mandatory without one.
            guard let identity = admittedIdentity
                ?? AgentQueuedInputIdentity.untracked(userItemID: userItem.id, in: session)
            else {
                return .blocked(message: Self.durableQueueAdmissionRequiredMessage)
            }
            let dispatchTicket = session.codexDispatchSerialGate.issueTicket()
            let fallbackContext = AgentTabSession.CodexFallbackSubmissionContext(
                // A durable identity is queued under its recovery intent ID (the receipt's intent).
                queueID: identity.intentID ?? UUID(),
                providerText: wrappedText,
                images: attachmentsToSend,
                taggedFileAttachments: taggedFilesToSend,
                draftText: trimmedText,
                identity: identity,
                origin: codexAttemptID.map(AgentTabSession.CodexFallbackOrigin.mcp) ?? .manual,
                dispatchTicket: dispatchTicket
            )
            Task {
                var handedOffToSerialDispatch = false
                defer {
                    if !handedOffToSerialDispatch {
                        session.codexDispatchSerialGate.cancel(dispatchTicket)
                    }
                }
                if let codexAttemptID {
                    guard await session.codexSteerAckTracker.awaitDispatchAuthorization(
                        attemptID: codexAttemptID
                    ) else {
                        self.removeUnconfirmedMCPOptimisticCodexUserItem(
                            session: session,
                            tabID: tabID,
                            itemID: prepared.removableUserItemID,
                            reason: "dispatch authorization did not complete"
                        )
                        return
                    }
                }
                handedOffToSerialDispatch = true
                let sendOutcome = await self.startAgentRun(
                    tabID: tabID,
                    initialMessage: wrappedText,
                    attachments: attachmentsToSend,
                    taggedFileAttachments: taggedFilesToSend,
                    // Codex carries its identity in the fallback context.
                    inputConstituents: nil,
                    codexFallbackContext: fallbackContext
                )
                self.noteRecoveryActionStartReturned(identity, outcome: sendOutcome, isCodex: true)
                if sendOutcome?.didSend != true {
                    self.clearPendingCodexComputerUseActivationIfMatched(
                        session: session,
                        activationID: stagedCodexComputerUseActivationID
                    )
                    // Delivery unknown: the provider may have the input; the bubble stays (never
                    // deleted, restored as a draft, or retried).
                    if codexAttemptID != nil, !Self.isDeliveryUnknown(sendOutcome) {
                        self.removeUnconfirmedMCPOptimisticCodexUserItem(
                            session: session,
                            tabID: tabID,
                            itemID: prepared.removableUserItemID,
                            reason: "send outcome was not accepted or durably queued"
                        )
                    }
                }
                guard let codexAttemptID else { return }
                let terminalState: CodexSteerAckTracker.TerminalState = switch sendOutcome {
                case .sent:
                    .steerAccepted
                case let .queuedFallback(receipt, _):
                    .durablyQueued(receipt: receipt)
                case let .deliveryUnknown(message):
                    .deliveryUnknown(message: message)
                case let .stale(reason):
                    .stale(reason: reason)
                case .cancelled:
                    .cancelled
                case let .failed(message):
                    .failed(message: message)
                case nil:
                    .stale(reason: "Codex steer could not be delivered because the runtime changed before send started.")
                }
                session.codexSteerAckTracker.resolve(
                    attemptID: codexAttemptID,
                    state: terminalState
                )
            }
            return UserTurnSubmissionResult.submitted
        }

        // One immutable identity for this input across every route below: the intent committed
        // before the optimistic clear (`submitUserTurnAdmittingRecoveryInput`), or untracked while
        // admission is inactive; none once admission is mandatory (fail closed).
        guard let inputIdentity = admittedIdentity
            ?? AgentQueuedInputIdentity.untracked(userItemID: userItem.id, in: session)
        else {
            return .blocked(message: Self.durableQueueAdmissionRequiredMessage)
        }
        let userInputTokenEstimate = enqueueUserTurnTokenEstimate(
            wrappedText: wrappedText,
            attachments: attachmentsToSend,
            session: session
        )

        // If agent is waiting for instruction, resume it.
        // Claude image attachments must go through a resumed turn (not wait-tool continuation),
        // otherwise attachment references are not forwarded reliably.
        if session.runState == .waitingForUser {
            if session.selectedAgent.usesClaudeNativeRuntime, !attachmentsToSend.isEmpty {
                Task { [weak self] in
                    guard let self else { return }
                    await cancelAgentRun(tabID: tabID, cause: .ordinary)
                    await startAgentRun(
                        tabID: tabID,
                        initialMessage: wrappedText,
                        attachments: attachmentsToSend,
                        taggedFileAttachments: taggedFilesToSend,
                        inputConstituents: [inputIdentity],
                        holdsPrefixBlockedInput: true
                    )
                }
                return UserTurnSubmissionResult.submitted
            }
            if session.instructionContinuation != nil {
                // R05-R1b: an older queued head owns the live wait, even while its own delivery is
                // suspended or blocked; this input queues behind it instead of claiming the wait.
                if !session.pendingInstructions.isEmpty {
                    queueBehindOlderInstructionHead(
                        session: session,
                        wrappedText: wrappedText,
                        identity: inputIdentity,
                        hasAttachments: !attachmentsToSend.isEmpty || !taggedFilesToSend.isEmpty
                    )
                    return UserTurnSubmissionResult.submitted
                }
                let textForContinuation = wrappedText
                let continuationAttachments = attachmentsToSend
                let continuationTaggedFiles = taggedFilesToSend
                _ = dequeuePendingNonCodexUserTokens(for: session) ?? userInputTokenEstimate
                Task { @MainActor [weak self, weak session] in
                    guard let self, let session else { return }
                    let augmented = await augmentUserMessageForProviderSend(
                        textForContinuation,
                        attachments: continuationAttachments,
                        taggedFileAttachments: continuationTaggedFiles,
                        agent: session.selectedAgent,
                        session: session,
                        carriers: [inputIdentity]
                    )
                    if let blockedReason = augmented.blockedReason {
                        // Its handoff prefix could not be saved with it: never resumed without it.
                        holdBlockedDurableInput([inputIdentity], session: session, reason: blockedReason)
                        return
                    }
                    let augmentedText = augmented.text
                    // Returning the text to the waiting tool is this input's stage-delivery boundary;
                    // every exit before it releases the exact pending-handoff stage it created.
                    var stageDelivered = false
                    defer {
                        recordPendingHandoffStageOutcome(
                            for: session,
                            stage: augmented.pendingHandoffStage,
                            disposition: stageDelivered ? .sent : .notSent
                        )
                    }
                    let hasAttachments = !continuationAttachments.isEmpty || !continuationTaggedFiles.isEmpty
                    guard session.instructionContinuation != nil else {
                        // B R1-1: the wait ended during preparation; the saved input is shown as held.
                        holdBlockedDurableInput([inputIdentity], session: session, reason: Self.instructionWaitEndedHoldReason)
                        return
                    }
                    // R05-R1b: a head queued during preparation keeps its priority.
                    guard session.pendingInstructions.isEmpty else {
                        queueBehindOlderInstructionHead(
                            session: session,
                            wrappedText: textForContinuation,
                            identity: inputIdentity,
                            hasAttachments: hasAttachments
                        )
                        return
                    }
                    // Before-handoff dispatch commit (durable input), then revalidate the exact
                    // wait (same wait ID and run attempt), lane, and empty queue with no suspension
                    // before the claim: a stale continuation never receives the input.
                    let expectedWaitID = session.instructionWaitID
                    let expectedRunAttemptID = session.activeRunAttemptID
                    let dispatchEvidence: AgentRecoveryDispatchEvidence
                    switch await AgentRecoveryDispatchEvidence.beginUnderActiveRun(
                        session: session,
                        constituents: [inputIdentity]
                    ) {
                    case let .success(evidence):
                        dispatchEvidence = evidence
                    case let .failure(failure):
                        print("[AgentModeVM][Recovery] waiting continuation not resumed: \(failure)")
                        // Nothing was handed off (for example the run has no compatible ownership):
                        // the saved input is shown as held, never sent unlinked.
                        holdBlockedDurableInput([inputIdentity], session: session, reason: failure.dispatchFailureText)
                        return
                    }
                    guard claimLiveInstructionWait(
                        session: session,
                        expectedWaitID: expectedWaitID,
                        expectedRunAttemptID: expectedRunAttemptID,
                        evidence: dispatchEvidence,
                        text: augmentedText,
                        beforeClaim: { session.pendingInstructions.isEmpty }
                    ) else {
                        // Nothing was handed off (settled back to queued). Behind a head queued
                        // meanwhile it keeps FIFO order; otherwise the wait changed and the saved
                        // input is shown as held (B R1-1), never resent automatically.
                        if session.runState.isActive, !session.pendingInstructions.isEmpty {
                            queueBehindOlderInstructionHead(
                                session: session,
                                wrappedText: textForContinuation,
                                identity: inputIdentity,
                                hasAttachments: hasAttachments
                            )
                        } else {
                            holdBlockedDurableInput([inputIdentity], session: session, reason: Self.instructionWaitEndedHoldReason)
                        }
                        return
                    }
                    stageDelivered = true
                }
                return UserTurnSubmissionResult.submitted
            }
        }

        // If agent is not running, start it
        if !session.runState.isActive {
            Task {
                let outcome = await startAgentRun(
                    tabID: tabID,
                    initialMessage: wrappedText,
                    attachments: attachmentsToSend,
                    taggedFileAttachments: taggedFilesToSend,
                    inputConstituents: [inputIdentity],
                    holdsPrefixBlockedInput: true
                )
                noteRecoveryActionStartReturned(inputIdentity, outcome: outcome, isCodex: false)
            }
        } else {
            // Queued input carries its admission identity.
            let identity = inputIdentity
            if let route = activeProviderSteeringRoute(for: session, attachments: attachmentsToSend) {
                submitActiveProviderSteering(
                    route,
                    session: session,
                    wrappedText: wrappedText,
                    attachmentsToSend: attachmentsToSend,
                    taggedFilesToSend: taggedFilesToSend,
                    trimmedText: trimmedText,
                    userItem: userItem,
                    identity: identity,
                    userInputTokenEstimate: userInputTokenEstimate
                )
            } else {
                // Shared follow-up queue for providers that consume queued instructions at the next turn boundary.
                session.pendingInstructions.append(AgentPendingInstruction(text: wrappedText, identity: identity))
            }
        }
        return UserTurnSubmissionResult.submitted
    }

    /// Shared append seam for composer, MCP, and scheduled turns (plan §3.3 `UserTurnInputSource`).
    /// Everything a persisted user turn needs before provider routing lives here: bubble text,
    /// Codex computer-use staging, interview-first wrapping (composer flag or frozen record flag),
    /// workflow wrapping, tagged-file auto-selection, delta flush, anchor bookkeeping, append, and
    /// the debounced save. `.scheduled` supplies the attempt's deterministic item id and never
    /// reads or clears composer pending state. `admittedInterviewFirst` is the admitted snapshot's
    /// interview choice (R12; `nil` only for legacy untracked composer input, which reads the live
    /// choice). Only a composer submission (`consumesComposerInterview`) consumes the live one-shot
    /// interview choice; an admitted non-composer input (MCP, Send saved) leaves it alone.
    ///
    /// `reusedUserItem` (review A P1-06, Send saved only): the authorized, already shown
    /// deterministic bubble of the saved intent. It is left exactly as shown (no append, duplicate,
    /// sequence-counter, or timestamp change); the new run attaches to that same turn, and the
    /// result reports `.reused` so failure cleanup never deletes it.
    func appendPreparedUserTurn(
        tabID: UUID,
        session: AgentTabSession,
        trimmedText: String,
        attachmentsToSend: [AgentImageAttachment],
        taggedFilesToSend: [AgentTaggedFileAttachment],
        activeWorkflow: AgentWorkflowDefinition?,
        nativePreparedTurn: NativeSlashPreparedUserTurn?,
        inputSource: UserTurnInputSource,
        preassignedUserItemID: UUID?,
        admittedInterviewFirst: Bool?,
        consumesComposerInterview: Bool = true,
        reusedUserItem: AgentChatItem? = nil
    ) -> PreparedUserTurnAppend {
        let bubbleText = Self.userBubbleText(
            trimmedText: trimmedText,
            attachments: attachmentsToSend,
            taggedFiles: taggedFilesToSend,
            workflow: activeWorkflow
        )
        if case .composer = inputSource, reusedUserItem == nil,
           nativePreparedTurn?.shouldEnableCodexComputerUse == true
        {
            session.pendingCodexComputerUseActivation = AgentCodexComputerUseActivation(
                id: UUID(),
                createdAt: Date()
            )
        }
        let stagedCodexComputerUseActivationID = session.pendingCodexComputerUseActivation?.id

        // Prepend interview instruction to the user message if enabled (first message only)
        var effectiveUserText = nativePreparedTurn?.providerText ?? trimmedText
        let itemID: UUID
        switch inputSource {
        case .composer:
            // A durably admitted input is shown as the item its intent was committed for.
            itemID = reusedUserItem?.id ?? preassignedUserItemID ?? UUID()
            let interviewFirst = admittedInterviewFirst ?? effectiveInterviewFirst(for: session)
            if interviewFirst, Self.sessionQualifiesForInterviewFirst(session) {
                effectiveUserText = Self.interviewFirstWrappedUserText(effectiveUserText)
                // The submitted choice is consumed (one-shot) by a composer submission only; an
                // admitted non-composer input carries its own choice and leaves the live one alone.
                if consumesComposerInterview {
                    setInterviewFirst(false, for: session)
                }
            }
        case let .scheduled(record, attempt):
            itemID = attempt.itemID
            if record.interviewFirst, Self.sessionQualifiesForInterviewFirst(session) {
                effectiveUserText = Self.interviewFirstWrappedUserText(effectiveUserText)
            }
        }

        // Wrap text with workflow template if selected
        let includeBuiltInCleanupGuidance = GlobalSettingsStore.shared.showBuiltInWorkflowCleanupGuidance()
        let wrappedText = activeWorkflow?.wrapUserText(
            effectiveUserText,
            includeBuiltInSessionCleanupGuidance: includeBuiltInCleanupGuidance
        ) ?? effectiveUserText
        let codexCompactionInFlight = session.selectedAgent == .codexExec
            && codexCoordinator.isCodexCompactionInFlight(session: session)

        autoSelectTaggedFilesForTurn(
            tabID: tabID,
            text: trimmedText,
            taggedFileAttachments: taggedFilesToSend
        )

        if session.runState.isActive,
           session.runState != .waitingForUser
        {
            flushPendingAssistantDelta(session)
        }

        if let reusedUserItem {
            // The shown bubble stays exactly as it is; this run's runtime footer starts now.
            recordAgentTurnUserAnchor(for: session, userItem: reusedUserItem, startedAt: Date())
            updateBindingsFromSession(session)
            return PreparedUserTurnAppend(
                userItem: reusedUserItem,
                effectiveUserText: effectiveUserText,
                wrappedText: wrappedText,
                codexCompactionInFlight: codexCompactionInFlight,
                stagedCodexComputerUseActivationID: stagedCodexComputerUseActivationID,
                disposition: .reused
            )
        }
        let userItem = AgentChatItem.user(
            bubbleText,
            id: itemID,
            attachments: attachmentsToSend,
            taggedFileAttachments: taggedFilesToSend,
            sequenceIndex: session.nextSequenceIndex,
            workflow: activeWorkflow
        )
        recordAgentTurnUserAnchor(for: session, userItem: userItem)
        session.appendItem(userItem)
        updateBindingsFromSession(session)
        scheduleSave(for: tabID)
        return PreparedUserTurnAppend(
            userItem: userItem,
            effectiveUserText: effectiveUserText,
            wrappedText: wrappedText,
            codexCompactionInFlight: codexCompactionInFlight,
            stagedCodexComputerUseActivationID: stagedCodexComputerUseActivationID,
            disposition: .appended
        )
    }

    /// Non-Codex providers estimate the user turn's tokens up front and dequeue the estimate
    /// when the run consumes it. Shared by composer and scheduled sends.
    func enqueueUserTurnTokenEstimate(
        wrappedText: String,
        attachments: [AgentImageAttachment],
        session: AgentTabSession
    ) -> Int {
        let providerPreviewText = renderProviderMessage(
            text: wrappedText,
            attachments: attachments,
            agent: session.selectedAgent
        )
        return nonCodexContextUsageEstimator(for: session.selectedAgent)?
            .enqueueUserTurnEstimate(messageForProvider: providerPreviewText, session: session)
            ?? Self.estimateRuntimeTokens(for: providerPreviewText)
    }

    /// Chat-bubble text for a user turn: strips an active slash-skill prefix and substitutes an
    /// attachment-only description when no text was typed. Shared by composer and scheduled sends.
    static func userBubbleText(
        trimmedText: String,
        attachments: [AgentImageAttachment],
        taggedFiles: [AgentTaggedFileAttachment],
        workflow: AgentWorkflowDefinition?
    ) -> String {
        if !trimmedText.isEmpty {
            // When a slash-skill is active, strip the `/skillname` prefix from the bubble
            // so the user sees only their arguments (the skill pill shows the command name).
            if let workflow, workflow.displayName.hasPrefix("/") {
                let tokens = extractSlashSkillTokens(from: trimmedText)
                if let token = tokens.first {
                    let argsText = (trimmedText as NSString)
                        .substring(with: token.argumentsRange)
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                    return argsText.isEmpty ? trimmedText : argsText
                }
                return trimmedText
            }
            return trimmedText
        } else if !attachments.isEmpty {
            return "Sent \(attachments.count) image\(attachments.count == 1 ? "" : "s")"
        } else {
            return "Included \(taggedFiles.count) file\(taggedFiles.count == 1 ? "" : "s")"
        }
    }

    /// The interview-first preamble applies only before the assistant has answered anything.
    static func sessionQualifiesForInterviewFirst(_ session: AgentTabSession) -> Bool {
        session.items.isEmpty || !session.items.contains(where: { $0.kind == .assistant })
    }

    static func interviewFirstWrappedUserText(_ userText: String) -> String {
        """
        <interview_first>
        Before starting this task, interview me to make sure you fully understand what I need. Follow these rules exactly:

        1. Ask ONE question at a time using the `ask_user` tool. Always include an `options` array with 2–4 concrete multiple-choice answers so I can respond quickly. Add a final option like "Other (I'll explain)" when my answer might not be listed.
        2. After each answer, adapt your next question based on what I told you. Narrow in on specifics — don't repeat what you already know.
        3. Ask 1–3 questions total. Stop early if the task is already clear enough.
        4. After the interview, briefly summarize what you learned and how it shapes your approach, then proceed with the task.

        Example flow:
        - Q1: "What's the main goal?" → options: ["Add new feature", "Fix a bug", "Refactor existing code", "Other (I'll explain)"]
        - User picks "Add new feature"
        - Q2 (adapted): "Where should this feature live?" → options: ["Extend FooView", "New standalone view", "Backend service layer", "Other (I'll explain)"]
        - ...and so on, each question building on previous answers.
        </interview_first>

        \(userText)
        """
    }

    private func interruptedACPProviderText(for session: AgentTabSession, before steeringUserItem: AgentChatItem) -> String? {
        guard let interruptedUserItem = session.items.last(where: {
            $0.kind == .user && $0.sequenceIndex < steeringUserItem.sequenceIndex
        }) else {
            return nil
        }
        let rendered = renderProviderMessage(
            text: interruptedUserItem.text,
            attachments: interruptedUserItem.attachments,
            agent: session.selectedAgent
        )
        let trimmed = rendered.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private func activeProviderSteeringRoute(
        for session: AgentTabSession,
        attachments: [AgentImageAttachment] = []
    ) -> ActiveProviderSteeringRoute? {
        guard session.runState == .running,
              session.pendingApproval == nil else { return nil }
        if activeACPPromptIsAvailable(for: session, attachments: attachments) {
            return .acpPrompt
        }
        if session.selectedAgent.usesClaudeNativeRuntime {
            return .claudeNativeInterrupt
        }
        return nil
    }

    private func activeACPPromptIsAvailable(
        for session: AgentTabSession,
        attachments: [AgentImageAttachment]
    ) -> Bool {
        guard session.selectedAgent.acpProviderID != nil,
              session.runState == .running,
              session.pendingApproval == nil,
              session.pendingAskUser == nil,
              session.pendingUserInputRequest == nil,
              session.pendingPermissionsRequest == nil,
              attachments.isEmpty,
              session.runID != nil,
              session.activeRunAttemptID != nil,
              session.acpController != nil
        else {
            return false
        }
        // ACP live steering is safe only through the serialized queue. The queue
        // waits for RepoPrompt MCP tools to go idle, then the runner sends
        // session/cancel and waits for the cancelled prompt to settle before the
        // steering session/prompt. Never send prompt-only steering while a turn is
        // already running.
        return true
    }

    private func submitActiveProviderSteering(
        _ route: ActiveProviderSteeringRoute,
        session: AgentTabSession,
        wrappedText: String,
        attachmentsToSend: [AgentImageAttachment],
        taggedFilesToSend: [AgentTaggedFileAttachment],
        trimmedText: String,
        userItem: AgentChatItem,
        identity: AgentQueuedInputIdentity,
        userInputTokenEstimate: Int
    ) {
        assert(identity.userItemID == userItem.id, "Steering identity must name its optimistic user bubble")
        switch route {
        case .acpPrompt:
            // ACP live steering uses the same serialized queued-flush shape as
            // Claude native steering. The run service waits for MCP tools to go idle,
            // sends session/cancel, waits for the active ACP prompt to settle, then
            // submits the steering session/prompt. Do not prompt directly here.
            let interruptedPromptProviderText = interruptedACPProviderText(for: session, before: userItem)
            let steering = AgentTabSession.ACPSteeringInstruction(
                id: UUID(),
                targetRunID: session.runID,
                targetRunAttemptID: session.activeRunAttemptID,
                providerText: wrappedText,
                interruptedPromptProviderText: interruptedPromptProviderText,
                attachments: attachmentsToSend,
                taggedFileAttachments: taggedFilesToSend,
                draftText: trimmedText,
                identity: identity,
                createdAt: Date()
            )
            session.pendingACPSteeringInstructions.append(steering)
            Self.steeringDebugLog("[AgentRunSteeringWake] ACP steering queued tab=\(session.tabID) runID=\(String(describing: session.runID)) attempt=\(String(describing: session.activeRunAttemptID)) queue=\(session.pendingACPSteeringInstructions.count) mcpDispatch=\(session.isMCPInstructionDispatchInProgress)")
            guard !session.isMCPInstructionDispatchInProgress else {
                Self.steeringDebugLog("[AgentRunSteeringWake] ACP steering flush owned by MCP dispatch tab=\(session.tabID) queue=\(session.pendingACPSteeringInstructions.count)")
                return
            }
            Task { [weak self, weak session] in
                guard let self, let session else { return }
                let accepted = await runService.submitQueuedACPSteeringIfSupported(session: session)
                guard !accepted,
                      let queuedIndex = session.pendingACPSteeringInstructions.firstIndex(where: { $0.id == steering.id })
                else {
                    return
                }
                let queued = session.pendingACPSteeringInstructions.remove(at: queuedIndex)
                // Attention notifications only: a completion deferred behind this queued steering is
                // re-evaluated once this handoff settled (after the direct start returned).
                defer { attentionCompletionProgress(for: session) }
                let followUp = AgentPendingInstruction(text: queued.providerText, identity: queued.identity)
                if session.runState.isActive {
                    session.pendingInstructions.insert(followUp, at: 0)
                    // The agent may already be parked in its instruction wait: hand it the head.
                    deliverRequeuedHeadToLiveInstructionWaitIfNeeded(session)
                } else if session.runState == .completed, session.acpController != nil {
                    let afterStart = beginAttentionFollowUpObservation(for: session)
                    let outcome = await startAgentRun(
                        tabID: session.tabID,
                        initialMessage: queued.providerText,
                        inputConstituents: [queued.identity]
                    )
                    // Durable input that was never handed off stays queued as a follow-up.
                    if followUp.isDurable, Self.runStartDidNotHandOff(outcome) {
                        session.pendingInstructions.insert(followUp, at: 0)
                        session.isDirty = true
                        scheduleSave(for: session.tabID)
                    }
                    afterStart()
                } else {
                    // ACP steering should never bounce back into the composer. If the
                    // active-steering queue was rejected before the run service could take it,
                    // preserve it as a normal provider follow-up instead.
                    session.pendingInstructions.insert(followUp, at: 0)
                    session.isDirty = true
                    updateBindingsFromSession(session)
                    scheduleSave(for: session.tabID)
                }
            }
        case .claudeNativeInterrupt:
            // Claude Code preserves draft text and wakes current MCP waiters as soon
            // as the local steering request is accepted, then sends after MCP tools idle.
            let steering = AgentTabSession.ClaudeSteeringInstruction(
                id: UUID(),
                targetRunID: session.runID,
                targetRunAttemptID: session.activeRunAttemptID,
                providerText: wrappedText,
                attachments: attachmentsToSend,
                taggedFileAttachments: taggedFilesToSend,
                draftText: trimmedText,
                identity: identity,
                createdAt: Date(),
                supersedingProtectedTurnIDs: []
            )
            session.pendingClaudeSteeringInstructions.append(steering)
            runService.protectCurrentClaudeTurnForAcceptedSteeringIfNeeded(session: session, steeringID: steering.id)
            Self.steeringDebugLog("[AgentRunSteeringWake] Claude steering queued tab=\(session.tabID) runID=\(String(describing: session.runID)) attempt=\(String(describing: session.activeRunAttemptID)) queue=\(session.pendingClaudeSteeringInstructions.count) mcpDispatch=\(session.isMCPInstructionDispatchInProgress)")
            guard !session.isMCPInstructionDispatchInProgress else {
                Self.steeringDebugLog("[AgentRunSteeringWake] Claude steering flush owned by MCP dispatch tab=\(session.tabID) queue=\(session.pendingClaudeSteeringInstructions.count)")
                return
            }
            Task { [weak self] in
                guard let self else { return }
                _ = await runService.submitQueuedClaudeSteeringIfSupported(session: session)
            }
        }
    }

    private struct NativeControlProgressRestoreState {
        let id: UUID
        let tabID: UUID
        let previousRunState: AgentSessionRunState
        let previousRunningStatusText: String?
        let previousRunningStatusSource: AgentTabSession.RunningStatusSource?
        let previousActiveAgentRunStartedAt: Date?
        let wasMarkedActiveInTabs: Bool
        let progressStatusText: String
    }

    private func appendOptimisticGoalObjectiveUserBubbleIfNeeded(
        action: CodexAgentModeCoordinator.GoalSlashAction?,
        session: AgentTabSession,
        workflow: AgentWorkflowDefinition?
    ) {
        guard case let .setObjective(objective) = action else { return }
        let userItem = AgentChatItem.user(
            objective,
            sequenceIndex: session.nextSequenceIndex,
            workflow: workflow,
            codexGoalMode: AgentCodexGoalModeMetadata(action: .setObjective),
            isLocalControlPlaneEcho: true
        )
        session.appendItem(userItem)
        updateBindingsFromSession(session)
        scheduleSave(for: session.tabID)
        requestUIRefresh(tabID: session.tabID, urgent: true)
    }

    private func beginNativeSlashControlProgressIfNeeded(
        command: CodexAgentModeCoordinator.NativeSlashCommand,
        action: CodexAgentModeCoordinator.GoalSlashAction?,
        session: AgentTabSession
    ) -> NativeControlProgressRestoreState? {
        guard command == .goal else { return nil }
        let progressText = switch action ?? .show {
        case .setObjective:
            "Setting Codex goal…"
        case .show:
            "Loading Codex goal…"
        case .pause:
            "Pausing Codex goal…"
        case .resume:
            "Resuming Codex goal…"
        case .clear:
            "Clearing Codex goal…"
        }
        let id = UUID()
        let restoreState = NativeControlProgressRestoreState(
            id: id,
            tabID: session.tabID,
            previousRunState: session.runState,
            previousRunningStatusText: session.runningStatusText,
            previousRunningStatusSource: session.runningStatusSource,
            previousActiveAgentRunStartedAt: session.activeAgentRunStartedAt,
            wasMarkedActiveInTabs: tabsWithActiveAgentRun.contains(session.tabID),
            progressStatusText: progressText
        )
        session.nativeControlProgressID = id
        session.runState = .running
        session.setRunningStatus(progressText, source: .transport)
        setAgentRunActive(session.tabID, isActive: true)
        requestUIRefresh(tabID: session.tabID, urgent: true)
        return restoreState
    }

    private func finishNativeSlashControlProgress(
        _ restoreState: NativeControlProgressRestoreState?,
        session: AgentTabSession?
    ) {
        guard let restoreState,
              let session,
              session.nativeControlProgressID == restoreState.id
        else { return }
        let progressStillDisplayed = session.runningStatusText == restoreState.progressStatusText
            && session.runningStatusSource == .transport
        session.nativeControlProgressID = nil
        guard progressStillDisplayed else {
            requestUIRefresh(tabID: restoreState.tabID, urgent: true)
            return
        }
        session.setRunningStatus(
            restoreState.previousRunningStatusText,
            source: restoreState.previousRunningStatusSource
        )
        if session.runState == .running {
            session.runState = restoreState.previousRunState
        }
        if restoreState.wasMarkedActiveInTabs {
            session.activeAgentRunStartedAt = restoreState.previousActiveAgentRunStartedAt
            publishActiveAgentRunStartedAt(for: restoreState.tabID, session: session)
        } else {
            setAgentRunActive(restoreState.tabID, isActive: false)
        }
        requestUIRefresh(tabID: restoreState.tabID, urgent: true)
    }

    private func submitNativeSlashCommandAfterHydration(
        tabID: UUID,
        invocation: ResolvedNativeSlashCommand,
        selectedWorkflowForGoal: AgentWorkflowDefinition?,
        progressRestoreState: NativeControlProgressRestoreState?
    ) async -> CodexAgentModeCoordinator.NativeSlashCommandExecutionResult? {
        guard let session = sessions[tabID] else { return nil }
        let semanticRunState = progressRestoreState?.previousRunState ?? session.runState
        if !semanticRunState.isActive || (session.activeAgentSessionID != nil && !session.hasLoadedPersistedState) {
            await prepareSessionForRunStart(tabID: tabID, session: session)
        }
        guard let hydratedSession = sessions[tabID] else {
            finishNativeSlashControlProgress(progressRestoreState, session: sessions[tabID])
            return nil
        }
        let result = await codexCoordinator.executeNativeSlashCommand(
            invocation.command,
            argumentsText: invocation.argumentsText,
            session: hydratedSession,
            selectedWorkflowForGoal: selectedWorkflowForGoal,
            semanticRunStateForControlCommand: progressRestoreState?.previousRunState
        )
        switch result {
        case let .succeeded(message):
            let item = AgentChatItem.system(message, sequenceIndex: hydratedSession.nextSequenceIndex)
            hydratedSession.appendItem(item)
        case let .failed(message):
            let item = AgentChatItem.error(message, sequenceIndex: hydratedSession.nextSequenceIndex)
            hydratedSession.appendItem(item)
        }
        updateBindingsFromSession(hydratedSession)
        scheduleSave(for: tabID)
        finishNativeSlashControlProgress(progressRestoreState, session: hydratedSession)
        return result
    }

    func resolvedNativeSlashCommand(
        in text: String,
        session: AgentTabSession
    ) -> ResolvedNativeSlashCommand? {
        guard let token = Self.extractSlashSkillTokens(from: text).first,
              !token.name.lowercased().hasPrefix("skill:"),
              let command = codexCoordinator.nativeSlashCommand(named: token.name, session: session)
        else {
            return nil
        }
        let argumentsText = (text as NSString)
            .substring(with: token.argumentsRange)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return ResolvedNativeSlashCommand(command: command, token: token, argumentsText: argumentsText)
    }

    private func prepareNativeSlashPreparedUserTurn(
        _ invocation: ResolvedNativeSlashCommand
    ) -> NativeSlashPreparedUserTurn {
        switch invocation.command {
        case .computerUse:
            NativeSlashPreparedUserTurn(
                command: invocation.command,
                argumentsText: invocation.argumentsText,
                providerText: CodexComputerUseWorkflow.renderProviderPrompt(userInstructions: invocation.argumentsText),
                bubbleWorkflow: CodexComputerUseWorkflow.bubbleWorkflowDefinition(),
                shouldEnableCodexComputerUse: true
            )
        case .compact, .goal:
            NativeSlashPreparedUserTurn(
                command: invocation.command,
                argumentsText: invocation.argumentsText,
                providerText: invocation.argumentsText,
                bubbleWorkflow: nil,
                shouldEnableCodexComputerUse: false
            )
        }
    }

    private func clearPendingCodexComputerUseActivationIfMatched(
        session: AgentTabSession,
        activationID: UUID?
    ) {
        guard let activationID,
              session.pendingCodexComputerUseActivation?.id == activationID
        else {
            return
        }
        session.pendingCodexComputerUseActivation = nil
    }

    private func validateNativeSlashCommandUsage(
        _ invocation: ResolvedNativeSlashCommand,
        session: AgentTabSession,
        attachments: [AgentImageAttachment],
        taggedFiles: [AgentTaggedFileAttachment],
        activeWorkflow: AgentWorkflowDefinition?
    ) -> UserTurnSubmissionResult? {
        let argumentsText = invocation.argumentsText
        if activeWorkflow != nil,
           invocation.command.behavior == .userTurnWrapper
        {
            return .blocked(message: "/\(invocation.command.rawValue) is a Codex native workflow that starts its own provider turn. Clear the selected prompt workflow before using it.")
        }
        if !attachments.isEmpty || !taggedFiles.isEmpty {
            let suffix = invocation.command == .computerUse ? " yet" : ""
            return .blocked(message: "The /\(invocation.command.rawValue) command cannot be used with attachments or tagged files\(suffix).")
        }
        switch invocation.command {
        case .compact:
            if !argumentsText.isEmpty {
                return .blocked(message: "/compact does not take arguments.")
            }
        case .goal:
            if case let .setObjective(objective) = CodexAgentModeCoordinator.goalSlashAction(from: argumentsText) {
                if let message = CodexAgentModeCoordinator.goalObjectiveValidationMessage(objective) {
                    return .blocked(message: message)
                }
                if let activeWorkflow {
                    let includeBuiltInCleanupGuidance = GlobalSettingsStore.shared.showBuiltInWorkflowCleanupGuidance()
                    switch CodexAgentModeCoordinator.composeGoalObjective(
                        rawObjective: objective,
                        selectedWorkflow: activeWorkflow,
                        includeBuiltInSessionCleanupGuidance: includeBuiltInCleanupGuidance
                    ) {
                    case .success:
                        break
                    case let .failure(message):
                        return .blocked(message: message)
                    }
                }
            }
        case .computerUse:
            break
        }
        let shouldCheckAvailability = invocation.command == .computerUse
            || session.activeAgentSessionID == nil
            || session.hasLoadedPersistedState
        if shouldCheckAvailability,
           let availabilityMessage = codexCoordinator.nativeSlashCommandAvailabilityMessage(
               invocation.command,
               argumentsText: argumentsText,
               session: session
           )
        {
            return .blocked(message: availabilityMessage)
        }
        return nil
    }

    private func validateSlashSkillUsage(
        in text: String,
        activeWorkflow: AgentWorkflowDefinition?
    ) -> UserTurnSubmissionResult? {
        let invocations = resolvedSlashSkillInvocations(in: text)
        guard !invocations.isEmpty else {
            return nil
        }
        if invocations.count > 1 {
            return .blocked(message: "Only one /skill can be used per message.")
        }
        if activeWorkflow != nil {
            return .blocked(message: "Use either a selected workflow or a /skill, not both.")
        }
        return nil
    }

    func resolvedSlashSkillInvocations(in text: String) -> [ResolvedSlashSkillInvocation] {
        Self.extractSlashSkillTokens(from: text).compactMap { token in
            let resolvedName: String = {
                let normalizedName = token.name.trimmingCharacters(in: .whitespacesAndNewlines)
                if normalizedName.lowercased().hasPrefix("skill:") {
                    return String(normalizedName.dropFirst("skill:".count))
                }
                return normalizedName
            }()
            guard !resolvedName.isEmpty,
                  let definition = skillCatalog.resolve(name: resolvedName)
            else {
                return nil
            }
            return ResolvedSlashSkillInvocation(definition: definition, token: token)
        }
    }

    /// Extract a slash-skill token only when `/` is the first non-whitespace character in the text.
    /// This allows literal slashes deeper in the input (e.g. file paths) without triggering skill expansion.
    static func extractSlashSkillTokens(from text: String) -> [SlashSkillToken] {
        guard !text.isEmpty else { return [] }
        let fullText = text as NSString
        let length = fullText.length
        guard length > 0 else { return [] }

        // Find the first non-whitespace character; it must be `/` for a skill token.
        var slashIndex = 0
        while slashIndex < length {
            let ch = fullText.character(at: slashIndex)
            if let scalar = UnicodeScalar(ch), CharacterSet.whitespacesAndNewlines.contains(scalar) {
                slashIndex += 1
                continue
            }
            break
        }
        guard slashIndex < length, fullText.character(at: slashIndex) == 47 /* "/" */ else {
            return []
        }

        // Scan the skill name immediately after the `/`
        var cursor = slashIndex + 1
        var hasNameCharacter = false
        var isInvalidToken = false
        while cursor < length {
            let current = fullText.character(at: cursor)
            guard let scalar = UnicodeScalar(current) else {
                isInvalidToken = true
                break
            }
            if CharacterSet.whitespacesAndNewlines.contains(scalar) {
                break
            }
            if Self.slashSkillNameScalars.contains(scalar) {
                hasNameCharacter = true
                cursor += 1
                continue
            }
            if scalar == ":",
               fullText.substring(with: NSRange(location: slashIndex + 1, length: cursor - slashIndex - 1)).lowercased() == "skill"
            {
                hasNameCharacter = true
                cursor += 1
                continue
            }
            isInvalidToken = true
            break
        }

        guard hasNameCharacter, !isInvalidToken else { return [] }

        let nameRange = NSRange(location: slashIndex + 1, length: cursor - slashIndex - 1)
        let name = fullText.substring(with: nameRange)
        let tokenRange = NSRange(location: slashIndex, length: cursor - slashIndex)
        let argumentsRange = NSRange(location: cursor, length: length - cursor)
        return [SlashSkillToken(name: name, tokenRange: tokenRange, argumentsRange: argumentsRange)]
    }

    private func shouldSignalMCPInstructionDeliveredAfterOptimisticSubmit(for session: AgentTabSession) -> Bool {
        guard session.mcpControlContext != nil,
              session.runState == .running,
              !session.isMCPInstructionDispatchInProgress
        else {
            return false
        }
        return mcpActiveInstructionDeliverySignalTiming(for: session) == .afterOptimisticSubmit
    }

    private func mcpActiveInstructionDeliverySignalTiming(
        for session: AgentTabSession
    ) -> MCPActiveInstructionDeliverySignalTiming {
        switch activeProviderSteeringRoute(for: session) {
        case .claudeNativeInterrupt, .acpPrompt:
            .afterProviderSend
        case nil:
            session.selectedAgent == .codexExec
                ? .afterProviderSend
                : .afterOptimisticSubmit
        }
    }

    #if DEBUG
        static func test_mcpActiveInstructionDeliverySignalTiming(
            selectedAgent: AgentProviderKind,
            hasNativeSteeringRoute: Bool
        ) -> MCPActiveInstructionDeliverySignalTiming {
            if hasNativeSteeringRoute {
                return .afterProviderSend
            }
            return selectedAgent == .codexExec
                ? .afterProviderSend
                : .afterOptimisticSubmit
        }
    #endif

    func renderProviderMessage(
        text: String,
        attachments: [AgentImageAttachment],
        agent: AgentProviderKind
    ) -> String {
        guard !attachments.isEmpty else { return text }
        switch agent {
        case .claudeCode, .claudeCodeGLM, .kimiCode, .customClaudeCompatible, .openCode, .cursor, .ohMyPi:
            return renderAtPathAttachmentMessage(text: text, attachments: attachments)
        case .codexExec:
            return text
        }
    }

    private func renderAtPathAttachmentMessage(text: String, attachments: [AgentImageAttachment]) -> String {
        var lines: [String] = []
        for attachment in attachments {
            switch attachment.source {
            case let .localFile(path):
                let trimmedPath = path.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !trimmedPath.isEmpty else { continue }
                lines.append("@\(escapePathForAtCommand(trimmedPath))")
            case let .url(url):
                let trimmedURL = url.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !trimmedURL.isEmpty else { continue }
                lines.append(trimmedURL)
            }
        }
        guard !lines.isEmpty else { return text }
        if !text.isEmpty {
            lines.append("")
            lines.append(text)
        }
        return lines.joined(separator: "\n")
    }

    func escapePathForAtCommand(_ path: String) -> String {
        var escaped = ""
        for character in path {
            switch character {
            case "\\", " ", ",", ";", "!", "?", "(", ")", "[", "]", "{", "}":
                escaped.append("\\")
                escaped.append(character)
            default:
                escaped.append(character)
            }
        }
        return escaped
    }

    private static func estimateRuntimeTokens(for text: String) -> Int {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return 0 }
        return TokenCalculationService.estimateTokens(for: trimmed)
    }

    static func extractTaggedPaths(from text: String) -> [String] {
        guard !text.isEmpty else { return [] }
        let scalars = Array(text.unicodeScalars)
        var ordered: [String] = []
        ordered.reserveCapacity(8)
        var seen = Set<String>()
        var index = 0

        while index < scalars.count {
            let scalar = scalars[index]
            guard scalar == "@" else {
                index += 1
                continue
            }
            if index > 0 {
                let previous = scalars[index - 1]
                if !taggedFileTerminatingScalars.contains(previous) {
                    index += 1
                    continue
                }
            }

            var cursor = index + 1
            var tokenScalars: [UnicodeScalar] = []
            var isEscaped = false

            while cursor < scalars.count {
                let current = scalars[cursor]
                if isEscaped {
                    tokenScalars.append(current)
                    isEscaped = false
                    cursor += 1
                    continue
                }
                if current == "\\" {
                    isEscaped = true
                    cursor += 1
                    continue
                }
                if taggedFileTerminatingScalars.contains(current) {
                    break
                }
                tokenScalars.append(current)
                cursor += 1
            }

            var token = String(String.UnicodeScalarView(tokenScalars))
            token = token.trimmingCharacters(in: taggedFileTrailingTrimSet)
            if !token.isEmpty {
                let lowered = token.lowercased()
                if !lowered.hasPrefix("/"),
                   !lowered.hasPrefix("~"),
                   !lowered.hasPrefix("file://"),
                   seen.insert(token).inserted
                {
                    ordered.append(token)
                }
            }

            index = cursor
        }

        return ordered
    }

    static func unescapeTaggedPath(_ value: String) -> String {
        guard value.contains("\\") else {
            return value.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        let scalars = Array(value.unicodeScalars)
        var output: [UnicodeScalar] = []
        output.reserveCapacity(scalars.count)
        var index = 0
        while index < scalars.count {
            let current = scalars[index]
            if current == "\\", index + 1 < scalars.count {
                let next = scalars[index + 1]
                switch next {
                case "\\", " ", ",", ";", "!", "?", "(", ")", "[", "]", "{", "}":
                    output.append(next)
                default:
                    output.append(current)
                    output.append(next)
                }
                index += 2
                continue
            }
            output.append(current)
            index += 1
        }
        return String(String.UnicodeScalarView(output)).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    @MainActor
    private func fileContentsXMLForTaggedPaths(
        _ taggedPaths: [String],
        tokenBudget: Int,
        maxFiles: Int,
        lookupContext: WorkspaceLookupContext = .visibleWorkspace
    ) async -> String? {
        guard let promptManager else { return nil }
        return await Self.taggedFileContentsXMLForTaggedPaths(
            taggedPaths,
            tokenBudget: tokenBudget,
            maxFiles: maxFiles,
            store: promptManager.workspaceFileContextStore,
            lookupContext: lookupContext
        )
    }

    static func taggedFileContentsXMLForTaggedPaths(
        _ taggedPaths: [String],
        tokenBudget: Int,
        maxFiles: Int,
        store: WorkspaceFileContextStore,
        lookupContext: WorkspaceLookupContext = .visibleWorkspace
    ) async -> String? {
        guard !taggedPaths.isEmpty else { return nil }

        enum TaggedReadableFile {
            case workspace(ResolvedPromptFileEntry)
            case external(WorkspaceExternalReadableFile)
        }

        let readableService = WorkspaceReadableFileService(store: store)
        var orderedFiles: [TaggedReadableFile] = []
        orderedFiles.reserveCapacity(min(taggedPaths.count, maxFiles))
        var workspaceEntries: [ResolvedPromptFileEntry] = []
        workspaceEntries.reserveCapacity(min(taggedPaths.count, maxFiles))
        var seenFileIDs = Set<UUID>()
        var seenExternalPaths = Set<String>()
        let scopedRootRefs = await store.rootRefs(scope: lookupContext.rootScope)
        let rootsByID = Dictionary(uniqueKeysWithValues: scopedRootRefs.map { ($0.id, $0) })
        let displayRootRefs = lookupContext.bindingProjection?.visibleLogicalRootRefs ?? scopedRootRefs

        for taggedPath in taggedPaths {
            guard orderedFiles.count < maxFiles else { break }
            let translatedPath = lookupContext.translateInputPath(taggedPath)
            guard let readable = await readableService.resolveReadableFile(
                translatedPath,
                profile: .mcpRead,
                rootScope: lookupContext.rootScope
            ) else { continue }
            switch readable {
            case let .workspace(file):
                guard seenFileIDs.insert(file.id).inserted,
                      let content = try? await store.readContent(rootID: file.rootID, relativePath: file.standardizedRelativePath),
                      let root = rootsByID[file.rootID]
                else { continue }
                let entry = ResolvedPromptFileEntry(
                    file: file,
                    isCodemap: false,
                    mode: .fullFile,
                    loadedContent: content,
                    rootFolderPath: root.standardizedFullPath
                )
                workspaceEntries.append(entry)
                orderedFiles.append(.workspace(entry))
            case let .external(externalFile):
                guard seenExternalPaths.insert(externalFile.absolutePath).inserted else { continue }
                orderedFiles.append(.external(externalFile))
            }
        }

        guard !orderedFiles.isEmpty else { return nil }

        let workspaceBlocks = PromptPackagingService.generateFileBlocksDetailed(
            files: workspaceEntries,
            filePathDisplay: .relative,
            codemapPresentation: .empty,
            displayPathResolver: { entry in
                if let projected = lookupContext.bindingProjection?.projectedLogicalPathComponents(
                    forPhysicalPath: entry.file.standardizedFullPath
                ) {
                    return ClientPathFormatter.nonAbsoluteDisplayPath(
                        root: projected.root,
                        relativePath: projected.relativePath,
                        visibleRoots: displayRootRefs
                    )
                }
                guard let root = rootsByID[entry.file.rootID] else {
                    return entry.file.standardizedRelativePath
                }
                return ClientPathFormatter.nonAbsoluteDisplayPath(
                    root: root,
                    relativePath: entry.file.standardizedRelativePath,
                    visibleRoots: displayRootRefs
                )
            }
        )
        let workspaceBlocksByID = Dictionary(uniqueKeysWithValues: workspaceBlocks.map { ($0.file.id, $0.text) })

        var blocks: [String] = []
        blocks.reserveCapacity(orderedFiles.count)
        for file in orderedFiles {
            switch file {
            case let .workspace(workspaceEntry):
                guard let block = workspaceBlocksByID[workspaceEntry.file.id], !block.isEmpty else { continue }
                blocks.append(block)
            case let .external(externalFile):
                guard let content = try? await readableService.readAlwaysReadableExternalFile(externalFile) else { continue }
                blocks.append(Self.externalTaggedFileBlock(displayPath: externalFile.displayPath, content: content))
            }
        }

        guard !blocks.isEmpty else { return nil }

        var acceptedBlocks: [String] = []
        acceptedBlocks.reserveCapacity(blocks.count)
        var runningTokens = 0
        for block in blocks {
            let blockTokens = TokenCalculationService.estimateTokens(for: block)
            if runningTokens + blockTokens > tokenBudget {
                break
            }
            acceptedBlocks.append(block)
            runningTokens += blockTokens
        }

        guard !acceptedBlocks.isEmpty else { return nil }
        return """
        <file_contents>
        \(acceptedBlocks.joined(separator: "\n\n"))
        </file_contents>
        """
    }

    private nonisolated static func externalTaggedFileBlock(displayPath: String, content: String) -> String {
        let fence = PromptPackagingService.codeFenceStart(for: displayPath)
        return """
        File: \(displayPath)
        \(fence)
        \(content)
        ```
        """
    }

    @MainActor
    func autoSelectTaggedFilesForTurn(
        tabID: UUID,
        text: String,
        taggedFileAttachments: [AgentTaggedFileAttachment]
    ) {
        guard Self.shouldAttemptTaggedFileAutoSelection(
            text: text,
            taggedFileAttachments: taggedFileAttachments
        ) else {
            return
        }

        Task { @MainActor [weak self] in
            await self?.promoteSelectionPathsToFullContext(
                tabID: tabID,
                rawPaths: Self.taggedSelectionRawPaths(text: text, taggedFileAttachments: taggedFileAttachments)
            )
        }
    }

    private static func taggedSelectionRawPaths(
        text: String,
        taggedFileAttachments: [AgentTaggedFileAttachment]
    ) -> [String] {
        var rawPaths: [String] = []
        rawPaths.reserveCapacity(extractTaggedPaths(from: text).count + taggedFileAttachments.count)
        rawPaths.append(contentsOf: extractTaggedPaths(from: text))
        rawPaths.append(contentsOf: taggedFileAttachments.map(\.relativePath))
        return rawPaths
    }

    @MainActor
    func promoteSelectionPathsToFullContext(
        tabID: UUID,
        rawPaths: [String]
    ) async {
        guard !rawPaths.isEmpty,
              let promptManager,
              let workspaceManager
        else {
            return
        }

        let store = promptManager.workspaceFileContextStore
        let lookupContext = await agentWorkspaceLookupContext(tabID: tabID, session: session(for: tabID, createIfNeeded: false))
        let resolvedPaths = await resolvedWorkspaceTaggedSelectionPaths(
            rawPaths: rawPaths,
            store: store,
            lookupContext: lookupContext
        )
        guard !resolvedPaths.isEmpty else { return }

        if promptManager.activeComposeTabID == tabID {
            workspaceManager.publishActiveComposeTabSnapshot(commitToMemory: true)
        }
        guard var tab = workspaceManager.composeTab(with: tabID) else { return }
        let updatedSelection = Self.selectionByPromotingPathsToFullSelection(
            tab.selection,
            paths: resolvedPaths,
            lookupContext: lookupContext
        )
        guard updatedSelection != tab.selection else { return }
        tab.selection = updatedSelection
        workspaceManager.updateComposeTabStoredOnly(tab)
    }

    static func shouldAttemptTaggedFileAutoSelection(
        text: String,
        taggedFileAttachments: [AgentTaggedFileAttachment]
    ) -> Bool {
        !taggedFileAttachments.isEmpty || !extractTaggedPaths(from: text).isEmpty
    }

    private func resolvedWorkspaceTaggedSelectionPaths(
        rawPaths: [String],
        store: WorkspaceFileContextStore,
        lookupContext: WorkspaceLookupContext
    ) async -> [String] {
        var normalizedPaths: [String] = []
        normalizedPaths.reserveCapacity(rawPaths.count)
        var seenInputs = Set<String>()
        for rawPath in rawPaths {
            let normalizedPath = Self.unescapeTaggedPath(rawPath)
            guard !normalizedPath.isEmpty, seenInputs.insert(normalizedPath).inserted else { continue }
            normalizedPaths.append(normalizedPath)
        }
        guard !normalizedPaths.isEmpty else { return [] }

        let translatedPaths = normalizedPaths.map { lookupContext.translateInputPath($0) }
        let requests = translatedPaths.map {
            WorkspacePathLookupRequest(userPath: $0, profile: .mcpRead, rootScope: lookupContext.rootScope)
        }
        let lookupResults = await store.lookupPaths(requests)
        var resolvedPaths: [String] = []
        resolvedPaths.reserveCapacity(normalizedPaths.count)
        var seenResolved = Set<String>()
        for translatedPath in translatedPaths {
            guard let file = lookupResults[translatedPath]?.file else { continue }
            let physicalPath = file.standardizedFullPath
            guard seenResolved.insert(physicalPath).inserted else { continue }
            resolvedPaths.append(lookupContext.displayPath(forPhysicalPath: physicalPath, display: .full))
        }
        return resolvedPaths
    }

    nonisolated static func selectionByPromotingPathsToFullSelection(
        _ selection: StoredSelection,
        paths: [String],
        lookupContext: WorkspaceLookupContext = .visibleWorkspace
    ) -> StoredSelection {
        let logicalSelection = lookupContext.logicalizeSelection(selection)
        let promotedPaths = StoredSelectionPathNormalization.standardizedPaths(paths)
        guard !promotedPaths.isEmpty else { return logicalSelection == selection ? selection : logicalSelection }

        let existingPaths = StoredSelectionPathNormalization.standardizedPaths(logicalSelection.selectedPaths)
        let existingSlices = StoredSelectionPathNormalization.standardizedSlices(logicalSelection.slices)
        let promotedKeys = Set(promotedPaths.map { physicalizedSelectionKey($0, lookupContext: lookupContext) })

        var mergedPaths = existingPaths
        var seen = Set(existingPaths.map { physicalizedSelectionKey($0, lookupContext: lookupContext) })
        for path in promotedPaths where seen.insert(physicalizedSelectionKey(path, lookupContext: lookupContext)).inserted {
            mergedPaths.append(path)
        }

        let filteredSlices = existingSlices.filter {
            !promotedKeys.contains(physicalizedSelectionKey($0.key, lookupContext: lookupContext))
        }

        let normalizedSelection = StoredSelection(
            selectedPaths: existingPaths,
            manualCodemapPaths: logicalSelection.manualCodemapPaths,
            slices: existingSlices,
            codemapAutoEnabled: selection.codemapAutoEnabled
        )
        let updatedSelection = StoredSelection(
            selectedPaths: mergedPaths,
            manualCodemapPaths: logicalSelection.manualCodemapPaths.filter {
                !promotedKeys.contains(physicalizedSelectionKey($0, lookupContext: lookupContext))
            },
            slices: filteredSlices,
            codemapAutoEnabled: selection.codemapAutoEnabled
        )
        return updatedSelection == normalizedSelection && logicalSelection == selection ? selection : updatedSelection
    }

    private nonisolated static func physicalizedSelectionKey(
        _ path: String,
        lookupContext: WorkspaceLookupContext
    ) -> String {
        let translated = lookupContext.translateInputPath(path)
        let expanded = (translated as NSString).expandingTildeInPath
        if expanded.hasPrefix("/") {
            return StandardizedPath.absolute(expanded)
        }
        return StandardizedPath.relative(expanded)
    }

    @MainActor
    func augmentUserMessageForProviderSend(
        _ text: String,
        attachments: [AgentImageAttachment] = [],
        taggedFileAttachments: [AgentTaggedFileAttachment] = [],
        agent: AgentProviderKind? = nil,
        session: AgentTabSession? = nil,
        carriers: [AgentQueuedInputIdentity]
    ) async -> AgentStagedProviderText {
        let effectiveAgent = session?.selectedAgent ?? agent ?? activeSession?.selectedAgent ?? selectedAgent
        let withSkillExpansion = await expandSlashSkillInvocationIfNeeded(text, agentKind: effectiveAgent)
        let lookupContext: WorkspaceLookupContext = if let session {
            await agentWorkspaceLookupContext(tabID: session.tabID, session: session)
        } else if let tabID = currentTabID {
            await agentWorkspaceLookupContext(tabID: tabID, session: sessions[tabID])
        } else {
            .visibleWorkspace
        }
        let withTaggedFiles = await augmentUserMessageWithTaggedFileContents(
            withSkillExpansion,
            taggedFileAttachments: taggedFileAttachments,
            lookupContext: lookupContext
        )
        let withAttachmentRendering = renderProviderMessage(
            text: withTaggedFiles,
            attachments: attachments,
            agent: effectiveAgent
        )
        guard let session else { return AgentStagedProviderText(text: withAttachmentRendering) }
        return await stagePendingHandoff(withAttachmentRendering, session: session, carriers: carriers)
    }

    /// Text-only form of `stagePendingHandoffIfNeeded` (the stage it creates still awaits an outcome).
    @MainActor
    func prependPendingHandoffIfNeeded(
        _ text: String,
        session: AgentTabSession
    ) -> String {
        stagePendingHandoffIfNeeded(text, session: session).text
    }

    /// Prepends the pending-handoff payload as a new exact stage unless it is already staged into
    /// another input or held as possibly delivered (an uncertain stage or an unresolved recovery
    /// join): a held payload is never prepended again automatically. A legacy payload is assigned
    /// its durable payload ID here (persisted by the next save).
    @MainActor
    func stagePendingHandoffIfNeeded(
        _ text: String,
        session: AgentTabSession
    ) -> AgentStagedProviderText {
        guard let handoffPayload = session.pendingHandoff.payload,
              !session.pendingHandoff.isReservedForSend
        else {
            return AgentStagedProviderText(text: text)
        }
        let trimmedPayload = handoffPayload.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedPayload.isEmpty else {
            return AgentStagedProviderText(text: text)
        }
        let hadPayloadID = session.pendingHandoff.payloadID != nil
        guard let payloadID = session.pendingHandoff.ensurePayloadID() else {
            return AgentStagedProviderText(text: text)
        }
        if !hadPayloadID {
            session.isDirty = true
        }
        let stage = AgentPendingHandoffStage(payloadID: payloadID)
        session.pendingHandoff.stage = stage
        session.pendingHandoff.isStagedForSend = true
        return AgentStagedProviderText(text: trimmedPayload + "\n\n" + text, pendingHandoffStage: stage)
    }

    // SEARCH-HELPER: Handoff, Resume, Recovery, Transcript, Session Transfer
    // Shared helper that stages a resume-recovery handoff so the model has
    // conversational context after a forced fresh session start.
    @MainActor
    func stageResumeRecoveryHandoffIfNeeded(for session: AgentTabSession) async {
        _ = await stageResumeRecoveryHandoffIfNeeded(
            for: session,
            ifStillOwned: { true },
            beforeCommit: nil
        )
    }

    @MainActor
    private func stageResumeRecoveryHandoffIfNeeded(
        for session: AgentTabSession,
        ifStillOwned: @escaping @MainActor () -> Bool,
        beforeCommit: (@MainActor () async -> Void)?
    ) async -> Bool {
        guard ifStillOwned() else { return false }
        // Don't overwrite an existing staged payload.
        if let existingPayload = session.pendingHandoff.payload,
           !existingPayload.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            return true
        }
        let cutoffItemID = session.items.last(where: { $0.kind != .thinking })?.id
        let sourceTabName = normalizedSessionTitle(workspaceManager?.composeTabName(with: session.tabID))
        let escapedSourceTabName = sourceTabName
            .replacingOccurrences(of: "\u{26}", with: "\u{26}amp;")
            .replacingOccurrences(of: "\u{22}", with: "\u{26}quot;")
            .replacingOccurrences(of: "<", with: "\u{26}lt;")
            .replacingOccurrences(of: ">", with: "\u{26}gt;")
        let sourceAgentName = session.selectedAgent.displayName
        let transcriptXML = buildForkTranscriptXML(from: session, upToItemID: cutoffItemID)
        // delivery_id makes crash/restart retries best-effort idempotent at the prompt level.
        let deliveryID = UUID().uuidString
        let payload = await Self.composeClaudeResumeRecoveryHandoffPayload(
            sourceTabName: escapedSourceTabName,
            sourceAgentName: sourceAgentName,
            transcriptXML: transcriptXML,
            initialThreadContextBlock: buildInitialThreadContextBlock(tabID: session.tabID),
            deliveryID: deliveryID
        )
        guard !payload.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return ifStillOwned()
        }
        await beforeCommit?()
        guard ifStillOwned() else { return false }
        if let existingPayload = session.pendingHandoff.payload,
           !existingPayload.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            return true
        }
        session.pendingHandoff = AgentPendingHandoffState(
            payload: payload,
            createdAt: Date(),
            sourceItemID: cutoffItemID,
            payloadID: UUID(),
            defersProviderLockUntilSend: false,
            isStagedForSend: false
        )
        session.isDirty = true
        return true
    }

    @MainActor
    func stageClaudeResumeRecoveryHandoffIfNeeded(
        for session: AgentTabSession,
        ifStillOwned: @escaping @MainActor () -> Bool,
        beforeCommit: (@MainActor () async -> Void)?
    ) async -> Bool {
        await stageResumeRecoveryHandoffIfNeeded(
            for: session,
            ifStillOwned: ifStillOwned,
            beforeCommit: beforeCommit
        )
    }

    /// Settles exactly `stage` of the pending-handoff payload (stage-delivery semantics, not provider
    /// acceptance; delegated child-question notices settle separately by their own stage):
    /// - `.sent` consumes that payload (never downgraded: the payload is gone);
    /// - `.notSent` releases the stage for a later send (verified non-handoff or rejection);
    /// - `.deliveryUnknown` holds it: no consumption, no re-prepend, no release.
    /// A nil, superseded, or other-payload stage is a no-op, so a late outcome never settles a newer
    /// stage or clears a newer payload. A recovery hold is resolved only by the recovery join.
    @MainActor
    func recordPendingHandoffStageOutcome(
        for session: AgentTabSession,
        stage: AgentPendingHandoffStage?,
        disposition: AgentStagedInputDisposition
    ) {
        guard let stage,
              session.pendingHandoff.stage == stage,
              session.pendingHandoff.payloadID == stage.payloadID
        else { return }
        switch disposition {
        case .sent:
            session.pendingHandoff.clearAfterSend()
            session.isDirty = true
            scheduleSave(for: session.tabID)
        case .notSent:
            guard session.pendingHandoff.deliveryHold?.isRecoveryHold != true else { return }
            session.pendingHandoff.stage = nil
            session.pendingHandoff.deliveryHold = nil
            session.pendingHandoff.isStagedForSend = false
        case .deliveryUnknown:
            if session.pendingHandoff.deliveryHold == nil {
                session.pendingHandoff.deliveryHold = .deliveryUnknown
            }
        }
    }

    @MainActor
    private func expandSlashSkillInvocationIfNeeded(
        _ text: String,
        agentKind: AgentProviderKind? = nil
    ) async -> String {
        guard !text.isEmpty else { return text }
        await refreshSkillCatalog(force: false, agentKind: agentKind)
        var invocations = resolvedSlashSkillInvocations(in: text)

        // Defensive fallback: if slash-skill tokens were detected syntactically but none
        // resolved (e.g. a skill was just installed and we missed the dirty signal),
        // force-refresh once and retry resolution.
        if invocations.isEmpty {
            let syntacticTokens = Self.extractSlashSkillTokens(from: text)
            if !syntacticTokens.isEmpty {
                await refreshSkillCatalog(force: true, agentKind: agentKind)
                invocations = resolvedSlashSkillInvocations(in: text)
            }
        }

        guard invocations.count == 1, let invocation = invocations.first else {
            return text
        }
        guard let renderedBody = renderSlashSkillBody(for: invocation, sourceText: text) else {
            return text
        }
        return composeSlashSkillPromptBlock(
            definition: invocation.definition,
            renderedBody: renderedBody
        )
    }

    private func renderSlashSkillBody(
        for invocation: ResolvedSlashSkillInvocation,
        sourceText: String
    ) -> String? {
        let template = AgentWorkflowDefinition.stripYAMLFrontmatter(invocation.definition.template)
        let trimmedTemplate = template.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedTemplate.isEmpty else {
            return nil
        }

        let fullText = sourceText as NSString
        let argsText = fullText.substring(with: invocation.token.argumentsRange)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let renderedUserInstructions = renderSlashSkillUserInstructions(argsText)
        if trimmedTemplate.contains("$ARGUMENTS") {
            return trimmedTemplate.replacingOccurrences(of: "$ARGUMENTS", with: renderedUserInstructions)
        }
        guard !renderedUserInstructions.isEmpty else {
            return trimmedTemplate
        }
        return "\(trimmedTemplate)\n\n\(renderedUserInstructions)"
    }

    private func renderSlashSkillUserInstructions(_ argsText: String) -> String {
        let trimmedArgs = argsText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedArgs.isEmpty else {
            return ""
        }
        return """
        <user_instructions>
        \(trimmedArgs)
        </user_instructions>
        """
    }

    private func composeSlashSkillPromptBlock(
        definition: AgentSkillDefinition,
        renderedBody: String
    ) -> String {
        let promptContext = skillCatalog.promptContext(for: definition)
        let escapedName = Self.escapePromptXMLAttribute(definition.name)
        let escapedScope = Self.escapePromptXMLAttribute(promptContext.scopeLabel)
        let escapedSource = Self.escapePromptXMLAttribute(promptContext.sourceLabel)

        var sections = [
            """
            <selected_skill_context name="\(escapedName)" scope="\(escapedScope)" source="\(escapedSource)">
            The selected /\(definition.name) skill content is already included below.
            Treat any <user_instructions> block as the user's live instructions for this skill invocation.
            Do not re-read the skill file unless the user explicitly asks you to inspect or modify the skill itself.
            </selected_skill_context>
            """
        ]

        if let directoryTree = promptContext.directoryTree?.trimmingCharacters(in: .whitespacesAndNewlines), !directoryTree.isEmpty {
            sections.append(
                """
                <skill_directory_tree>
                \(directoryTree)
                </skill_directory_tree>
                """
            )
        }

        sections.append(renderedBody)
        return sections.joined(separator: "\n\n")
    }

    private static func escapePromptXMLAttribute(_ text: String) -> String {
        text
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
    }

    @MainActor
    private func augmentUserMessageWithTaggedFileContents(
        _ text: String,
        taggedFileAttachments: [AgentTaggedFileAttachment] = [],
        lookupContext: WorkspaceLookupContext = .visibleWorkspace
    ) async -> String {
        guard !text.contains("<file_contents>") else { return text }
        var orderedPaths: [String] = []
        var seen = Set<String>()
        for taggedPath in Self.extractTaggedPaths(from: text) {
            let normalized = Self.unescapeTaggedPath(taggedPath)
            guard !normalized.isEmpty else { continue }
            if seen.insert(normalized).inserted {
                orderedPaths.append(normalized)
            }
        }
        for attachment in taggedFileAttachments {
            let normalized = Self.unescapeTaggedPath(attachment.relativePath)
            guard !normalized.isEmpty else { continue }
            if seen.insert(normalized).inserted {
                orderedPaths.append(normalized)
            }
        }
        guard !orderedPaths.isEmpty else { return text }
        guard let xml = await fileContentsXMLForTaggedPaths(
            orderedPaths,
            tokenBudget: Self.taggedFileContentsTokenBudget,
            maxFiles: Self.taggedFileContentsMaxFiles,
            lookupContext: lookupContext
        ) else {
            return text
        }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return xml }
        return "\(text)\n\n\(xml)"
    }

    // MARK: - Agent Run Lifecycle

    /// Start an agent run for the given tab.
    ///
    /// `providerHandoffAuthorization` is consulted by the run service immediately before the
    /// provider runner is invoked (after the Codex dispatch ticket, message augmentation, and
    /// workspace resolution). A `false` answer aborts before any provider work with
    /// `.stale(reason: AgentModeRunService.providerHandoffRevokedReason)`.
    ///
    /// `inputConstituents` are the immutable identities captured when this input was admitted, in
    /// order. `nil` is the legacy untracked input of inactive recovery admission; when the session
    /// requires durable admission it fails closed (`.stale`, nothing handed off) instead.
    ///
    /// `holdsPrefixBlockedInput` (B R1-1): for callers that do not re-queue on failure, a start
    /// refused because its pending-handoff prefix could not be saved shows the carried durable input
    /// as held. Callers that re-queue a not-handed-off start leave it `false` (never both).
    @discardableResult
    func startAgentRun(
        tabID: UUID,
        initialMessage: String,
        attachments: [AgentImageAttachment] = [],
        taggedFileAttachments: [AgentTaggedFileAttachment] = [],
        inputConstituents: [AgentQueuedInputIdentity]?,
        codexFallbackContext: AgentTabSession.CodexFallbackSubmissionContext? = nil,
        providerHandoffAuthorization: (@MainActor () -> Bool)? = nil,
        holdsPrefixBlockedInput: Bool = false
    ) async -> CodexAgentModeCoordinator.NativeSendOutcome? {
        guard let session = session(for: tabID, createIfNeeded: true) else {
            return .failed(message: Self.composeTabRemovalInProgressMessage)
        }
        let codexDispatchTicket = codexFallbackContext?.dispatchTicket
        if let codexDispatchTicket {
            guard await session.codexDispatchSerialGate.awaitTurn(codexDispatchTicket) else {
                return .cancelled
            }
        }
        defer {
            if let codexDispatchTicket {
                session.codexDispatchSerialGate.finish(codexDispatchTicket)
            }
        }
        if let blockedMessage = newWorkBlockedMessage(for: session) {
            // Backend admission: no provider work against a retained, unsavable conversation or an
            // owner reserved by an in-flight removal operation.
            if session.mcpFollowUpRunPending {
                session.mcpFollowUpRunPending = false
                handleObservedMCPStateChange(for: session)
            }
            return .failed(message: blockedMessage)
        }
        guard AgentModelCatalog.isAgentAvailable(session.selectedAgent, availability: agentAvailabilityContext) else {
            if session.mcpFollowUpRunPending {
                session.mcpFollowUpRunPending = false
                handleObservedMCPStateChange(for: session)
            }
            return .failed(message: unavailableAgentMessage(for: session.selectedAgent))
        }
        defer {
            if session.mcpFollowUpRunPending {
                session.mcpFollowUpRunPending = false
                handleObservedMCPStateChange(for: session)
            }
        }
        // Codex routes carry their identity in `codexFallbackContext`; every other route needs one
        // (checked after the dispatch-ticket and follow-up defers are installed, and before the tab
        // is bound, the session prepared, or any input text is staged — F1).
        let constituents: [AgentQueuedInputIdentity]
        if let inputConstituents {
            constituents = inputConstituents
        } else if let untracked = AgentQueuedInputIdentity.untracked(userItemID: nil, in: session) {
            constituents = [untracked]
        } else if session.selectedAgent == .codexExec, codexFallbackContext?.identity.isDurable == true {
            constituents = []
        } else {
            return .stale(reason: Self.durableQueueAdmissionRequiredMessage)
        }
        guard ensureSessionBoundToTab(session) != nil else {
            return .failed(message: "The tab could not be bound to an agent session.")
        }
        await prepareSessionForRunStart(tabID: tabID, session: session)
        await prepareMCPWaitTrackingForRunStart(session: session)
        let carriers = constituents.isEmpty ? codexFallbackContext.map { [$0.identity] } ?? [] : constituents
        let augmented = await augmentUserMessageForProviderSend(
            initialMessage,
            attachments: attachments,
            taggedFileAttachments: taggedFileAttachments,
            agent: session.selectedAgent,
            session: session,
            carriers: carriers
        )
        if let blockedReason = augmented.blockedReason {
            // Nothing was dispatched or staged: re-queuing callers keep durable input queued (same
            // intents), exactly as for any other start that provably handed nothing off; the others
            // show it as held.
            if holdsPrefixBlockedInput {
                holdBlockedDurableInput(carriers, session: session, reason: blockedReason)
            }
            return .failed(message: blockedReason)
        }
        let augmentedMessage = augmented.text
        // Exact pending-handoff stage this start's text carries (nil when nothing was prepended).
        let pendingHandoffStage = augmented.pendingHandoffStage
        // Idle parent only (plan §6.2): pending child questions ride on this turn's first input
        // as a labeled runtime block (never the user's text). A busy parent gets them with its
        // next eligible tool result instead, so steer/supersede/queued-fallback inputs never
        // carry them. The runner settles exactly this stage at its actual provider submission.
        let augmentedInitialMessage = session.runState.isActive
            ? augmentedMessage
            : stageDelegatedQuestionNoticesForTurnInput(augmentedMessage, session: session)
        let delegatedQuestionStageID = augmentedInitialMessage == augmentedMessage
            ? nil
            : delegatedQuestionTurnStageID(forTabID: tabID)

        let initialMessageForRun = await buildInitialThreadMessageIfNeeded(
            tabID: tabID,
            session: session,
            initialMessage: augmentedInitialMessage
        )
        let preparedCodexFallbackContext = codexFallbackContext.map { context in
            AgentTabSession.CodexFallbackSubmissionContext(
                queueID: context.queueID,
                providerText: initialMessageForRun,
                images: context.images,
                taggedFileAttachments: context.taggedFileAttachments,
                draftText: context.draftText,
                identity: context.identity,
                origin: context.origin,
                dispatchTicket: context.dispatchTicket
            )
        }

        let startOutcome = await runService.startRun(
            tabID: tabID,
            session: session,
            // The notice-free text keeps the runners' "run text differs" token re-estimate honest.
            initialUserMessage: augmentedMessage,
            initialMessageForRun: initialMessageForRun,
            attachments: attachments,
            inputConstituents: constituents,
            codexFallbackContext: preparedCodexFallbackContext,
            providerHandoffAuthorization: providerHandoffAuthorization,
            delegatedQuestionStageID: delegatedQuestionStageID,
            pendingHandoffStage: pendingHandoffStage
        )
        // Start-tail settlement of stages the provider outcome did not already resolve: a start that
        // provably handed nothing off releases them; uncertainty holds them; an admitted runner
        // still owes its outcome (an inactive run alone is not proof of non-handoff).
        let startDisposition = Self.stagedInputStartDisposition(for: startOutcome)
        if let startDisposition {
            recordPendingHandoffStageOutcome(for: session, stage: pendingHandoffStage, disposition: startDisposition)
        }
        settleDelegatedQuestionTurnStageAfterRunStart(
            delegatedQuestionStageID,
            session: session,
            startDisposition: startDisposition
        )
        return startOutcome
    }

    private static func headlessContinuityDecision(
        agent: AgentProviderKind,
        providerSessionID: String?,
        hasAttachments: Bool,
        hasPendingHandoff: Bool
    ) -> (shouldBypassHistoryReplay: Bool, resumeSessionID: String?) {
        let normalizedProviderSessionID = providerSessionID
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .flatMap { $0.isEmpty ? nil : $0 }
        let supportsSessionResume = agent.usesClaudeNativeRuntime
            || agent.acpProviderID != nil
        let keepsAttachmentsAtTopLevel = agent.usesClaudeNativeRuntime || agent.acpProviderID != nil
        let shouldBypassHistoryReplay = hasPendingHandoff
            || (supportsSessionResume && normalizedProviderSessionID != nil)
            || (keepsAttachmentsAtTopLevel && hasAttachments)
        return (
            shouldBypassHistoryReplay,
            shouldBypassHistoryReplay && supportsSessionResume ? normalizedProviderSessionID : nil
        )
    }

