    /// Clear the chat transcript for the current tab
    func clearChat() {
        guard let tabID = currentTabID else { return }
        clearChat(tabID: tabID)
    }

    /// Clear the chat transcript for a specific tab
    func clearChat(tabID: UUID) {
        guard let session = sessions[tabID] else { return }
        // A retained stale-reset view is replaced only by its confirmed reload, never reset here.
        guard !staleResetRecoveryBlocksNewWork(session) else { return }
        guard recoveryCoordinator != nil else {
            performClearChat(session, tabID: tabID, committedRecoveryReset: false)
            return
        }
        Task { [weak self] in
            _ = await self?.clearChatPreservingRecovery(tabID: tabID)
        }
    }

    /// Result of a recovery-composed transcript reset (`clearChatPreservingRecovery`).
    enum RecoveryTranscriptResetOutcome: Equatable {
        /// The reset receipt committed durably, then the live session was cleared.
        case committed
        /// No durable session exists yet: cleared locally exactly as without recovery.
        case clearedUnsaved
        /// Nothing was cleared and the generation did not advance; the old state stays usable.
        case vetoed(String)
    }

    /// Lossless-restart reset ordering (spec R2). Preserves the old generation's composer (or
    /// vetoes), joins the in-flight session writer and then holds the writer slot itself, commits
    /// the reset receipt through the existing foundation save from a cleared candidate built by
    /// the normal snapshot builder, and only after that commit clears live and provider state.
    /// Admission stays frozen until the commit retires the old lane; on failure nothing was cleared
    /// and the freeze is released (the generation did not advance).
    func clearChatPreservingRecovery(tabID: UUID) async -> RecoveryTranscriptResetOutcome {
        guard let session = sessions[tabID] else { return .vetoed("the tab is gone") }
        guard !staleResetRecoveryBlocksNewWork(session) else { return .vetoed("stale reset recovery is pending") }
        if let failure = await prepareRecoveryTranscriptReset(for: session) {
            print("[AgentModeVM][Recovery] transcript reset vetoed to preserve composer input: \(failure)")
            return .vetoed(String(describing: failure))
        }
        let preparedLane = session.recoveryLane
        func veto(_ reason: String) -> RecoveryTranscriptResetOutcome {
            endRecoveryTranscriptResetPreparation(for: session, lane: preparedLane)
            print("[AgentModeVM][Recovery] transcript reset not committed: \(reason)")
            return .vetoed(reason)
        }
        guard sessions[tabID] === session, !staleResetRecoveryBlocksNewWork(session) else {
            return veto("the owner changed during preparation")
        }
        guard let sessionID = session.activeAgentSessionID, session.persistenceState(for: sessionID) != nil else {
            guard preparedLane == nil, session.persistenceState == nil else {
                return veto("the session has durable state but no current authority")
            }
            performClearChat(session, tabID: tabID, committedRecoveryReset: false)
            return .clearedUnsaved
        }
        guard let preparedLane, !preparedLane.isRetired else {
            return veto("no recovery lane owns the session")
        }
        // Join the in-flight writer (never a queued/coalesced return), then own the writer slot so
        // no snapshot of the old transcript can be written around the reset commit.
        while saveInFlightSessionIDs.contains(sessionID) {
            await withCheckedContinuation { saveCompletionWaiters[sessionID, default: []].append($0) }
        }
        guard sessions[tabID] === session,
              session.activeAgentSessionID == sessionID,
              session.recoveryLane === preparedLane,
              !preparedLane.isRetired,
              !staleResetRecoveryBlocksNewWork(session),
              let state = session.persistenceState(for: sessionID),
              let context = currentSessionPersistenceContext(),
              sessionPersistenceContextIsCurrent(context),
              state.stamp.workspaceID == context.workspace.id
        else {
            return veto("the owner or persistence context changed while joining the session writer")
        }
        saveInFlightSessionIDs.insert(sessionID)
        defer {
            saveInFlightSessionIDs.remove(sessionID)
            for waiter in saveCompletionWaiters.removeValue(forKey: sessionID) ?? [] {
                waiter.resume()
            }
            if saveRequestedWhileInFlightSessionIDs.remove(sessionID) != nil, sessions[tabID] === session {
                scheduleSave(for: tabID)
            }
        }
        let receipt = session.pendingTranscriptResetReceipt ?? AgentSessionTranscriptResetReceipt(id: UUID())
        let removals = session.pendingFinalizedScheduledSendItemRemovals + session.finalizedScheduledSendItemMarkers
        var candidate = makePersistedAgentSession(
            for: session,
            tabID: tabID,
            sessionID: sessionID,
            workspaceID: context.workspace.id,
            sessionName: resolvedSessionDisplayName(for: tabID),
            persistableSnapshot: PersistableTranscriptSnapshot(
                transcript: .empty,
                projectionCounts: AgentTranscriptProjectionCounts(),
                canonicalVisibleRowCount: 0,
                lastUserMessageAt: nil
            )
        )
        // The candidate mirrors exactly what `performClearChat` clears.
        candidate.uiToolResultPayloadsByItemID = [:]
        candidate.remoteResendPayloadsByItemID = [:]
        candidate.locallyAttributedStartItemID = nil
        candidate.providerSessionID = nil
        candidate.providerHistoryRecovery = nil
        candidate.providerTokenUsageByTurn = []
        candidate.codexConversationID = nil
        candidate.codexRolloutPath = nil
        candidate.codexModel = nil
        candidate.codexReasoningEffort = nil
        candidate.codexContextWindow = nil
        candidate.codexLastTotalTokens = nil
        candidate.codexTotalTotalTokens = nil
        let commit: AgentSessionSaveCommit
        do {
            #if DEBUG
                if let hook = test_recoveryResetBeforeCommitHook {
                    await hook(session)
                }
            #endif
            commit = try await dataService.saveAgentSession(
                candidate,
                for: context.workspace,
                preparation: .alreadyCanonicalTranscript,
                trustedCanonicalItemCount: 0,
                intentionallyRemovingFinalizedScheduledSendItems: removals,
                committingTranscriptReset: receipt,
                fileCreationPolicy: .requireExisting,
                persistenceState: state
            )
        } catch AgentScheduledSendMutationError.staleDeletionGeneration,
            AgentScheduledSendMutationError.invalidPersistenceStamp,
            AgentScheduledSendMutationError.sessionDeleted,
            AgentScheduledSendMutationError.staleIncarnation
        {
            if sessions[tabID] === session {
                handleDurableSessionDeleted(session, sessionID: sessionID)
            }
            return veto("the session was deleted")
        } catch {
            // Nothing was cleared and the generation did not advance (a commit that raced this
            // failure is idempotent under the same receipt and rejects stale old-generation writes).
            return veto("the reset commit failed: \(error)")
        }
        guard sessions[tabID] === session, session.activeAgentSessionID == sessionID else {
            // Committed for a replaced owner: its own reload adopts the reset; nothing is cleared here.
            return veto("the owner changed during the reset commit")
        }
        session.persistenceState = commit.persistenceState
        session.persistedIncarnationSessionID = sessionID
        session.pendingTranscriptResetReceipt = nil
        session.pendingFinalizedScheduledSendItemRemovals.removeAll { removals.contains($0) }
        // The successor claim retires the frozen lane (binding changed: nothing is written under
        // either generation; the preserved composer is held by the new one).
        recoveryPersistenceStateDidChange(for: session)
        performClearChat(session, tabID: tabID, committedRecoveryReset: true)
        return .committed
    }

    private func performClearChat(_ session: AgentTabSession, tabID: UUID, committedRecoveryReset: Bool) {
        if !committedRecoveryReset {
            // An explicit reset intentionally removes finalized scheduled markers; the next save
            // must carry their exact identities so persistence tombstones them instead of
            // protecting them against what would otherwise look like a stale snapshot.
            session.pendingFinalizedScheduledSendItemRemovals.append(
                contentsOf: session.finalizedScheduledSendItemMarkers
            )
            // Each explicit reset carries its own stable receipt until the save that commits it; a
            // save retried for the same reset reuses it.
            session.pendingTranscriptResetReceipt = AgentSessionTranscriptResetReceipt(id: UUID())
        }
        session.setItemsSilently([], reason: .clearedChat)
        session.clearDerivedTranscriptCaches()
        if committedRecoveryReset {
            // The preserved old-generation composer stays exactly as written (held after the
            // reset); the cleared attachments are not reported as an old-generation edit.
            session.withRecoveryComposerObservationSuppressed {
                session.pendingImageAttachments.removeAll()
                session.pendingTaggedFileAttachments.removeAll()
            }
        } else {
            session.pendingImageAttachments.removeAll()
            session.pendingTaggedFileAttachments.removeAll()
        }
        session.attachmentsPendingProviderConsumptionCleanup.removeAll()
        session.nextSequenceIndex = 0
        session.attentionTextProvenance = nil
        discardAttentionDeferredCompletion(for: session)
        session.lastActivityAt = Date()
        session.lastUserMessageAt = nil
        session.isDirty = true
        invalidateSidebarRestoreOrdering()
        sessionIndexStore.removeSortDate(forTabID: tabID)

        // Detach before clearing the provider session ID so async cleanup cannot
        // restore the old conversation or affect a replacement controller.
        claudeCoordinator.prepareForConversationResetSync(session)
        session.providerSessionID = nil
        // The history ledger belongs to the cleared transcript (reset semantics only).
        session.providerHistoryRecovery = nil
        session.recoveryResumeFallbackSuppressedConversationID = nil
        session.recoveryResumeUnavailableConversationID = nil
        session.pendingHistoryImportCommit = nil
        session.committedHistoryImportID = nil
        session.providerTokenUsageByTurn.removeAll()
        session.claudeConfiguredContextWindow = nil
        session.claudeConfiguredContextWindowKey = nil
        session.pendingNonCodexUserInputTokenQueue.removeAll()
        session.activeNonCodexTurnTokenAccumulator = nil
        session.contextUsageSnapshot = nil
        session.contextCompactedAt = nil
        session.activeReasoningItemID = nil
        session.reasoningItemIDsByGroupID.removeAll()
        session.backgroundRowIDs.removeAll()
        session.backgroundRowSourceIDs.removeAll()
        session.backgroundCurrentAssistantRowIDs.removeAll()
        session.clearClaudeReasoningStatus(clearDisplayedStatus: true)
        session.setRunningStatus(nil, source: nil)
        session.codexReasoningSegmentsByKey.removeAll()
        session.pendingTurnRuntimeAnchors.removeAll()
        session.agentMessageRuntimeFootersByItemID.removeAll()

        // Clear Codex-native identifiers and usage
        codexCoordinator.clearCodexSessionState(session)

        applyTranscriptViewportBindingState(
            to: session,
            viewportState: .liveBottom,
            armingState: .armed
        )
        if tabID == currentTabID {
            updateBindingsFromSession(session)
        }
        scheduleSave(for: tabID)
    }

    /// Rename the visible agent session for a tab.
    ///
    /// Agent-mode sidebar rows are session-first, but the user-facing title is also
    /// mirrored through the compose tab so window/tab UI and persisted workspace
    /// state stay in sync.
    func renameSession(tabID: UUID, to newName: String) {
        let validatedName = AgentSession.validatedName(newName)
        guard !validatedName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }

        promptManager?.renameComposeTab(tabID, to: validatedName)

        let sessionID = boundSessionID(for: tabID)
        if let sessionID,
           var entry = ownerValidatedSessionIndex[sessionID]
        {
            entry.name = validatedName
            applyLocalSessionIndexUpsert(entry)
        }

        if let session = sessions[tabID] {
            if session.activeAgentSessionID == nil, let sessionID {
                _ = installPersistentSessionBinding(
                    sessionID: sessionID,
                    on: session,
                    updateWorkspaceMetadata: true,
                    invalidateAsyncWork: true
                )
            }
            session.isDirty = true
            scheduleSave(for: tabID)
            handleObservedMCPStateChange(for: session)
            codexCoordinator.scheduleCodexThreadNameSyncIfPossible(
                for: session,
                name: validatedName,
                explicitThreadID: session.codexConversationID,
                source: "renameSession"
            )
        } else if let sessionID,
                  let workspace = workspaceManager?.activeWorkspace ?? lastKnownWorkspaceSnapshot
        {
            Task { [dataService] in
                try? await dataService.renameAgentSession(
                    id: sessionID,
                    to: validatedName,
                    for: workspace
                )
            }
        }
    }

    private func cleanupACPStateForDeletedSession(_ session: AgentTabSession) async {
        await session.teardownACPControllerIfPresent()
    }

    struct DeletedAgentSessionCleanupResult: Equatable {
        let affectedTabIDs: Set<UUID>
        let clearedComposeTabIDs: Set<UUID>
        let clearedStashedTabIDs: Set<UUID>
    }

    @discardableResult
    func finalizeDeletedAgentSessionReferences(
        sessionID: UUID,
        workspaceID: UUID?,
        knownTabIDs: Set<UUID> = [],
        reason: String
    ) async -> DeletedAgentSessionCleanupResult {
        #if DEBUG
            let finalizeStartMS = AgentModePerfDiagnostics.timestampMSIfEnabled()
        #endif
        let cleanupRegistration = await AgentRunSessionStore.currentRegistration(for: sessionID)
        var affectedTabIDs = knownTabIDs
        if let indexedTabID = ownerValidatedSessionIndex[sessionID]?.tabID {
            affectedTabIDs.insert(indexedTabID)
        }

        let liveTabIDs = Set(sessions.values.compactMap { session -> UUID? in
            session.activeAgentSessionID == sessionID ? session.tabID : nil
        })
        let stateCleanupTabIDs = knownTabIDs.union(liveTabIDs)
        affectedTabIDs.formUnion(liveTabIDs)

        var clearedComposeTabIDs = Set<UUID>()
        var clearedStashedTabIDs = Set<UUID>()
        if let workspaceManager {
            for workspace in workspaceManager.workspaces where workspaceID == nil || workspace.id == workspaceID {
                for tab in workspace.composeTabs where tab.activeAgentSessionID == sessionID {
                    if workspaceManager.compareAndSetActiveAgentSessionID(
                        expected: sessionID,
                        replacement: nil,
                        forTabID: tab.id,
                        inWorkspaceID: workspace.id
                    ) {
                        clearedComposeTabIDs.insert(tab.id)
                        affectedTabIDs.insert(tab.id)
                    }
                }
                for stashed in workspace.stashedTabs where stashed.tab.activeAgentSessionID == sessionID {
                    if workspaceManager.compareAndSetActiveAgentSessionID(
                        expected: sessionID,
                        replacement: nil,
                        forTabID: stashed.tab.id,
                        inWorkspaceID: workspace.id
                    ) {
                        clearedStashedTabIDs.insert(stashed.tab.id)
                        affectedTabIDs.insert(stashed.tab.id)
                    }
                }
            }
        }
        if var snapshot = lastKnownWorkspaceSnapshot,
           workspaceID == nil || snapshot.id == workspaceID
        {
            var didChangeSnapshot = false
            for tabIndex in snapshot.composeTabs.indices where snapshot.composeTabs[tabIndex].activeAgentSessionID == sessionID {
                affectedTabIDs.insert(snapshot.composeTabs[tabIndex].id)
                snapshot.composeTabs[tabIndex].activeAgentSessionID = nil
                didChangeSnapshot = true
            }
            for stashedIndex in snapshot.stashedTabs.indices where snapshot.stashedTabs[stashedIndex].tab.activeAgentSessionID == sessionID {
                affectedTabIDs.insert(snapshot.stashedTabs[stashedIndex].tab.id)
                snapshot.stashedTabs[stashedIndex].tab.activeAgentSessionID = nil
                didChangeSnapshot = true
            }
            if didChangeSnapshot {
                lastKnownWorkspaceSnapshot = snapshot
            }
        }

        // Retire synchronously (no suspension since the binding scan above): every live owner
        // still bound to the deleted UUID is detached from its tab together with all tab-scoped
        // state, before any await. A tab hosting another owner is never touched, and an owner
        // installed on the tab while the teardown below is suspended is never targeted by it.
        var detachedOwners: [(session: AgentTabSession, runID: UUID?)] = []
        for tabID in stateCleanupTabIDs {
            let owner = sessions[tabID].flatMap { $0.activeAgentSessionID == sessionID ? $0 : nil }
            guard owner != nil || sessions[tabID] == nil else { continue }
            removePendingUIRefresh(for: tabID)
            if activeSessionLoadInProgressTabID == tabID {
                activeSessionLoadInProgressTabID = nil
            }
            sessionIndexStore.removeSortDate(forTabID: tabID)
            tabsWithActiveAgentRun.remove(tabID)
            mcpControlledTabIDs.remove(tabID)
            guard let session = owner else { continue }
            detachedOwners.append((session, session.runID))
            cancelPersistedLoad(for: session)
            session.cancelEphemeralRuntimeState()
            cancelPendingQuestion(for: session)
            cancelPendingApproval(for: session)
            cancelPendingApplyEditsReview(for: session, reason: "Session deleted")
            cancelPendingInstruction(for: session)
            clearRemoteStartWindowPickerIfOwned(by: tabID)
            remoteCoordinator.stop(tabID: tabID)
            sessions.removeValue(forKey: tabID)
        }
        // Tab owners as of the detach: a later owner of an affected tab is a replacement.
        let ownersAfterDetach = Dictionary(uniqueKeysWithValues: affectedTabIDs.map { tabID in
            (tabID, sessions[tabID].map(ObjectIdentifier.init))
        })
        // Awaited teardown of the detached objects only, using the detached-owner pattern
        // (workspace-switch discard): no tab-scoped publication, and coordinator tab state is
        // released only when it still belongs to the captured run.
        for (session, runID) in detachedOwners {
            #if DEBUG
                if let hook = test_deletedSessionTeardownHook {
                    await hook(session)
                }
            #endif
            await teardownApplyEditsApprovalSessionSync(for: session, cleanupScope: true)
            await cleanupACPStateForDeletedSession(session)
            await teardownMCPControl(for: session, cleanupSessionStore: true, publishChanges: false)
            await session.disposeProviderIfPresent()
            await codexCoordinator.shutdownCodexSession(
                session,
                clearTabScopedCoordinatorState: false,
                detachedRunID: runID
            )
            await claudeCoordinator.shutdownClaudeSession(
                session,
                clearTabScopedCoordinatorState: false,
                detachedRunID: runID
            )
            await cleanupMCPRunRoutingIfPresent(
                boundSessionID: sessionID,
                liveSession: session,
                explicitRunID: runID,
                reason: reason
            )
        }

        await releaseSessionWorktreeOwnership(sessionID: sessionID)
        removeSessionIndex(sessionID: sessionID)
        if let cleanupRegistration {
            await AgentRunSessionStore.cleanup(registration: cleanupRegistration)
        }

        for tabID in clearedComposeTabIDs.union(clearedStashedTabIDs) {
            postAgentSessionBindingDidChange(
                tabID: tabID,
                previousSessionID: sessionID,
                sessionID: nil
            )
        }

        let activeTabID = currentTabID
        if let activeTabID, affectedTabIDs.contains(activeTabID) {
            // A replacement installed during the teardown already owns and presents the tab.
            if sessions[activeTabID].map(ObjectIdentifier.init) == ownersAfterDetach[activeTabID] ?? nil {
                lastProcessedTabID = nil
                onTabChanged(activeTabID)
            }
        } else if activeTabID == nil, !affectedTabIDs.isEmpty {
            lastProcessedTabID = nil
            onTabChanged(nil)
        }
        syncSidebarUIState(refresh: true, reason: .sessionIndex)

        let result = DeletedAgentSessionCleanupResult(
            affectedTabIDs: affectedTabIDs,
            clearedComposeTabIDs: clearedComposeTabIDs,
            clearedStashedTabIDs: clearedStashedTabIDs
        )
        #if DEBUG
            AgentModePerfDiagnostics.durationEvent(
                "cleanup.vm.finalizeDeletedReferences",
                startMS: finalizeStartMS,
                fields: [
                    "sessionID": sessionID.uuidString,
                    "affectedTabCount": String(result.affectedTabIDs.count),
                    "clearedComposeCount": String(result.clearedComposeTabIDs.count),
                    "clearedStashedCount": String(result.clearedStashedTabIDs.count)
                ]
            )
        #endif
        return result
    }

    /// Delete a session completely (clear chat and close tab)
    func deleteSession(tabID: UUID) async {
        #if DEBUG
            let deleteSessionStartMS = AgentModePerfDiagnostics.timestampMSIfEnabled()
        #endif
        let sessionID = boundSessionID(for: tabID)
        let liveSession = sessions[tabID]
        let wasCurrentTab = currentTabID == tabID
        if wasCurrentTab {
            lastProcessedTabID = nil
        }
        if let session = liveSession {
            releaseScheduledSendForRemovedSession(session, deletesPersistedSession: true)
            removePendingUIRefresh(for: tabID)
            cancelPersistedLoad(for: session)
            session.cancelEphemeralRuntimeState()
            cancelPendingQuestion(for: session)
            cancelPendingApproval(for: session)
            cancelPendingApplyEditsReview(for: session, reason: "Session deleted")
            await teardownApplyEditsApprovalSessionSync(for: session, cleanupScope: true)
            cancelPendingInstruction(for: session)
            await cleanupACPStateForDeletedSession(session)
            await teardownMCPControl(for: session, cleanupSessionStore: true)
            await session.disposeProviderIfPresent()
            await codexCoordinator.shutdownCodexSession(session)
            await claudeCoordinator.shutdownClaudeSession(session)
        }
        await cleanupMCPRunRoutingIfPresent(
            boundSessionID: sessionID,
            liveSession: liveSession,
            reason: "session_delete"
        )
        let workspaceID = workspaceManager?.activeWorkspace?.id
        if let workspace = workspaceManager?.activeWorkspace,
           let sessionID
        {
            try? await dataService.deleteAgentSession(id: sessionID, for: workspace)
            removeSessionIndex(sessionID: sessionID)
        } else {
            removeSessionIndex(forTabID: tabID)
        }
        tabDraftText.removeValue(forKey: tabID)
        clearRemoteStartWindowPickerIfOwned(by: tabID)
        remoteCoordinator.stop(tabID: tabID)
        sessions.removeValue(forKey: tabID)
        tabsWithActiveAgentRun.remove(tabID)
        mcpControlledTabIDs.remove(tabID)
        sessionIndexStore.removeSortDate(forTabID: tabID)
        removePendingUIRefresh(for: tabID)
        if let sessionID {
            scheduledSendCoordinator?.tabDidClose(sessionID: sessionID)
        }
        await promptManager?.closeComposeTab(tabID)
        if let sessionID {
            await finalizeDeletedAgentSessionReferences(
                sessionID: sessionID,
                workspaceID: workspaceID,
                knownTabIDs: [tabID],
                reason: "session_delete"
            )
        } else {
            syncSidebarUIState(refresh: true, reason: .sessionIndex)
        }
        #if DEBUG
            AgentModePerfDiagnostics.durationEvent(
                "cleanup.vm.deleteSession",
                startMS: deleteSessionStartMS,
                tabID: tabID,
                fields: [
                    "tabID": tabID.uuidString,
                    "sessionID": sessionID?.uuidString ?? "nil"
                ]
            )
        #endif
    }

    /// Last activity timestamp for sorting tabs in the UI
    func lastActivityDate(for tabID: UUID) -> Date {
        if let session = sessions[tabID] {
            return session.lastActivityAt
        }
        if let tab = promptManager?.currentComposeTabs.first(where: { $0.id == tabID }) {
            return tab.lastModified
        }
        return .distantPast
    }

    /// Last user message timestamp for sorting tabs (user messages and question responses count)
    func lastUserMessageDate(for tabID: UUID) -> Date? {
        if let session = sessions[tabID] {
            if let cached = session.lastUserMessageAt {
                return cached
            }
            if let computed = computeLastUserMessageDate(in: session.items) {
                return computed
            }
            return sessionListSortDate(for: tabID)
        }
        return sessionListSortDate(for: tabID)
    }

    /// Check if a tab has an agent session (in memory or persisted on disk)
    func hasAgentSession(for tabID: UUID) -> Bool {
        // Check in-memory sessions first (O(1) dictionary lookup)
        if sessions[tabID] != nil {
            return true
        }
        // Check cached metadata from disk (includes sessions without user messages)
        if ownerValidatedSessionIndex.values.contains(where: { $0.tabID == tabID }) {
            return true
        }
        // Check if tab has a persisted agent session ID via workspaceManager
        if let tabState = workspaceManager?.composeTab(with: tabID),
           tabState.activeAgentSessionID != nil
        {
            return true
        }
        return false
    }

    func hasLinkedAgentSession(for tabID: UUID?) -> Bool {
        guard let tabID else { return false }
        return explicitActiveSessionID(for: tabID) != nil
    }

    /// Returns true when a new-session click should be ignored because the current tab is
    /// still an untouched placeholder for the requested profile.
    func shouldSwallowNewSessionClick(
        for tabID: UUID?,
        requestedProfile: AgentSessionProfile = .standard
    ) -> Bool {
        guard let tabID,
              sessions[tabID]?.profile == requestedProfile
        else {
            return false
        }
        return isUntouchedSessionPlaceholder(for: tabID)
    }

    private func isUntouchedSessionPlaceholder(for tabID: UUID?) -> Bool {
        guard let tabID,
              hasLinkedAgentSession(for: tabID),
              let session = sessions[tabID]
        else {
            return false
        }

        // If this tab points at a persisted session that has not finished loading,
        // treat it as unknown instead of empty to avoid false positives.
        if session.activeAgentSessionID != nil && !session.hasLoadedPersistedState {
            return false
        }

        let hasTranscript = !session.transcript.turns.isEmpty || !session.items.isEmpty
        let hasDraft = !session.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let hasPendingAttachments = !session.pendingImageAttachments.isEmpty || !session.pendingTaggedFileAttachments.isEmpty
        let hasPendingInteraction = session.runState == .waitingForUser
            || session.hasPendingQuestionUI
            || session.pendingApproval != nil
            || session.pendingPermissionsRequest != nil
            || session.pendingApplyEditsReview != nil
        let hasActiveRun = session.runState.isActive
        // A pending scheduled message is conversation content: the placeholder must not be
        // reused or closed out from under it.
        let hasScheduledSend = session.scheduledSend != nil

        return !(hasTranscript || hasDraft || hasPendingAttachments || hasPendingInteraction || hasActiveRun || hasScheduledSend)
    }

    /// Ensure a session exists for a tab (creates one if needed)
    func ensureSession(for tabID: UUID) {
        guard let session = session(for: tabID, createIfNeeded: true) else { return }
        _ = ensureSessionBoundToTab(session)
    }

    var canCreateKnowledgeSession: Bool {
        !availableAgents.filter(KnowledgeSessionPolicy.supportedProviders.contains).isEmpty
    }

    /// Create a brand new session by creating a tab that is already linked to an agent session.
    /// Profiles are chosen before provider construction and remain immutable for the tab's lifetime.
    @discardableResult
    func createAndActivateSessionTab(
        profile requestedProfile: AgentSessionProfile = .standard,
        focusComposer: Bool = false
    ) async -> UUID? {
        guard let promptManager else { return nil }

        let knowledgeAgents = availableAgents.filter(KnowledgeSessionPolicy.supportedProviders.contains)
        guard requestedProfile != .knowledge || !knowledgeAgents.isEmpty else { return nil }

        let priorTabID = currentTabID
        if shouldSwallowNewSessionClick(
            for: priorTabID,
            requestedProfile: requestedProfile
        ) {
            if focusComposer, let priorTabID {
                ui.composer.requestFocus(
                    AgentComposerFocusRequest(
                        id: UUID(),
                        tabID: priorTabID,
                        reason: .reusedPlaceholder
                    )
                )
            }
            return priorTabID
        }
        let shouldClosePriorPlaceholder = isUntouchedSessionPlaceholder(for: priorTabID)
        let originatingWorkspaceID = persistenceWorkspace?.id
        let originatingOwner = sessionIndexOwner
        let selection = FreshSessionSelection(
            agent: selectedAgent,
            modelRaw: selectedModelRaw,
            reasoningEffortRaw: selectedReasoningEffortRaw
        )
        var preparedSession: AgentTabSession?

        // Only interactive creation may continue once an eligible inactive auto-stash has
        // committed; its owned cleanup finishes independently. The fresh session is prepared
        // before the new tab activates, so activation presents it directly.
        guard let tabID = await promptManager.createFreshAgentComposeTab(
            capacityCleanupWait: focusComposer
                ? .deferEligibleInactiveAutoStashCleanup
                : .awaitCompletion,
            prepareBeforeActivation: { [weak self] tabID, agentSessionID in
                guard let self,
                      persistenceWorkspace?.id == originatingWorkspaceID,
                      sessionIndexOwner == originatingOwner,
                      let session = prepareFreshSessionForActivation(
                          tabID: tabID,
                          agentSessionID: agentSessionID,
                          profile: requestedProfile,
                          selection: selection,
                          knowledgeAgents: knowledgeAgents
                      )
                else { return false }
                preparedSession = session
                return true
            }
        ),
            let session = preparedSession,
            session.tabID == tabID,
            persistenceWorkspace?.id == originatingWorkspaceID,
            sessionIndexOwner == originatingOwner,
            currentTabID == tabID,
            sessions[tabID] === session
        else { return nil }

        updateBindingsFromSession(session)
        syncAllActiveUIState()
        if focusComposer {
            ui.composer.requestFocus(
                AgentComposerFocusRequest(
                    id: UUID(),
                    tabID: tabID,
                    reason: requestedProfile == .knowledge ? .newKnowledgeSession : .newSession
                )
            )
        }

        if shouldClosePriorPlaceholder,
           let priorTabID,
           priorTabID != tabID
        {
            await deleteSession(tabID: priorTabID)
        }
        return tabID
    }

    // MARK: - Session Handoff

    /// Whether the current tab has enough transcript to be worth handing off.
    var canForkCurrentSession: Bool {
        guard let tabID = currentTabID,
              let session = sessions[tabID] else { return false }
        return canForkSession(session)
    }

    func canForkSession(_ session: AgentTabSession) -> Bool {
        if session.remoteHost != nil {
            return remoteCoordinator.canForkRemoteSession(session: session)
        }
        if session.transcript.turns.contains(where: { $0.request != nil }) {
            return true
        }
        return session.items.contains(where: { $0.kind == .user || $0.kind == .assistant || $0.kind == .assistantInline })
    }

    /// Build the handoff payload string for a given item cutoff (used for clipboard copy and handoff).
    @MainActor
    func buildHandoffPayload(upToItemID: UUID?) async -> String {
        guard let sourceTabID = currentTabID else { return "" }
        do {
            return try await buildHandoffPayload(
                sourceTabID: sourceTabID,
                upToItemID: upToItemID
            )
        } catch {
            return ""
        }
    }

    @MainActor
    func buildHandoffPayload(
        sourceTabID: UUID,
        upToItemID: UUID?
    ) async throws -> String {
        guard let sourceSession = sessions[sourceTabID] else {
            throw AgentHandoffConfigurationError.sourceUnavailable
        }
        guard let sourceTranscript = resolvedHandoffSourceTranscript(
            for: sourceSession,
            upToItemID: upToItemID
        ) else {
            throw AgentSessionError.invalidHandoffCutoff
        }

        return await buildHandoffPayload(
            sourceTabID: sourceTabID,
            sourceSession: sourceSession,
            sourceTranscript: sourceTranscript,
            upToItemID: upToItemID
        )
    }

    @MainActor
    private func buildHandoffPayload(
        sourceTabID: UUID,
        sourceSession: AgentTabSession,
        sourceTranscript: AgentTranscript,
        upToItemID: UUID?,
        oracleChatIDMapping: OracleViewModel.HandoffChatIDMapping = .empty
    ) async -> String {
        guard let workspaceManager else { return "" }

        if sourceTabID == currentTabID {
            workspaceManager.publishActiveComposeTabSnapshot(commitToMemory: true)
        }
        let sourceSelection = workspaceManager.composeTab(with: sourceTabID)?.selection ?? StoredSelection()
        let sourceTabName = workspaceManager.composeTabName(with: sourceTabID) ?? "Session"
        let sourceAgentName = sourceSession.selectedAgent.displayName
        let sourceModelName = modelDisplayName(
            rawModel: sourceSession.selectedModelRaw,
            agentKind: sourceSession.selectedAgent
        )
        let payloadTranscript = Self.rewritingStructuredHandoffChatIDs(
            in: sourceTranscript,
            replacements: oracleChatIDMapping.replacements
        )
        let transcriptXML = buildForkTranscriptXML(from: payloadTranscript, upToItemID: upToItemID)
        let lookupContext = await agentWorkspaceLookupContext(tabID: sourceTabID, session: sourceSession)
        let fileContentsBlock = await buildForkFileContentsBlock(
            selection: sourceSelection,
            tokenCap: 60000,
            lookupContext: lookupContext
        )
        // delivery_id makes crash/restart retries best-effort idempotent at the prompt level.
        let deliveryID = UUID().uuidString

        return Self.composeSessionHandoffPayload(
            sourceTabName: sourceTabName,
            sourceAgentName: sourceAgentName,
            sourceModelName: sourceModelName,
            fileContentsBlock: fileContentsBlock,
            transcriptXML: transcriptXML,
            deliveryID: deliveryID,
            oracleChatIDMappingRows: oracleChatIDMapping.rows
        )
    }

    private static func rewritingStructuredHandoffChatIDs(
        in source: AgentTranscript,
        replacements: [String: String]
    ) -> AgentTranscript {
        guard !replacements.isEmpty else { return source }

        var transcript = source
        for turnIndex in transcript.turns.indices {
            for spanIndex in transcript.turns[turnIndex].responseSpans.indices {
                for activityIndex in transcript.turns[turnIndex].responseSpans[spanIndex].activities.indices {
                    guard var execution = transcript.turns[turnIndex]
                        .responseSpans[spanIndex]
                        .activities[activityIndex]
                        .toolExecution
                    else { continue }

                    execution.argsJSON = rewritingStructuredHandoffChatIDs(
                        in: execution.argsJSON,
                        replacements: replacements
                    )
                    execution.resultJSON = rewritingStructuredHandoffChatIDs(
                        in: execution.resultJSON,
                        replacements: replacements
                    )
                    transcript.turns[turnIndex]
                        .responseSpans[spanIndex]
                        .activities[activityIndex]
                        .toolExecution = execution
                }
            }
        }
        return transcript
    }

    private static func rewritingStructuredHandoffChatIDs(
        in rawJSON: String?,
        replacements: [String: String]
    ) -> String? {
        guard let rawJSON,
              let data = rawJSON.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data, options: .fragmentsAllowed)
        else { return rawJSON }

        func rewrite(_ value: Any) -> (value: Any, changed: Bool) {
            if let string = value as? String {
                if let replacement = replacements[string] {
                    return (replacement, true)
                }
                if let uuid = UUID(uuidString: string),
                   let replacement = replacements[uuid.uuidString]
                {
                    return (replacement, true)
                }
                return (string, false)
            }
            if let array = value as? [Any] {
                var changed = false
                let rewritten = array.map { element -> Any in
                    let result = rewrite(element)
                    changed = changed || result.changed
                    return result.value
                }
                return (rewritten, changed)
            }
            if let dictionary = value as? [String: Any] {
                var changed = false
                var rewritten: [String: Any] = [:]
                for (key, element) in dictionary {
                    let result = rewrite(element)
                    changed = changed || result.changed
                    rewritten[key] = result.value
                }
                return (rewritten, changed)
            }
            return (value, false)
        }

        let rewritten = rewrite(object)
        guard rewritten.changed,
              let output = try? JSONSerialization.data(
                  withJSONObject: rewritten.value,
                  options: [.fragmentsAllowed, .sortedKeys, .withoutEscapingSlashes]
              )
        else { return rawJSON }
        return String(data: output, encoding: .utf8) ?? rawJSON
    }

    /// Build the file-contents block used by handoff payload export for the current active tab.
    /// This intentionally snapshots only the current tab selection, matching the in-app handoff path.
    @MainActor
    func buildCurrentTabHandoffFileContentsBlock(
        tokenCap: Int = 60000,
        overTokenCapSummaryWillBegin: (() async -> Void)? = nil
    ) async -> String {
        guard let workspaceManager,
              let sourceTabID = currentTabID else { return "" }
        workspaceManager.publishActiveComposeTabSnapshot(commitToMemory: true)
        let sourceSelection = workspaceManager.composeTab(with: sourceTabID)?.selection ?? StoredSelection()
        let lookupContext = await agentWorkspaceLookupContext(tabID: sourceTabID, session: sessions[sourceTabID])
        return await buildForkFileContentsBlock(
            selection: sourceSelection,
            tokenCap: tokenCap,
            lookupContext: lookupContext,
            overTokenCapSummaryWillBegin: overTokenCapSummaryWillBegin
        )
    }

    /// Resolves the authoritative transcript used for handoff payloads and destination
    /// migration. Prefer the structured transcript because historical/compacted rows
    /// can be absent from the mutable `items` suffix.
    @MainActor
    func resolvedHandoffSourceTranscript(
        for session: AgentTabSession,
        upToItemID: UUID?
    ) -> AgentTranscript? {
        // Settle a background-delayed refresh before reading the derived transcript.
        flushDeferredDerivedTranscriptRefresh(for: session)
        let hasStructuredTranscript = !session.transcript.turns.isEmpty

        if let upToItemID {
            if hasStructuredTranscript {
                return AgentTranscriptIO.isValidHandoffExportCutoffRowID(upToItemID, in: session.transcript)
                    ? session.transcript
                    : nil
            }

            let itemTranscript = AgentTranscriptIO.handoffTranscript(fromLegacyItems: session.items)
            if AgentTranscriptIO.isValidHandoffExportCutoffRowID(upToItemID, in: itemTranscript) {
                return itemTranscript
            }

            return nil
        }

        if !hasStructuredTranscript, !session.items.isEmpty {
            return AgentTranscriptIO.handoffTranscript(fromLegacyItems: session.items)
        }

        return session.transcript
    }

    /// Build transcript items for the destination session (copies through `upToItemID`,
    /// or the full transcript when no cutoff is supplied; forces streaming off and drops thinking items).
    @MainActor
    func buildHandoffTranscriptItems(
        sourceTranscript: AgentTranscript,
        upToItemID: UUID?
    ) -> [AgentChatItem] {
        AgentTranscriptIO.buildHandoffTranscriptItems(from: sourceTranscript, upToRowID: upToItemID)
    }

    /// Compatibility helper for legacy callers/tests that only have live items.
    @MainActor
    func buildHandoffTranscriptItems(
        sourceItems: [AgentChatItem],
        upToItemID: UUID
    ) -> [AgentChatItem] {
        buildHandoffTranscriptItems(
            sourceTranscript: AgentTranscriptIO.handoffTranscript(fromLegacyItems: sourceItems),
            upToItemID: upToItemID
        )
    }

    /// Prepare a handoff fork without changing the foreground compose tab or active bindings.
    /// The source is explicitly addressed so MCP callers can fork any live session in the window.
    /// A nil cutoff migrates and exports the full transcript.
    ///
    /// - Returns: The background destination tab ID on success.
    @MainActor
    @discardableResult
    func prepareHandoffHeadless(
        sourceTabID: UUID,
        upToItemID: UUID?,
        destinationAgent: AgentProviderKind,
        destinationModelRaw: String,
        destinationReasoningEffortRaw: String?,
        destinationOhMyPiThinkingSelections: OhMyPiThinkingSelections = .empty,
        delegationParentSessionID: UUID? = nil,
        delegationCommitCheck: () throws -> Void = {}
    ) async throws -> UUID {
        guard let promptManager,
              let workspaceManager
        else {
            throw AgentSessionError.noActiveWorkspace
        }
        guard let sourceSession = sessions[sourceTabID] else {
            throw AgentSessionError.emptySession
        }
        guard let sourceAgentModeSessionID = sourceSession.activeAgentSessionID else {
            throw MCPError.invalidParams(
                "Handoff requires a durable source Agent Mode session identity"
            )
        }

        if let remoteReason = localSessionMutationDisabledReason(for: sourceSession) {
            throw AgentSessionError.remoteManaged(remoteReason)
        }

        guard let sourceTranscript = resolvedHandoffSourceTranscript(
            for: sourceSession,
            upToItemID: upToItemID
        ) else {
            throw AgentSessionError.invalidHandoffCutoff
        }
        if sourceSession.profile == .knowledge,
           !KnowledgeSessionPolicy.supportedProviders.contains(destinationAgent)
        {
            throw MCPError.invalidParams(
                "Knowledge handoffs currently support Claude Code and Codex destinations only."
            )
        }

        // 1) Resolve the transcript copy once, before any destination-side mutation.
        let sourceTabName = workspaceManager.composeTabName(with: sourceTabID) ?? "Session"
        let migratedItems = buildHandoffTranscriptItems(
            sourceTranscript: sourceTranscript,
            upToItemID: upToItemID
        )

        // 2) Create a fork-duplicate tab in the background (copies selection, prompt,
        //    expansions, overrides, discover config, etc. but clears session bindings).
        guard let destTab = await promptManager.createBackgroundForkComposeTab(
            sourceTabID: sourceTabID,
            named: "\(sourceTabName) (handoff)"
        ) else {
            throw AgentSessionError.emptySession
        }
        let destTabID = destTab.id

        // 3) Pre-allocate the durable destination Agent Mode identity before any Oracle
        //    clone can be persisted or published.
        guard let destSession = session(for: destTabID, createIfNeeded: true) else {
            await promptManager.closeComposeTab(destTabID)
            throw SessionAccessError.tabUnavailable(tabID: destTabID)
        }
        guard destSession.adoptSessionProfile(sourceSession.profile) else {
            await promptManager.closeComposeTab(destTabID)
            throw PersistentBindingMutationError.staleTransition
        }
        destSession.selectedAgent = destinationAgent
        destSession.selectedModelRaw = destinationModelRaw
        destSession.selectedReasoningEffortRaw = destinationReasoningEffortRaw
        destSession.ohMyPiThinkingSelections = destinationAgent == .ohMyPi
            ? destinationOhMyPiThinkingSelections
            : .empty
        destSession.autoEditEnabled = sourceSession.autoEditEnabled
        guard let destinationAgentModeSessionID = ensureSessionBoundToTab(destSession) else {
            await promptManager.closeComposeTab(destTabID)
            throw PersistentBindingMutationError.staleTransition
        }
        // Branches never inherit source accounting; the destination starts its own identity.
        destSession.replaceUsageAccounting(nil)
        // MCP forks re-check the requester and destination placement after the suspensions above,
        // then record delegation lineage on the durable identity before any Oracle clone or
        // payload is published. UI handoffs pass nil and stay parentless.
        do {
            try delegationCommitCheck()
        } catch {
            await promptManager.closeComposeTab(destTabID)
            throw error
        }
        if let delegationParentSessionID {
            applySpawnParentSessionID(
                delegationParentSessionID,
                to: destSession,
                inheritWorktreeBindings: false
            )
            guard destSession.parentSessionID == delegationParentSessionID else {
                await promptManager.closeComposeTab(destTabID)
                throw PersistentBindingMutationError.staleTransition
            }
        }

        // 4) Clone only Oracle/chat sessions owned by the source Agent Mode session.
        //    The run ID stays nil until the destination's first explicit continuation.
        var oracleChatIDMapping = OracleViewModel.HandoffChatIDMapping.empty
        if let oracleViewModel {
            do {
                let idMapping = try await oracleViewModel.cloneChatSessions(
                    fromTabID: sourceTabID,
                    toTabID: destTabID,
                    sourceAgentModeSessionID: sourceAgentModeSessionID,
                    destinationAgentModeSessionID: destinationAgentModeSessionID
                )
                oracleChatIDMapping = oracleViewModel.handoffChatIDMapping(
                    for: idMapping,
                    destinationTabID: destTabID
                )
            } catch {
                await promptManager.closeComposeTab(destTabID)
                throw error
            }
        }

        // 5) Build the payload only after cloning so structured chat IDs can point at the
        //    destination clones and prose can carry an explicit old → new table.
        let payload = await buildHandoffPayload(
            sourceTabID: sourceTabID,
            sourceSession: sourceSession,
            sourceTranscript: sourceTranscript,
            upToItemID: upToItemID,
            oracleChatIDMapping: oracleChatIDMapping
        )

        // 6) Install the migrated transcript and deferred payload, then persist the mapping.
        destSession.replaceItems(migratedItems)
        refreshDerivedTranscriptState(for: destSession)
        destSession.hasSentFirstMessage = migratedItems.contains { $0.kind == .user }
        destSession.pendingHandoff = AgentPendingHandoffState(
            payload: payload,
            createdAt: Date(),
            sourceItemID: upToItemID,
            payloadID: UUID(),
            defersProviderLockUntilSend: true,
            isStagedForSend: false
        )
        scheduleSave(for: destTabID)
        return destTabID
    }

    /// Handoff the current session to a new tab, then foreground the prepared destination.
    @MainActor
    @discardableResult
    func prepareHandoffToNewTab(
        upToItemID: UUID,
        destinationAgent: AgentProviderKind,
        destinationModelRaw: String,
        destinationReasoningEffortRaw: String?,
        destinationOhMyPiThinkingSelections: OhMyPiThinkingSelections = .empty
    ) async throws -> UUID {
        guard let sourceTabID = currentTabID else {
            throw AgentSessionError.noActiveWorkspace
        }
        return try await prepareHandoffToNewTab(
            sourceTabID: sourceTabID,
            upToItemID: upToItemID,
            destinationAgent: destinationAgent,
            destinationModelRaw: destinationModelRaw,
            destinationReasoningEffortRaw: destinationReasoningEffortRaw,
            destinationOhMyPiThinkingSelections: destinationOhMyPiThinkingSelections
        )
    }

    /// Source-addressed foreground handoff used by UI actions that pin their source at presentation.
    @MainActor
    @discardableResult
    func prepareHandoffToNewTab(
        sourceTabID: UUID,
        upToItemID: UUID,
        destinationAgent: AgentProviderKind,
        destinationModelRaw: String,
        destinationReasoningEffortRaw: String?,
        destinationOhMyPiThinkingSelections: OhMyPiThinkingSelections = .empty
    ) async throws -> UUID {
        guard let promptManager,
              let workspaceManager
        else {
            throw AgentSessionError.noActiveWorkspace
        }

        let destTabID = try await prepareHandoffHeadless(
            sourceTabID: sourceTabID,
            upToItemID: upToItemID,
            destinationAgent: destinationAgent,
            destinationModelRaw: destinationModelRaw,
            destinationReasoningEffortRaw: destinationReasoningEffortRaw,
            destinationOhMyPiThinkingSelections: destinationOhMyPiThinkingSelections
        )
        let clonedActiveChatSessionID = workspaceManager.activeChatSessionID(forTabID: destTabID)
        guard let destSession = sessions[destTabID] else {
            throw AgentSessionError.emptySession
        }

        await promptManager.switchComposeTab(destTabID)
        if let oracleViewModel,
           let clonedActiveChatSessionID
        {
            await oracleViewModel.focusSession(clonedActiveChatSessionID, forTab: destTabID)
        }
        updateBindingsFromSession(destSession)
        return destTabID
    }

    /// Builds a handoff transcript XML from the resolved source transcript using the shared
    /// priority-based budgeting policy from `AgentTranscriptIO.buildForkTranscriptXML`.
    /// Tool calls are dropped first, then intermediate assistant narration, then
    /// system/error context, and finally whole oldest essential turns if needed.
    private func buildForkTranscriptXML(
        from transcript: AgentTranscript,
        upToItemID: UUID? = nil,
        maxTranscriptItems: Int = 200,
        maxToolArgsCharacters: Int = 2000
    ) -> String {
        AgentTranscriptIO.buildForkTranscriptXML(
            from: transcript,
            upToRowID: upToItemID,
            maxTranscriptItems: maxTranscriptItems,
            maxToolArgsCharacters: maxToolArgsCharacters
        )
    }

    /// Compatibility wrapper for callers with a session; resolves historical rows against
    /// the structured transcript rather than the mutable working suffix.
    private func buildForkTranscriptXML(
        from source: AgentTabSession,
        upToItemID: UUID? = nil,
        maxTranscriptItems: Int = 200,
        maxToolArgsCharacters: Int = 2000
    ) -> String {
        guard let transcript = resolvedHandoffSourceTranscript(for: source, upToItemID: upToItemID) else {
            return AgentTranscriptIO.buildForkTranscriptXML(
                from: .empty,
                upToRowID: nil,
                maxTranscriptItems: maxTranscriptItems,
                maxToolArgsCharacters: maxToolArgsCharacters
            )
        }
        return buildForkTranscriptXML(
            from: transcript,
            upToItemID: upToItemID,
            maxTranscriptItems: maxTranscriptItems,
            maxToolArgsCharacters: maxToolArgsCharacters
        )
    }

    /// Builds the file contents block for the fork payload.
    /// If the selection token count exceeds the cap, falls back to the formatted
    /// selection reply summary (same format as the manage_selection tool response).
    @MainActor
    private func buildForkFileContentsBlock(
        selection: StoredSelection,
        tokenCap: Int,
        lookupContext: WorkspaceLookupContext,
        overTokenCapSummaryWillBegin: (() async -> Void)? = nil
    ) async -> String {
        guard let promptManager else { return "" }
        let tokenCounter = promptManager.tokenCountingViewModel
        tokenCounter.suspendAutomaticRecounts()
        defer { tokenCounter.resumeAutomaticRecounts() }

        return await AgentProviderContextBuilder.forkFileContentsBlock(
            selection: selection,
            tokenCap: tokenCap,
            store: promptManager.workspaceFileContextStore,
            lookupContext: lookupContext,
            overTokenCapSummaryProvider: { [weak self] selection, lookupContext, presentation in
                guard let self, let mcp = mcpServer else { return nil }
                let reply = await mcp.buildBorrowedTabSelectionReply(
                    codemapPresentation: presentation,
                    from: selection,
                    includeBlocks: false,
                    display: .relative,
                    lookupContext: lookupContext
                )
                let summary = ToolOutputFormatter.formatSelectionReplyToString(reply)
                return """
                <selection_summary>
                \(summary)
                </selection_summary>
                """
            },
            overTokenCapSummaryWillBegin: overTokenCapSummaryWillBegin
        )
    }
}

// MARK: - AgentWorkspaceSessionIndexStoreDelegate

@MainActor
extension AgentModeViewModel: AgentWorkspaceSessionIndexStoreDelegate {
    var activeWorkspaceIDForSessionIndexOwnership: UUID? {
        #if DEBUG
            if let test_activeWorkspaceIDForSessionIndexOverride {
                return test_activeWorkspaceIDForSessionIndexOverride
            }
        #endif
        return workspaceManager?.activeWorkspaceID ?? lastKnownWorkspaceSnapshot?.id
    }

    var activeWorkspaceIDForWorkspaceUnloadValidation: UUID? {
        workspaceManager?.activeWorkspaceID
    }

    var enforcesActiveWorkspaceIDForSessionIndexOwnership: Bool {
        #if DEBUG
            if test_activeWorkspaceIDForSessionIndexOverride != nil {
                return true
            }
        #endif
        return workspaceManager != nil
    }

    /// Must derive only from the `workspace` argument; it runs before `installOwner` clears store state.
    func makeSidebarRestoreFrozenOrder(for workspace: WorkspaceModel) -> [UUID: Int] {
        var orderByTabID: [UUID: Int] = [:]
        for (index, tab) in persistedSidebarTabs(for: workspace).enumerated() where orderByTabID[tab.id] == nil {
            orderByTabID[tab.id] = index
        }
        return orderByTabID
    }

    func sessionIndexStore(
        _ store: AgentWorkspaceSessionIndexStore,
        didChangeStateWithReason reason: SessionIndexStateChangeReason
    ) {
        switch reason {
        case .sessionIndex:
            syncSidebarUIState(refresh: true, reason: .sessionIndex)
            scheduleSidebarAutoArchiveIfReady(reason: .sessionIndexChanged)
        case .sortDates:
            syncSidebarUIState(refresh: true, reason: .sortDates)
        case .sessionList:
            syncSidebarUIState(refresh: true, reason: .sessionList)
        }
    }
}

// MARK: - WorkspaceSwitchSessionProviderDelegate

@MainActor
extension AgentModeViewModel: WorkspaceSwitchSessionProviderDelegate {
    func teardownMCPControlForDiscardedSession(
        _ session: AgentTabSession,
        cleanupSessionStore: Bool,
        publishChanges: Bool,
        deactivateLiveControlContext: Bool
    ) async {
        await teardownMCPControl(
            for: session,
            cleanupSessionStore: cleanupSessionStore,
            publishChanges: publishChanges,
            deactivateLiveControlContext: deactivateLiveControlContext
        )
    }

    func cleanupMCPRunRoutingForDiscardedSession(
        boundSessionID: UUID?,
        liveSession: AgentTabSession,
        explicitRunID: UUID?,
        reason: String
    ) async {
        await cleanupMCPRunRoutingIfPresent(
            boundSessionID: boundSessionID,
            liveSession: liveSession,
            explicitRunID: explicitRunID,
            reason: reason
        )
    }
}
